var QUESTOES_INTERVENCAO_ESTADO_PROPRIEDADE = [{"id":4148530,"enunciado":"Suponha que determinada empresa, contratada por um Município para realizar a pavimentação de uma estrada vicinal, tenha paralisado injustificadamente os serviços e abandonado o canteiro de obras. Visando evitar o isolamento da comunidade rural e a deterioração do patrimônio público, a Prefeitura assumiu imediatamente a execução direta das obras pendentes, alocando servidores públicos de seu quadro técnico com atribuições compatíveis para operar o maquinário e dar continuidade ao projeto até que ocorra a rescisão formal do contrato e a convocação do próximo licitante. Considerando as medidas de intervenção do Estado no prejuízo das prerrogativas administrativas, o procedimento emergencial caracterizado pela utilização transitória de bens particulares e serviços ligados ao contrato em face do interesse público configura:","opcoes":["Desapropriação indireta.","Limitação administrativa.","Ocupação temporária.","Servidão administrativa."],"correta":2,"explicacao":"Gabarito: <strong>Ocupação temporária.</strong>.","banca":"Instituto Legalle","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Desapropriação indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"Limitação administrativa","ancora":"limitacao-administrativa"},"C":{"topico":"Ocupação temporária","ancora":"ocupacao-temporaria"},"D":{"topico":"Servidão administrativa","ancora":"servidao-administrativa"}}},{"id":4150700,"enunciado":"O Estado de Santa Catarina pretende desapropriar o imóvel de titularidade de João, com o objetivo de construir, no local, um hospital púbico. Em assim sendo, o Poder Público, em observância às formalidades legais, notificou o proprietário e apresentou-lhe oferta de indenização. Nesse cenário, considerando as disposições do Decreto-Lei nº 3.365/1941, é correto afirmar que a referida notificação conterá a","opcoes":["cópia do ato de declaração de utilidade pública; a planta ou descrição do bem e suas confrontações; o valor da oferta; e a informação de que o prazo para aceitá-la ou rejeitá-la é de quinze dias e de que o silêncio será considerado aceitação.","cópia do ato de declaração de utilidade pública; a planta ou descrição do bem e suas confrontações; o valor da oferta; e a informação de que o prazo para aceitá-la ou rejeitá-la é de quinze dias e de que o silêncio será considerado rejeição.","cópia do ato de declaração de utilidade pública; a planta ou descrição do bem e suas confrontações; o valor da oferta; e a informação de que o prazo para aceitá-la ou rejeitá-la é de trinta dias e de que o silêncio será considerado rejeição.","a planta ou descrição do bem e suas confrontações; o valor da oferta; e a informação de que o prazo para aceitá-la ou rejeitá-la é de trinta dias e de que o silêncio será considerado aceitação.","o valor da oferta; e a informação de que o prazo para aceitá-la ou rejeitá-la é de quinze dias e de que o silêncio será considerado aceitação."],"correta":1,"explicacao":"Gabarito: <strong>cópia do ato de declaração de utilidade pública; a planta ou descrição do bem e suas confrontações; o valor da oferta; e a informação de que o prazo para aceitá-la ou rejeitá-la é de quinze dias e de que o silêncio será considerado rejeição.</strong>.","banca":"FGV","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"notificacao oferta indenizacao","ancora":"notificacao-oferta-indenizacao"},"B":{"topico":"notificacao oferta indenizacao","ancora":"notificacao-oferta-indenizacao"},"C":{"topico":"notificacao oferta indenizacao","ancora":"notificacao-oferta-indenizacao"},"D":{"topico":"notificacao oferta indenizacao","ancora":"notificacao-oferta-indenizacao"},"E":{"topico":"notificacao oferta indenizacao","ancora":"notificacao-oferta-indenizacao"}}},{"id":4160972,"enunciado":"O Município de Cianorte editou decreto declarando de utilidade pública determinado imóvel urbano particular para construção de nova unidade básica de saúde. Na sequência, promoveu a incorporação definitiva do imóvel ao patrimônio público municipal e iniciou a execução das obras, sem realizar previamente o pagamento de indenização ao proprietário, informando que eventual compensação financeira seria apurada e quitada apenas ao término do empreendimento público. Inconformado, o proprietário questionou a constitucionalidade da medida adotada pelo Município. Considerando o que preconiza a Constituição Federal e as demais disposições legais aplicáveis ao tema, assinale a alternativa CORRETA.","opcoes":["A Administração Municipal agiu incorretamente, pois a desapropriação por necessidade ou utilidade pública, ou por interesse social, exige justa e prévia indenização em dinheiro.","A Administração Municipal agiu corretamente, pois a indenização poderá ser paga posteriormente quando a desapropriação envolver implementação de política pública essencial.","A Administração Municipal agiu corretamente, pois imóveis urbanos destinados à execução de políticas públicas municipais submetem-se à desapropriação independentemente de indenização prévia.","A Administração Municipal agiu incorretamente apenas porque a construção de unidade básica de saúde depende de autorização legislativa específica para decretação da utilidade pública.","A Administração Municipal agiu corretamente, pois a desapropriação por utilidade pública autoriza incorporação definitiva do imóvel ao patrimônio público antes do pagamento da indenização."],"correta":0,"explicacao":"Gabarito: <strong>A Administração Municipal agiu incorretamente, pois a desapropriação por necessidade ou utilidade pública, ou por interesse social, exige justa e prévia indenização em dinheiro.</strong>.","banca":"FAFIPA","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4179172,"enunciado":"Relacione corretamente a modalidade de intervenção do Estado, presente na Coluna 1, na propriedade com a situação fática ocorrida em um consórcio intermunicipal de saúde, disposto na Coluna 2, de acordo com o Direito Administrativo e com o Código Civil: Coluna 1: 1) Ocupação Temporária. 2) Servidão Administrativa. 3) Limitação Administrativa. Coluna 2: ( ) O consórcio institui o direito de passagem de tubulações de oxigênio hospitalar subterrâneas em terreno vizinho privado, em caráter permanente, mediante registro imobiliário. ( ) O Município onde fica a sede do consórcio proíbe a construção de edifícios com mais de três andares no entorno do heliponto do hospital de pronto-socorro administrado pelo consórcio. ( ) O consórcio utiliza terreno privado vizinho, desprovido de edificações, para o canteíro de obras e depósito de areia durante a reforma da ala de urgência, pelo prazo de três meses. Qual alternativa preenche, CORRETAMENTE, de cima para baixo, os parênteses acima?","opcoes":["2 - 3 - 1.","1 - 2 - 3.","3 - 1 - 2.","2 - 1 - 3."],"correta":0,"explicacao":"Gabarito: <strong>2 - 3 - 1.</strong>.","banca":"LEGALLE Concursos","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"1":{"topico":"Ocupação temporária","ancora":"ocupacao-temporaria"},"2":{"topico":"Servidão administrativa","ancora":"servidao-administrativa"},"3":{"topico":"Limitação administrativa","ancora":"limitacao-administrativa"}}},{"id":4179790,"enunciado":"No contexto de implementação de infraestrutura logística, uma autarquia federal promoveu a ocupação de extensa área privada para viabilizar a execução de obra pública, sem a prévia instauração de procedimento expropriatório nem o pagamento de indenização. A área passou a ser utilizada de forma contínua e irreversível, com incorporação física ao empreendimento público. Anos depois, o proprietário ajuizou demanda judicial visando à reparação pelos prejuízos sofridos, alegando esvaziamento total de seu direito de propriedade. À luz do regime jurídico da desapropriação e da proteção constitucional à propriedade, assinale a afirmativa correta.","opcoes":["A hipótese caracteriza desapropriação indireta, sendo devida indenização ao proprietário, em regra correspondente ao valor do bem, ainda que ausente procedimento formal prévio.","A situação configura mera limitação administrativa, não sendo devida indenização, uma vez que a atuação estatal atendeu ao interesse público e não houve formal decretação de desapropriação.","A ausência de prévio procedimento expropriatório impede o reconhecimento de qualquer forma de desapropriação, restando ao particular pleitear perdas e danos limitados ao uso temporário do bem.","A incorporação do bem ao patrimônio público sem observância do devido processo legal torna o ato inexistente, devendo o imóvel ser restituído ao particular, independentemente da situação fática consolidada."],"correta":0,"explicacao":"Gabarito: <strong>A hipótese caracteriza desapropriação indireta, sendo devida indenização ao proprietário, em regra correspondente ao valor do bem, ainda que ausente procedimento formal prévio.</strong>.","banca":"Instituto Consulplan","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4180605,"enunciado":"O Município de Foz do Iguaçu - PR desapropriou determinada área para a construção de um centro esportivo municipal. Após estudos técnicos realizados anos depois, constatou-se a inviabilidade da implantação do projeto originalmente previsto no decreto expropriatório. Diante dessa situação, a Administração Pública passou a analisar as providências cabíveis quanto à destinação do imóvel desapropriado. Considerando o disposto no Decreto-Lei nº 3.365/1941, assinale a alternativa INCORRETA.","opcoes":["Comprovada a inviabilidade ou a perda objetiva de interesse público em manter a destinação originalmente prevista, o expropriante deverá adotar medidas previstas em lei para a destinação do bem.","Na hipótese de alienação do imóvel, deverá ser assegurado direito de preferência à pessoa física ou jurídica desapropriada.","Caso não seja possível a destinação do imóvel para outra finalidade pública, poderá o bem ser alienado na forma prevista em lei.","A primeira providência a ser considerada pelo expropriante consiste na destinação da área não utilizada para outra finalidade pública.","Verificada a inviabilidade da finalidade originalmente prevista, o imóvel deverá ser obrigatoriamente restituído ao antigo proprietário, independentemente de interesse público superveniente ou da possibilidade de alienação."],"correta":4,"explicacao":"Gabarito: <strong>Verificada a inviabilidade da finalidade originalmente prevista, o imóvel deverá ser obrigatoriamente restituído ao antigo proprietário, independentemente de interesse público superveniente ou da possibilidade de alienação.</strong>.","banca":"FAFIPA","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"finalidade inviavel procedimento","ancora":"finalidade-inviavel-procedimento"},"B":{"topico":"finalidade inviavel procedimento","ancora":"finalidade-inviavel-procedimento"},"C":{"topico":"finalidade inviavel procedimento","ancora":"finalidade-inviavel-procedimento"},"D":{"topico":"finalidade inviavel procedimento","ancora":"finalidade-inviavel-procedimento"},"E":{"topico":"finalidade inviavel procedimento","ancora":"finalidade-inviavel-procedimento"}}},{"id":4181817,"enunciado":"Sobre a desapropriação por utilidade pública disciplinada pelo Decreto-Lei nº 3.365/1941 e sobre o regime jurídico dos bens públicos, assinale a alternativa correta:","opcoes":["Na desapropriação por utilidade pública, a contestação na ação judicial poderá versar livremente sobre qualquer matéria, inclusive sobre o mérito do interesse público que fundamentou o ato expropriatório.","Os bens públicos dominicais são imprescritíveis, mas, por não estarem afetados a uma finalidade pública específica, podem ser adquiridos por usucapião quando a posse do particular ultrapassar quinze anos.","A desapropriação indireta é o procedimento pelo qual a Administração, mediante prévio decreto e justa indenização, incorpora ao seu domínio bem imóvel particular, dispensada, nessa hipótese, a fase judicial.","Os bens de uso comum do povo e os de uso especial, enquanto conservarem essa qualificação, são inalienáveis, mas podem ser onerados por direitos reais de garantia, dada a sua expressão econômica.","Declarada a utilidade pública, ficam as autoridades administrativas autorizadas a penetrar nos prédios compreendidos na declaração, e a caducidade do decreto expropriatório opera-se em cinco anos, contados da sua expedição, somente podendo a declaração ser renovada decorrido um ano."],"correta":4,"explicacao":"Gabarito: <strong>Declarada a utilidade pública, ficam as autoridades administrativas autorizadas a penetrar nos prédios compreendidos na declaração, e a caducidade do decreto expropriatório opera-se em cinco anos, contados da sua expedição, somente podendo a declaração ser renovada decorrido um ano.</strong>.","banca":"Fundação La Salle","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Limites da matéria em juízo","ancora":"limite-materia-juizo"},"B":{"topico":"Regime jurídico dos bens públicos","ancora":"regime-bens-publicos"},"C":{"topico":"Desapropriação indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"Regime jurídico dos bens públicos","ancora":"regime-bens-publicos"},"E":{"topico":"Autorização para penetrar em prédios","ancora":"art7-penetrar-predios"}}},{"id":4183784,"enunciado":"Em janeiro de 2026, o Município de Flores da Cunha desapropriou um imóvel de um particular para a construção de um hospital. Ao tomar posse do imóvel, pagou à proprietária, imediatamente, o valor da avaliação inicial do bem. Contudo, durante o processo de desapropriação, verificou-se que o terreno tinha valor maior que o pago anteriormente, o que gerou a necessidade de complementação da indenização. Considerando a situação narrada e apenas a jurisprudência do STF a respeito da matéria, assinale a alternativa correta.","opcoes":["Em casos como o narrado acima, o valor a ser pago pelo Município de Flores da Cunha será sempre feito por precatório.","No caso de necessidade de complementação da indenização, ao final do processo expropriatório, deverá o pagamento ser feito mediante depósito judicial direto se o Poder Público não estiver em dia com os precatórios.","Em casos como o narrado acima, o valor a ser pago pelo Município de Flores da Cunha será sempre feito em dinheiro.","Caberá ao particular comprovar a situação de inadimplência com o pagamento dos precatórios na data do trânsito em julgado da decisão de mérito da ação de desapropriação."],"correta":1,"explicacao":"Gabarito: <strong>No caso de necessidade de complementação da indenização, ao final do processo expropriatório, deverá o pagamento ser feito mediante depósito judicial direto se o Poder Público não estiver em dia com os precatórios.</strong>.","banca":"FUNDATEC","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"stf tema 831 precatorios","ancora":"stf-tema-831-precatorios"},"B":{"topico":"stf tema 831 precatorios","ancora":"stf-tema-831-precatorios"},"C":{"topico":"stf tema 831 precatorios","ancora":"stf-tema-831-precatorios"},"D":{"topico":"stf tema 831 precatorios","ancora":"stf-tema-831-precatorios"}}},{"id":4187252,"enunciado":"Não é permitido às entidades públicas promover desapropriações para fins de utilidade pública.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"distincao instrumentos intervencao","ancora":"distincao-instrumentos-intervencao"},"E":{"topico":"distincao instrumentos intervencao","ancora":"distincao-instrumentos-intervencao"}}},{"id":4187254,"enunciado":"A realização de desapropriação na situação hipotética configura-se como um caso de desapropriação por interesse social.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4187255,"enunciado":"Em caso de falta de acordo acerca dos valores indenizatórios na situação de desapropriação, um juiz designará um perito para avaliação dos bens.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4187558,"enunciado":"O Município de Praia Grande declarou determinado imóvel de utilidade pública para implantação de equipamento público. Nos termos da Constituição da República, assinale a alternativa correta.","opcoes":["A indenização decorrente da desapropriação poderá ser paga por títulos da dívida pública em qualquer hipótese.","A desapropriação por necessidade ou utilidade pública, ou por interesse social, depende de justa e prévia indenização em dinheiro, ressalvadas as hipóteses previstas na própria Constituição.","A desapropriação por utilidade pública dispensa indenização quando demonstrado relevante interesse coletivo.","A declaração de utilidade pública transfere automaticamente a propriedade do imóvel ao Poder Público."],"correta":1,"explicacao":"Gabarito: <strong>A desapropriação por necessidade ou utilidade pública, ou por interesse social, depende de justa e prévia indenização em dinheiro, ressalvadas as hipóteses previstas na própria Constituição.</strong>.","banca":"IBAM","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Fundamentos constitucionais da desapropriação","ancora":"fundamentos-constitucionais-desapropriacao"},"B":{"topico":"Fundamentos constitucionais da desapropriação","ancora":"fundamentos-constitucionais-desapropriacao"},"C":{"topico":"Fundamentos constitucionais da desapropriação","ancora":"fundamentos-constitucionais-desapropriacao"},"D":{"topico":"Fundamentos constitucionais da desapropriação","ancora":"fundamentos-constitucionais-desapropriacao"}}},{"id":4196266,"enunciado":"No centro histórico do Município, um casarão particular foi tombado por sua relevância arquitetônica e por integrar conjunto urbano protegido. O proprietário, alegando alto custo de manutenção e interesse em construir estacionamento, inicia demolição parcial sem autorização do órgão competente. A fiscalização embarga a obra e encaminha o caso à Procuradoria. Em sua defesa, o particular afirma que o tombamento retirou integralmente seu direito de propriedade e que, por isso, poderia demolir o imóvel ou exigir indenização imediata. O órgão cultural informa que o imóvel ainda pode ser utilizado para fins compatíveis, desde que preservadas fachada e volumetria, e que a demolição compromete a integridade do conjunto protegido. Considerando os efeitos jurídicos do tombamento e os limites de intervenção no bem protegido, assinale a alternativa CORRETA.","opcoes":["O tombamento incorpora o imóvel ao domínio municipal e permite demolição por decisão administrativa.","A indenização decorre do tombamento quando houver limitação administrativa ao uso do imóvel.","O tombamento restringe o uso, preserva o domínio privado e exige autorização para demolição ou alteração.","O custo elevado de conservação autoriza demolição, desde que o proprietário comunique o órgão cultural."],"correta":2,"explicacao":"Gabarito: <strong>O tombamento restringe o uso, preserva o domínio privado e exige autorização para demolição ou alteração.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"B":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"C":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"D":{"topico":"tombamento conceito","ancora":"tombamento-conceito"}}},{"id":4205651,"enunciado":"O Município de Iretama identificou a necessidade de desapropriar determinado imóvel urbano abandonado, localizado em área densamente povoada, para implantação de unidade destinada ao controle de zoonoses e à execução de ações voltadas à prevenção de doenças transmissíveis. Em parecer jurídico, discutiu-se a existência de fundamento legal para a declaração de utilidade pública do imóvel. Considerando o disposto no art. 5º, alínea \"d\", do Decreto-Lei nº 3.365/1941, assinale a alternativa CORRETA.","opcoes":["A salubridade pública constitui fundamento exclusivo para a imposição de limitações administrativas, sendo vedada sua utilização como fundamento para desapropriação.","A salubridade pública constitui hipótese legal de utilidade pública apta a fundamentar a desapropriação de imóvel pelo Poder Público.","A salubridade pública constitui hipótese de interesse social, mas não de utilidade pública para fins de desapropriação.","A utilidade pública para fins de desapropriação exige necessariamente a existência de calamidade pública formalmente decretada.","A desapropriação por utilidade pública somente pode ocorrer para execução de obras viárias, não abrangendo medidas relacionadas à saúde coletiva."],"correta":1,"explicacao":"Gabarito: <strong>A salubridade pública constitui hipótese legal de utilidade pública apta a fundamentar a desapropriação de imóvel pelo Poder Público.</strong>.","banca":"FAFIPA","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"hipoteses utilidade publica","ancora":"hipoteses-utilidade-publica"},"B":{"topico":"hipoteses utilidade publica","ancora":"hipoteses-utilidade-publica"},"C":{"topico":"hipoteses utilidade publica","ancora":"hipoteses-utilidade-publica"},"D":{"topico":"hipoteses utilidade publica","ancora":"hipoteses-utilidade-publica"},"E":{"topico":"hipoteses utilidade publica","ancora":"hipoteses-utilidade-publica"}}},{"id":4205653,"enunciado":"Os Municípios integrantes de determinada região do Estado do Paraná decidiram constituir consórcio público para a gestão compartilhada de resíduos sólidos e de serviços ambientais. Durante a elaboração do protocolo de intenções, surgiram dúvidas sobre as competências e prerrogativas que podem ser atribuídas ao consórcio público nos termos da Lei nº 11.107/2005. A Procuradoria Jurídica do Município de Iretama foi consultada para esclarecer a questão. Considerando o disposto no art. 2º da Lei nº 11.107/2005, analise as assertivas a seguir. I. Os objetivos dos consórcios públicos serão determinados pelos entes da Federação que se consorciarem, observados os limites constitucionais. II. Para o cumprimento de seus objetivos, o consórcio público poderá firmar convênios, contratos e acordos de qualquer natureza, bem como receber auxílios, contribuições e subvenções sociais ou econômicas de outras entidades e órgãos do governo. III. Nos termos do contrato de consórcio de direito público, o consórcio poderá promover desapropriações e instituir servidões, observada a declaração de utilidade pública, necessidade pública ou interesse social realizada pelo Poder Público. IV. O consórcio público poderá ser contratado pela administração direta ou indireta dos entes federativos consorciados, dispensada a licitação. V. Os consórcios públicos somente poderão outorgar concessão, permissão ou autorização de obras ou serviços públicos mediante prévia autorização legislativa específica de cada ente consorciado, independentemente de previsão no contrato de consórcio público. Está CORRETO o que se afirma em:","opcoes":["II, III, IV e V, apenas.","I, II, III, IV e V.","I, III, IV e V, apenas.","I, II, III e IV, apenas.","I, II e III, apenas."],"correta":3,"explicacao":"Gabarito: <strong>I, II, III e IV, apenas.</strong>.","banca":"FAFIPA","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"consorcio publico art2","ancora":"consorcio-publico-art2"},"B":{"topico":"consorcio publico art2","ancora":"consorcio-publico-art2"},"C":{"topico":"consorcio publico art2","ancora":"consorcio-publico-art2"},"D":{"topico":"consorcio publico art2","ancora":"consorcio-publico-art2"},"E":{"topico":"consorcio publico art2","ancora":"consorcio-publico-art2"}}},{"id":4217014,"enunciado":"Constatando-se que uma vertente natural de água situada em um terreno particular na zona urbana transbordava para a via pública e sofria depreciação ambiental, o respectivo Município optou por transferir compulsoriamente a propriedade imobiliária para o patrimônio público, indenizando o proprietário e planejando implantar uma praça com o proposito de preservar a fonte. Considerando os meios de intervenção do Estado na propriedade, afirma-se CORRETAMENTE que a transferência da titularidade do imóvel para o poder público ocorreu por:","opcoes":["Desapropriação.","Servidão administrativa.","Limitação administrativa","Ocupação temporária."],"correta":0,"explicacao":"Gabarito: <strong>Desapropriação.</strong>.","banca":"LEGALLE Concursos","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Conceito e natureza jurídica da desapropriação","ancora":"conceito-desapropriacao"},"B":{"topico":"Servidão administrativa","ancora":"servidao-administrativa"},"C":{"topico":"Limitação administrativa","ancora":"limitacao-administrativa"},"D":{"topico":"Ocupação temporária","ancora":"ocupacao-temporaria"}}},{"id":4219594,"enunciado":"Leia a situação a seguir. Uma pintura do século XVIII, atribuída a um artista de destaque do período colonial, foi identificada em uma coleção particular durante a preparação de um leilão internacional. A obra, até então pouco conhecida, despertou o interesse de especialistas e foi submetida à análise técnica, sendo reconhecida por seu elevado valor histórico e artístico para o país. Diante do risco de sua saída definitiva do território nacional, o Instituto do Patrimônio Histórico e Artístico Nacional instaurou processo de tombamento com vistas à sua preservação, nos termos do Decreto-Lei nº 25/1937. O proprietário passou a questionar os efeitos jurídicos do tombamento sobre o uso, a circulação e a eventual alienação do bem. Considerando o caso descrito, assinale a opção que apresenta corretamente um efeito do tombamento.","opcoes":["O bem passa a integrar automaticamente o patrimônio da União, sendo vedada, em qualquer hipótese, sua saída do país.","O bem não pode ser objeto de qualquer forma de exploração econômica por seu proprietário, ainda que preservada sua titularidade.","O bem permanece sob a titularidade do proprietário, que fica obrigado à sua conservação, sendo necessária autorização do órgão competente para sua saída do país.","O bem perde o caráter de propriedade privada, tornando-se de uso coletivo, ainda que permaneça sob a guarda do proprietário, que deve permitir a visitação pública.","O bem pode ser utilizado pelo proprietário ou por terceiros, sendo vedada qualquer intervenção em sua materialidade, com o objetivo de preservar integralmente sua originalidade."],"correta":2,"explicacao":"Gabarito: <strong>O bem permanece sob a titularidade do proprietário, que fica obrigado à sua conservação, sendo necessária autorização do órgão competente para sua saída do país.</strong>.","banca":"FGV","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"art14 saida territorio","ancora":"art14-saida-territorio"},"B":{"topico":"art14 saida territorio","ancora":"art14-saida-territorio"},"C":{"topico":"art14 saida territorio","ancora":"art14-saida-territorio"},"D":{"topico":"art14 saida territorio","ancora":"art14-saida-territorio"},"E":{"topico":"art14 saida territorio","ancora":"art14-saida-territorio"}}},{"id":4220552,"enunciado":"Um Engenheiro Agrônomo do MPES elaborou a documentação para uma desapropriação, seguindo, rigorosamente, todas as normas técnicas e legais vigentes, sendo, portanto, “legal” em sua totalidade. O objetivo final da desapropriação é claramente favorecer uma sociedade empresária que possui laços pessoais com o próprio agrônomo, mesmo que o favorecimento esteja disfarçado sob uma cláusula técnica válida. Sobre a hipótese, assinale a opção que indica o princípio administrativo e a razão pela qual a conduta do agrônomo mostra uma falha primordial.","opcoes":["Legalidade, pois o ato criado viola a lei de concorrência.","Publicidade, pois a desapropriação não é transparente para o público em geral.","Pessoalidade, pois o agrônomo conhece o produtor que terá sua fazenda desapropriada.","Eficiência, pois o desenho da desapropriação é excessivamente complexo, dificultando a conferência.","Moralidade, pois a intenção subjacente do ato é gerar conflito de interesses, transcendendo o mero cumprimento formal da lei."],"correta":4,"explicacao":"Gabarito: <strong>Moralidade, pois a intenção subjacente do ato é gerar conflito de interesses, transcendendo o mero cumprimento formal da lei.</strong>.","banca":"FGV","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Moralidade na desapropriação","ancora":"moralidade-desapropriacao"},"B":{"topico":"Moralidade na desapropriação","ancora":"moralidade-desapropriacao"},"C":{"topico":"Moralidade na desapropriação","ancora":"moralidade-desapropriacao"},"D":{"topico":"Moralidade na desapropriação","ancora":"moralidade-desapropriacao"},"E":{"topico":"Moralidade na desapropriação","ancora":"moralidade-desapropriacao"}}},{"id":4230471,"enunciado":"Sobre a servidão administrativa, assinale a alternativa incorreta:","opcoes":["A servidão administrativa transfere a propriedade do imóvel para o Poder Público.","A servidão administrativa só gera direito à indenização quando houver efetivo prejuízo ao proprietário.","A servidão administrativa impõe um ônus real para atendimento do interesse público.","A servidão administrativa é uma forma de intervenção do Estado na propriedade privada.","A servidão administrativa recai sobre bem imóvel."],"correta":0,"explicacao":"Gabarito: <strong>A servidão administrativa transfere a propriedade do imóvel para o Poder Público.</strong>.","banca":"IDHTEC","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4230472,"enunciado":"Sobre a desapropriação, analise os itens a seguir: I. Todos os bens poderão ser desapropriados pela União, pelos Estados, Municípios, Distrito Federal e Territórios, mediante declaração de utilidade pública. II. Sempre que for necessária a utilização do subsolo pelo Poder Público, será necessária a desapropriação. III. A desapropriação poderá abranger a área contígua necessária ao desenvolvimento da obra a que se destina, e as zonas que se valorizarem extraordinariamente, em consequência da realização do serviço. IV. Quando o imóvel a ser desapropriado caracterizar-se como núcleo urbano informal ocupado predominante mente por população de baixa renda, o ente expropriante deverá prever, no planejamento da ação de desapropriação, medidas compensatórias. V. O imóvel desapropriado para implantação de parcela mento popular, destinado às classes de menor renda, poderá ter outra utilização, sendo garantido o direito de retrocessão. Assinale a alternativa correta:","opcoes":["Apenas os itens I, II e IV são verdadeiros.","Apenas os itens I, III e V são verdadeiros.","Apenas os itens I, III e IV são verdadeiros.","Apenas os itens I, II, III e IV são verdadeiros.","Todos os itens são verdadeiros."],"correta":2,"explicacao":"Gabarito: <strong>Apenas os itens I, III e IV são verdadeiros.</strong>.","banca":"IDHTEC","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"1":{"topico":"Competência para desapropriar","ancora":"competencia-desapropriar"},"2":{"topico":"Subsolo e espaço aéreo","ancora":"subsolo-espaco-aereo"},"3":{"topico":"Desapropriação por zona","ancora":"desapropriacao-por-zona"},"4":{"topico":"Núcleos urbanos informais","ancora":"nucleos-urbanos-informais"},"5":{"topico":"Tredestinação e retrocessão","ancora":"tredestinacao-retrocessao"}}},{"id":4230473,"enunciado":"Ainda sobre desapropriação, assinale a alternativa incorreta:","opcoes":["O Poder Legislativo poderá tomar a iniciativa da desapropriação, cumprindo, neste caso, ao Executivo, praticar os atos necessários à sua efetivação.","O Poder Judiciário pode, no processo de desapropriação, decidir se se verificam ou não os casos de utilidade pública.","A desapropriação deverá se efetivar dentro de cinco anos, contados da data da expedição do respectivo decreto de utilidade pública e findos os quais este caducará.","A desapropriação e imóveis urbanos será feita com prévia e justa indenização em dinheiro.","No processo de desapropriação, o poder público deverá notificar o proprietário e apresentar-lhe oferta de indenização."],"correta":1,"explicacao":"Gabarito: <strong>O Poder Judiciário pode, no processo de desapropriação, decidir se se verificam ou não os casos de utilidade pública.</strong>.","banca":"IDHTEC","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Iniciativa legislativa na desapropriação","ancora":"iniciativa-legislativa-desapropriacao"},"B":{"topico":"Limites da matéria em juízo","ancora":"limite-materia-juizo"},"C":{"topico":"Caducidade do decreto expropriatório","ancora":"caducidade-decreto-desapropriacao"},"D":{"topico":"Fundamentos constitucionais da desapropriação","ancora":"fundamentos-constitucionais-desapropriacao"},"E":{"topico":"Notificação, oferta e indenização","ancora":"notificacao-oferta-indenizacao"}}},{"id":4230514,"enunciado":"Determinado proprietário teve seu imóvel atingido por situação emergencial decorrente de grave risco coletivo. Em razão da urgência, autoridade pública utilizou temporariamente o bem para enfrentamento da situação, comprometendo-se a reparar eventual dano causado. Considerando a Constituição Federal, assinale a alternativa correta:","opcoes":["No caso de iminente perigo público, a autoridade competente poderá usar propriedade particular, assegurada ao proprietário indenização ulterior, se houver dano.","A utilização de propriedade particular pelo Poder Público somente pode ocorrer mediante desapropriação prévia.","A Constituição veda a utilização de propriedade particular em qualquer situação de perigo público.","A utilização temporária de propriedade particular exige autorização judicial prévia.","A indenização é devida independentemente da ocorrência de dano ao proprietário."],"correta":0,"explicacao":"Gabarito: <strong>No caso de iminente perigo público, a autoridade competente poderá usar propriedade particular, assegurada ao proprietário indenização ulterior, se houver dano.</strong>.","banca":"Instituto IACP","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"B":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"C":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"D":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"E":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"}}},{"id":4253704,"enunciado":"Certo município desapropriou imóvel de Lucas, por utilidade pública, para a construção de uma escola. Após incorporar o bem ao patrimônio público e pagar a indenização, o município construiu no local um centro cultural municipal e abandonou o projeto da escola. Lucas pretende reivindicar o imóvel, alegando desvio de finalidade. Paralelamente, a câmara municipal deliberou e aprovou lei que autoriza a desapropriação de imóvel vizinho pertencente ao estado para a instalação de posto de saúde, cabendo ao prefeito editar o decreto expropriatório. Nessa situação hipotética, de acordo com o Decreto-Lei n.º 3.365/1941 e a jurisprudência do STJ, Lucas","opcoes":["pode reivindicar o imóvel mediante ação própria, pois o referido decreto-lei veda apenas a reivindicação fundada em nulidade do processo, não alcançando a pretensão fundada em desvio de finalidade.","tem direito à retrocessão, pois qualquer mudança de destinação em relação ao declarado no decreto expropriatório configura tredestinação ilícita, autorizando a reivindicação do imóvel.","tem direito à retrocessão, pois a mudança de finalidade do bem desapropriado, ainda que para outra destinação pública, configura tredestinação ilícita e autoriza a reivindicação, nos termos do Código Civil.","não tem direito à retrocessão pela destinação pública dada ao bem; porém, se o bem fosse alienado a particular, tal destinação também afastaria o direito de retrocessão, pois qualquer ato do poder público presume-se revestido de finalidade pública.","não tem direito à retrocessão, pois a construção de centro cultural configura tredestinação lícita; e o procedimento adotado pelo município para desapropriar o imóvel estadual está correto, pois o Poder Legislativo pode tomar a iniciativa da desapropriação, cabendo ao Poder Executivo os atos de execução."],"correta":4,"explicacao":"Gabarito: <strong>não tem direito à retrocessão, pois a construção de centro cultural configura tredestinação lícita; e o procedimento adotado pelo município para desapropriar o imóvel estadual está correto, pois o Poder Legislativo pode tomar a iniciativa da desapropriação, cabendo ao Poder Executivo os atos de execução.</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4253783,"enunciado":"Considere as normas e a jurisprudência atualizada sobre as modalidades de intervenção do Estado na propriedade e assinale a alternativa correta:","opcoes":["A retrocessão é o direito do expropriado de exigir a devolução do bem caso a Administração Pública dê ao imóvel uma destinação pública diferente da prevista no decreto original, ainda que mantida a finalidade de interesse coletivo.","Na desapropriação extraordinária para fins de reforma agrária, compete aos Estados e Municípios desapropriar imóveis rurais que não cumpram sua função social, mediante indenização prévia e justa paga exclusivamente em dinheiro.","A desapropriação por zona permite que o Poder Público inclua, no decreto de utilidade pública, áreas contíguas necessárias ao desenvolvimento de uma obra ou zonas que se valorizem extraordinariamente em decorrência do serviço, podendo estas ser destinadas à revenda","A desapropriação indireta configura-se como uma modalidade restritiva de intervenção, na qual o proprietário mantém o domínio do bem, mas sofre limitações administrativas impostas por normas ambientais que esvaziam o conteúdo econômico do imóvel.","O confisco ou desapropriação confiscatória, aplicável a propriedades onde se localize trabalho escravo ou culturas ilegais de plantas psicotrópicas, admite o pagamento de indenização parcial ao proprietário que comprove boa-fé."],"correta":0,"explicacao":"Gabarito: <strong>A retrocessão é o direito do expropriado de exigir a devolução do bem caso a Administração Pública dê ao imóvel uma destinação pública diferente da prevista no decreto original, ainda que mantida a finalidade de interesse coletivo.</strong>.","banca":"FURB","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Tredestinação e retrocessão","ancora":"tredestinacao-retrocessao"},"B":{"topico":"Imunidade à reforma agrária","ancora":"imunidade-reforma-agraria"},"C":{"topico":"Desapropriação por zona","ancora":"desapropriacao-por-zona"},"D":{"topico":"Limitação e esvaziamento econômico","ancora":"limitacao-esvaziamento-economico"},"E":{"topico":"Imunidade à reforma agrária","ancora":"imunidade-reforma-agraria"}}},{"id":4253862,"enunciado":"O Estado de Santa Catarina, visando à construção de uma nova ala em um hospital público estadual, declarou a utilidade pública de um terreno baldio adjacente pertencente à Construtora \"Alfa\". Paralelamente, para viabilizar o início imediato do canteiro de obras e o armazenamento de maquinário pesado enquanto o processo expropriatório do terreno principal tramita, o Estado decide utilizar temporariamente um outro imóvel vizinho, de propriedade particular, que não possui benfeitorias e não está sendo utilizado. Diante dessa situação, assinale a alternativa correta:","opcoes":["O Estado poderá instituir a ocupação temporária do imóvel vizinho para o apoio às obras, sendo que, por se tratar de ocupação vinculada à execução de obras públicas em terreno não edificado, a indenização ao proprietário apenas será devida se houver dano efetivo ao bem.","No caso da desapropriação do terreno baldio da Construtora \"Alfa\", o Estado poderá efetivar a imissão provisória na posse independentemente da declaração de urgência, desde que comprove a necessidade de ampliação do hospital.","Por se tratar de uma intervenção supressiva, a ocupação temporária transfere a propriedade do imóvel vizinho ao Estado após o decurso de 5 (cinco) anos de uso ininterrupto, caso não haja oposição do proprietário.","A ocupação temporária do imóvel vizinho exige a prévia declaração de utilidade pública e o pagamento de indenização justa e antecipada em dinheiro, seguindo o mesmo rito procedimental da desapropriação do terreno principal.","A ocupação temporária e a servidão administrativa confundem-se neste caso, pois ambas possuem caráter permanente e exigem a averbação na matrícula do imóvel para terem validade perante terceiros."],"correta":0,"explicacao":"Gabarito: <strong>O Estado poderá instituir a ocupação temporária do imóvel vizinho para o apoio às obras, sendo que, por se tratar de ocupação vinculada à execução de obras públicas em terreno não edificado, a indenização ao proprietário apenas será devida se houver dano efetivo ao bem.</strong>.","banca":"FURB","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Ocupação temporária","ancora":"ocupacao-temporaria"},"B":{"topico":"Imissão provisória na posse","ancora":"imissao-provisoria-posse"},"C":{"topico":"Ocupação temporária","ancora":"ocupacao-temporaria"},"D":{"topico":"Ocupação temporária","ancora":"ocupacao-temporaria"},"E":{"topico":"Ocupação temporária","ancora":"ocupacao-temporaria"}}},{"id":4253879,"enunciado":"Uma lei federal autoriza que o Ministério da Saúde instale de forma permanente painéis publicitários (outdoors) relacionados à campanha de prevenção da dengue em terrenos privados e em fachadas de edifícios situados nas regiões geográficas de maior incidência da doença. Tal modalidade de intervenção na propriedade constitui","opcoes":["adjudicação compulsória.","ocupação temporária.","requisição administrativa.","desapropriação de uso.","servidão administrativa."],"correta":4,"explicacao":"Gabarito: <strong>servidão administrativa.</strong>.","banca":"FCC","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Desapropriação indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"Ocupação temporária","ancora":"ocupacao-temporaria"},"C":{"topico":"Requisição administrativa","ancora":"requisicao-administrativa"},"D":{"topico":"Servidão administrativa","ancora":"servidao-administrativa"},"E":{"topico":"Servidão administrativa","ancora":"servidao-administrativa"}}},{"id":4253953,"enunciado":"Acerca do tombamento, assinale a opção correta.","opcoes":["Devido às suas características, é vedado o tombamento geral de todos os bens situados em um bairro ou uma cidade.","Os bens públicos e os bens imateriais não podem ser objeto de tombamento.","Os efeitos do tombamento estão restritos ao proprietário e ao poder público, não se estendendo a terceiros (demais particulares).","O tombamento configura restrição total do direito de propriedade, razão pela qual acarreta direito a indenização.","Quanto à constituição, o tombamento pode ser de ofício, voluntário ou compulsório."],"correta":4,"explicacao":"Gabarito: <strong>Quanto à constituição, o tombamento pode ser de ofício, voluntário ou compulsório.</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"B":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"C":{"topico":"Tombamento — restrições aos vizinhos","ancora":"tombamento-vizinhos-art18"},"D":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"E":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"}}},{"id":4254015,"enunciado":"Leia as proposições a seguir: I. A requisição administrativa pressupõe a ocorrência de iminente perigo público como condição para o uso de propriedade particular pelo Poder Público. II. Na requisição administrativa, a indenização ao proprietário é devida previamente e independe da ocorrência de dano ao bem objeto da requisição. III. A requisição administrativa caracteriza-se pelo uso temporário e compulsório de propriedade particular, não implicando a transferência da titularidade do bem ao Poder Público. IV. A requisição administrativa depende da concordância do proprietário do bem, em razão do caráter excepcional da medida. O art. 5º, XXV, da Constituição Federal de 1988, disciplina a requisição administrativa como forma de utilização de propriedade particular pelo Poder Público em determinadas situações. Considerando o regime constitucional aplicável à requisição administrativa, estão corretas as proposições","opcoes":["I e II, apenas.","I e III, apenas.","II e IV, apenas.","I, II e III, apenas.","II, III e IV, apenas."],"correta":1,"explicacao":"Gabarito: <strong>I e III, apenas.</strong>.","banca":"FADESP","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"B":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"C":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"D":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"E":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"}}},{"id":4254059,"enunciado":"Lei municipal determinou que imóveis localizados em determinadas vias urbanas passariam a suportar, de modo permanente, a instalação de infraestrutura de telecomunicações e monitoramento urbano, vedando ao proprietário impedir o acesso para manutenção. A norma não previu indenização e José comprovou redução concreta do aproveitamento econômico de seu imóvel, o qual foi significativamente desvalorizado em razão da instalação. Trata-se de hipótese de intervenção do Estado na propriedade, configurando","opcoes":["desapropriação indireta, sendo necessária indenização prévia devido à perenidade da vedação imposta.","servidão administrativa, a qual admite indenização quando houver dano específico ao proprietário.","limitação administrativa geral, a qual dispensa indenização quando for permanente e impessoalizada.","requisição administrativa, sendo prescindível a indenização ainda que comprovado o dano concreto.","ocupação temporária, que não impede o caráter permanente da medida para sua caracterização e cabimento."],"correta":1,"explicacao":"Gabarito: <strong>servidão administrativa, a qual admite indenização quando houver dano específico ao proprietário.</strong>.","banca":"FCC","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Desapropriação indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"Servidão administrativa","ancora":"servidao-administrativa"},"C":{"topico":"Limitação administrativa","ancora":"limitacao-administrativa"},"D":{"topico":"Requisição administrativa","ancora":"requisicao-administrativa"},"E":{"topico":"Ocupação temporária","ancora":"ocupacao-temporaria"}}},{"id":4254115,"enunciado":"Considerando o regime jurídico da desapropriação, a respeito da imissão provisória na posse, é correto afirmar que","opcoes":["não mais é admitida no direito brasileiro, tendo em vista a necessidade de prévia e justa indenização em dinheiro.","depende de alegação de urgência, que poderá ser renovada, por até mais uma vez, pelo mesmo prazo inicial.","depende de perícia preliminar no processo e, uma vez deferida, dispensa o registro no cartório de imóveis.","tem que ser exercida dentro do prazo improrrogável de 120 (cento e vinte) dias após a alegação de urgência.","poderá ser feita, após a citação do réu, mediante o depósito do valor real do imóvel a ser expropriado."],"correta":3,"explicacao":"Gabarito: <strong>tem que ser exercida dentro do prazo improrrogável de 120 (cento e vinte) dias após a alegação de urgência.</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"B":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"C":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"D":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"E":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"}}},{"id":4254193,"enunciado":"“Sabe-se que a propriedade é o direito individual que assegura a seu titular uma série de poderes cujo conteúdo constitui objeto do direito civil; compreende os poderes de usar, gozar e dispor da coisa, de modo absoluto, exclusivo e perpétuo. Não podem, no entanto, esses poderes ser exercidos ilimitadamente, porque coexistem com direitos alheios, de igual natureza, e porque existem interesses públicos maiores, cuja tutela incumbe ao Poder Público exercer, ainda que em prejuízo de interesses individuais. Entra-se aqui na esfera do poder de polícia do Estado, ponto em que o estudo da propriedade sai da órbita do direito privado e passa a constituir objeto do direito público e a submeter-se a regime jurídico derrogatório e exorbitante do direito comum.” (Maria Sylvia Zanella Di Pietro. Direito Administrativo, 2025. 38. ed. Rio de Janeiro: Forense, 2025). Considerando a legislação aplicável e o entendimento consolidado do STJ acerca das diversas modalidades de intervenção do Estado na propriedade privada, assinale a alternativa correta.","opcoes":["O Poder Público ajuizou ação de desapropriação em face de Beltrano, ofertando inicialmente determinada quantia a título de indenização. Ao final do processo, a sentença fixou o valor indenizatório em montante superior ao ofertado, reconhecendo a diferença em favor do expropriado. Nessa hipótese, os honorários advocatícios devidos ao patrono de Beltrano devem ser fixados entre 10% e 20%, nos termos do art. 85, § 2º, do CPC, incidindo sobre a diferença entre o valor inicialmente ofertado e a indenização judicialmente fixada, por se tratar de condenação imposta à Fazenda Pública.","Sicrano adquiriu, por meio de contrato oneroso, imóvel rural que, à época da aquisição, já se encontrava parcialmente ocupado pelo Poder Público, em razão da implantação de rodovia estadual, com a execução de obras permanentes de pavimentação, drenagem e sinalização, situação visível e de conhecimento público na região. Nessa hipótese, Sicrano deve ajuizar ação de desapropriação indireta, fazendo jus à indenização integral, independentemente da data da aquisição do imóvel e da existência prévia de restrição administrativa, porquanto o direito à justa indenização é inerente ao direito de propriedade.","Construtora XYZ é proprietária de imóvel urbano situado em área central do município de Joinville que, em razão da aprovação de novo Plano Diretor Municipal, passou a estar submetido a restrições urbanísticas que reduziram significativamente o coeficiente de aproveitamento e o gabarito de altura das edificações permitidas no local, inviabilizando o projeto imobiliário inicialmente pretendido. Não houve ocupação física do bem pelo Poder Público nem transferência da titularidade dominial. Nessa hipótese, poderá haver direito à indenização, desde que demonstrado o esvaziamento substancial da propriedade.","Fulano de Tal é proprietário de imóvel urbano que passou a ser integralmente ocupado pelo Poder Público, que nele realizou obras permanentes de infraestrutura, implantando equipamento público de uso coletivo, sem a prévia instauração de procedimento expropriatório formal e sem o pagamento de indenização. Fulano de Tal pode ajuizar ação visando à indenização pela chamada desapropriação indireta, desde que o faça no prazo prescricional de cinco anos, contado da efetiva ocupação do imóvel pelo Poder Público, por se tratar de pretensão indenizatória contra a Fazenda Pública.","Tertuliano é proprietário de imóvel urbano não edificado, localizado em área incluída no plano diretor municipal, que, após regular notificação pelo Poder Público, permaneceu sem a edificação indicada no Plano Diretor, mesmo após a aplicação sucessiva do parcelamento ou edificação compulsórios e da alíquota progressiva do IPTU no tempo. Nessa hipótese, é juridicamente possível a desapropriação, com indenização prévia, justa e em dinheiro."],"correta":2,"explicacao":"Gabarito: <strong>Construtora XYZ é proprietária de imóvel urbano situado em área central do município de Joinville que, em razão da aprovação de novo Plano Diretor Municipal, passou a estar submetido a restrições urbanísticas que reduziram significativamente o coeficiente de aproveitamento e o gabarito de altura das edificações permitidas no local, inviabilizando o projeto imobiliário inicialmente pretendido. Não houve ocupação física do bem pelo Poder Público nem transferência da titularidade dominial. Nessa hipótese, poderá haver direito à indenização, desde que demonstrado o esvaziamento substancial da propriedade.</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Notificação, oferta e indenização","ancora":"notificacao-oferta-indenizacao"},"B":{"topico":"Desapropriação indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"Limitação e esvaziamento econômico","ancora":"limitacao-esvaziamento-economico"},"D":{"topico":"Desapropriação indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"Núcleos urbanos informais","ancora":"nucleos-urbanos-informais"}}},{"id":4254334,"enunciado":"Considere que o Instituto do Patrimônio Histórico e Artístico Nacional (IPHAN), autarquia integrante da Administração Pública federal, editou ato de tombamento de um bem público de titularidade estadual destinado a uso público de lazer e interesse ambiental. A decisão da autarquia federal","opcoes":["implica alteração da gestão exercida sobre o bem, transferida ao órgão de tombamento federal, que poderá decidir sobre os usos possíveis para o imóvel.","depende de autorização ou, no caso concreto, homologação pelo Poder Legislativo, como forma de preservação do princípio federativo e da autonomia dos entes subnacionais.","restringe a atuação dos demais órgãos e entidades de proteção do patrimônio histórico e cultural, que só poderão editar atos para imposição de tombamento em grau e limites mais rigorosos que os estabelecidos pela autarquia federal.","não impede que outros órgãos de tombamento editem decisões ou atos impondo restrições de mesma natureza, em igual ou diferentes limites, ou que concluam pela ausência de relevância para fins de tombamento, considerando a autonomia dos entes federativos.","está eivada de vício de legalidade, tendo em vista que, consoante expressa disposição legal, um ente público não pode editar atos de restrição ou intervenção na propriedade de outros entes subnacionais, sob violação do princípio federativo."],"correta":3,"explicacao":"Gabarito: <strong>não impede que outros órgãos de tombamento editem decisões ou atos impondo restrições de mesma natureza, em igual ou diferentes limites, ou que concluam pela ausência de relevância para fins de tombamento, considerando a autonomia dos entes federativos.</strong>.","banca":"FCC","ano":2025,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"B":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"C":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"D":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"E":{"topico":"tombamento conceito","ancora":"tombamento-conceito"}}},{"id":4254382,"enunciado":"A servidão administrativa é meio de intervenção do Estado na propriedade privada com natureza jurídica de direito real público para assegurar a realização de obras e serviços públicos. Sobre o tema, julgue os itens a seguir: I.Servidão administrativa e servidão privada, esta disciplinada pelo Código Civil, são institutos equivalentes. II.Servidão administrativa não pode recair sobre bem público, apenas sobre bem privado. III.Na servidão pública, o ente público aparece como partícipe da relação, enquanto a servidão privada dá-se entre particulares. IV.O regime jurídico envolvido na servidão pública é o regime jurídico administrativo, pautado nas prerrogativas conferidas à Administração em razão da supremacia do interesse público sobre o privado e nas sujeições oriundas da indisponibilidade do interesse público. V.A servidão administrativa nunca gerará direito à indenização do proprietário. É correto o que se apresenta em:","opcoes":["I, II e V, apenas.","I, II, III, IV e V.","III e IV, apenas.","IV e V, apenas.","I e II, apenas."],"correta":0,"explicacao":"Gabarito: <strong>I, II e V, apenas.</strong>.","banca":"FURG","ano":2025,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4254412,"enunciado":"O Município de Pinhais - PR declarou de utilidade pública um imóvel para construção de uma escola. Ajuizada a ação de desapropriação, o proprietário requereu levantamento imediato do valor depositado em juízo. O Município alegou que isso só seria possível após o trânsito em julgado. Sobre o assunto, assinale a alternativa CORRETA.","opcoes":["O levantamento pode ser autorizado antes da sentença, desde que o expropriado comprove a propriedade e não haja ônus ou oposição de terceiros, mediante decisão judicial.","O levantamento depende de lei da Câmara Municipal que o autorize caso a caso.","O levantamento é automático com o depósito judicial e independe de decisão do juiz.","O levantamento é vedado em qualquer hipótese antes do trânsito em julgado e a respectiva imissão na posse pela Administração.","O levantamento só é possível após o trânsito em julgado da sentença, ainda que não haja controvérsia sobre a titularidade."],"correta":4,"explicacao":"Gabarito: <strong>O levantamento só é possível após o trânsito em julgado da sentença, ainda que não haja controvérsia sobre a titularidade.</strong>.","banca":"FAFIPA","ano":2025,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4254487,"enunciado":"A Lei nº 4.132/1962 regulamenta a desapropriação por interesse social, modalidade que tem como finalidade primordial promover a justa distribuição da propriedade e seu adequado aproveitamento, em conformidade com os princípios constitucionais da função social. Assim, em relação às regras expressas na Lei nº 4.132/1962, é correto afirmar que, EXCETO:","opcoes":["É vedada a locação dos bens desapropriados, que somente serão objeto de venda a quem estiver em condições de dar-lhes a destinação social prevista.","O expropriante tem o prazo de dois anos, a partir da decretação da desapropriação por interesse social, para efetivar a aludida desapropriação e iniciar as providências de aproveitamento do bem expropriado.","Considera-se de interesse social, entre outras hipóteses, o aproveitamento de todo bem improdutivo ou explorado sem correspondência com as necessidades de habitação, trabalho e consumo dos centros de população a que deve ou possa suprir por seu destino econômico.","As necessidades de habitação, trabalho e consumo serão apuradas anualmente segundo a conjuntura e as condições econômicas locais, cabendo o seu estudo e verificação às autoridades encarregadas de velar pelo bem-estar e pelo abastecimento das respectivas populações."],"correta":0,"explicacao":"Gabarito: <strong>É vedada a locação dos bens desapropriados, que somente serão objeto de venda a quem estiver em condições de dar-lhes a destinação social prevista.</strong>.","banca":"CONSULPLAN","ano":2025,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"B":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"C":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"D":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"}}},{"id":4254494,"enunciado":"A desapropriação é uma das formas de intervenção do Estado na propriedade privada, prevista na Constituição Federal de 1988 e regulamentada por legislação específica. Esse instituto busca compatibilizar o direito de propriedade, assegurado constitucionalmente, com a supremacia do interesse público, garantindo ao mesmo tempo a proteção do particular contra arbitrariedades estatais. A respeito da jurisprudência do Supremo Tribunal Federal (STF) e do Superior Tribunal de Justiça (STJ) acerca dessa figura, analise as afirmativas a seguir. I. O prazo prescricional aplicável à desapropriação indireta, na hipótese em que o poder público tenha realizado obras no local ou atribuído natureza de utilidade pública ou de interesse social ao imóvel, é de dez anos. II. Reconhecida a incidência do princípio da boa-fé objetiva em ação de desapropriação indireta, se a aquisição do bem ou de direitos sobre ele ocorrer quando já existente restrição administrativa, fica subentendido que tal ônus foi considerado na fixação do preço. Nesses casos, o adquirente não faz jus a qualquer indenização do órgão expropriante por eventual apossamento anterior. Excetuam-se da tese hipóteses em que patente a boa-fé objetiva do sucessor, como em situações de negócio jurídico gratuito ou de vulnerabilidade econômica do adquirente. III. O trânsito em julgado de sentença condenatória proferida em sede de ação desapropriatória não obsta a propositura de Ação Civil Pública em defesa do patrimônio público, para discutir a dominialidade do bem expropriado, ainda que já se tenha expirado o prazo para a Ação Rescisória. Está correto o que se afirma em","opcoes":["I, II e III.","I e II, apenas.","I e III, apenas.","II e III, apenas."],"correta":0,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"CONSULPLAN","ano":2025,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4254509,"enunciado":"Sobre a declaração de bem de interesse público, que dá início ao procedimento de desapropriação, é correto afirmar que","opcoes":["pode ser realizada pelo Poder Executivo, por meio do decreto expropriatório, ou pelo Poder Legislativo, por meio de lei de efeito concreto.","não é possível a declaração de utilidade pública de bem imóvel pertencente ao domínio do ente municipal pelo Estado.","o decreto expropriatório não autoriza o expropriante a ingressar na área, ainda que para fins de inspeções ou levantamento.","o decreto expropriatório caduca em três anos, caso a Administração não adote medidas concretas para a efetivação da desapropriação."],"correta":0,"explicacao":"Gabarito: <strong>pode ser realizada pelo Poder Executivo, por meio do decreto expropriatório, ou pelo Poder Legislativo, por meio de lei de efeito concreto.</strong>.","banca":"VUNESP","ano":2025,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Iniciativa legislativa na desapropriação","ancora":"iniciativa-legislativa-desapropriacao"},"B":{"topico":"Competência para desapropriar","ancora":"competencia-desapropriar"},"C":{"topico":"Autorização para penetrar em prédios","ancora":"art7-penetrar-predios"},"D":{"topico":"Caducidade do decreto expropriatório","ancora":"caducidade-decreto-desapropriacao"}}},{"id":4254583,"enunciado":"Assinale a opção correta com base no entendimento do STJ sobre a intervenção do Estado na propriedade.","opcoes":["A indenização pela limitação administrativa ao direito de edificar advinda da criação de área non aedificandi é sempre devida quando imposta sobre imóvel urbano, pois o prejuízo causado ao proprietário da área é presumido.","São vedadas construções na faixa de servidão, ainda que não afetem a prestação do serviço público.","No ato de tombamento geral, é desnecessário individualizar os bens abarcados pelo tombo, pois as restrições impostas pelo instituto estendem-se à totalidade dos imóveis pertencentes à área tombada.","É devida indenização se o imóvel expropriado for adquirido após a imposição de limitação administrativa.","Incide imposto de renda sobre os valores indenizatórios recebidos pelo particular em razão de servidão administrativa instituída pelo poder público."],"correta":2,"explicacao":"Gabarito: <strong>No ato de tombamento geral, é desnecessário individualizar os bens abarcados pelo tombo, pois as restrições impostas pelo instituto estendem-se à totalidade dos imóveis pertencentes à área tombada.</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Limitação administrativa","ancora":"limitacao-administrativa"},"B":{"topico":"Servidão administrativa","ancora":"servidao-administrativa"},"C":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"D":{"topico":"Limitação e esvaziamento econômico","ancora":"limitacao-esvaziamento-economico"},"E":{"topico":"Servidão administrativa","ancora":"servidao-administrativa"}}},{"id":4254598,"enunciado":"A respeito da administração pública direta, indireta e fundacional, dos atos administrativos e da requisição, julgue o item seguinte. \n\n\n\n\nA requisição administrativa é uma forma de intervenção do Estado na propriedade privada que tem caráter temporário e é indenizável apenas em caso de dano, não se confundindo com a desapropriação, que exige indenização prévia.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"E":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"}}},{"id":4254669,"enunciado":"Sobre a atuação do Estado em relação à propriedade privada, assinale a alternativa que apresenta uma hipótese de tombamento.","opcoes":["A instituição de direito real público de uso, decorrente de sentença judicial, em ação movida pelo Estado de Pernambuco em face de um particular, que permite a utilização da referida propriedade particular pelo Estado com a finalidade de atendimento ao interesse público, mediante pagamento de indenização devida ao particular que suportará a limitação à sua propriedade","Comunicação expedida pelo juízo eleitoral vinte dias antes da eleição ao proprietário de um colégio privado requisitando seu edifício para instalação e pronunciamento das mesas receptoras de votos, para a eleição vindoura","Intervenção restritiva deduzida pelo legislador constituinte em 1988 voltada à proteção patrimonial cultural de todos os documentos e sítios detentores de reminiscências históricas dos antigos quilombos","Apropriação irreversível realizada pela União, de um bem imóvel particular, não precedida de declaração de interesse público, tampouco de observância ao devido processo legal, e desprovida de indenização prévia ao apossamento da área"],"correta":2,"explicacao":"Gabarito: <strong>Intervenção restritiva deduzida pelo legislador constituinte em 1988 voltada à proteção patrimonial cultural de todos os documentos e sítios detentores de reminiscências históricas dos antigos quilombos</strong>.","banca":"IBFC","ano":2025,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Servidão administrativa","ancora":"servidao-administrativa"},"B":{"topico":"Requisição administrativa","ancora":"requisicao-administrativa"},"C":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"D":{"topico":"Desapropriação indireta","ancora":"desapropriacao-indireta"}}},{"id":4254674,"enunciado":"Ao julgar uma ação de desapropriação por utilidade pública, deverá o juízo atentar-se ao fato de que a legislação ______. Assinale a alternativa que preencha corretamente a lacuna.","opcoes":["veda ao Poder Judiciário, no processo de desapropriação, decidir se se verificam ou não os casos de utilidade pública","prevê o prazo decadencial de cinco anos, contados da data da avaliação do imóvel objeto da pretensão, para propositura da ação de desapropriação","estabelece que a ação, quando a União for autora, será proposta necessariamente no Distrito Federal; e se o autor for o Estado, na capital deste","prevê a possibilidade de decisão liminar de imissão provisória na posse, no caso de urgência, independente da citação do réu, ficando dispensado registro de tal imissão no cartório de registro de imóveis competente"],"correta":0,"explicacao":"Gabarito: <strong>veda ao Poder Judiciário, no processo de desapropriação, decidir se se verificam ou não os casos de utilidade pública</strong>.","banca":"IBFC","ano":2025,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Limites da matéria em juízo","ancora":"limite-materia-juizo"},"B":{"topico":"Caducidade do decreto expropriatório","ancora":"caducidade-decreto-desapropriacao"},"C":{"topico":"Competência para desapropriar","ancora":"competencia-desapropriar"},"D":{"topico":"Imissão provisória na posse","ancora":"imissao-provisoria-posse"}}},{"id":4254724,"enunciado":"No que diz respeito à intervenção do Estado sobre a propriedade privada e aos bens públicos, julgue o item seguinte. \n\n\n\n\nA ocupação temporária é forma de intervenção do Estado na propriedade privada tipicamente relacionada a bens imóveis que, como regra, servem de apoio à execução de obras e serviços públicos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"E":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"}}},{"id":4254842,"enunciado":"Leia o excerto sobre servidão pública ou administrativa. O instituto da servidão, cuja estruturação é originária do direito privado, é, na verdade, uma categoria jurídica, pois é existente também no direito público (embora com suas peculiaridades), mas sempre significando sujeição a uma utilidade ou permissão instituída de forma estável para o direito, em benefício de outrem que não o proprietário do bem que suporta tal restrição, mas obviamente e em qualquer caso da servidão administrativa, sem que se aniquile a utilização dessa propriedade por seu proprietário, o que configuraria caso típico de desapropriação. (ARAÚJO, Edmir Netto de. Curso de direito administrativo. 8. ed. Rio de Janeiro: Saraiva Jur, 2018.) Considerando os ditames do direito administrativo acerca do referido instituto jurídico, marque V para as afirmativas verdadeiras e F para as falsas. ( ) A servidão administrativa é ônus real de uso, imposto pela Administração à propriedade particular, para assegurar a realização e conservação de obras e serviços públicos ou de utilidade pública, exigindo-se, em qualquer caso, o pagamento de indenização. ( ) Se a servidão administrativa for instituída diretamente por lei, não é necessário realizar qualquer outro ato jurídico unilateral ou bilateral para que o ônus real atinja determinados bens ou série de bens. ( ) Nos casos de servidão constituída por acordo extrajudicial, precedido de declaração de utilidade pública de bem determinado, ou decorrente de sentença judicial, o ônus real se efetiva mediante inscrição no Registro de Imóveis competente, para conhecimento e validade erga omnes. ( ) A característica de perpetuidade das servidões administrativas obsta a sua extinção, mesmo quando a coisa dominante for desafetada de sua finalidade pública ou quando o bem gravado for expropriado pela entidade pública que a instituiu. Assinale a sequência correta.","opcoes":["F, V, V, F","F, F, V, F","V, F, F, V","V, V, F, V"],"correta":0,"explicacao":"Gabarito: <strong>F, V, V, F</strong>.","banca":"UFMT","ano":2025,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4254894,"enunciado":"Suponha que a prefeitura do município Alfa decida construir uma avenida para melhorar o fluxo de trânsito entre duas regiões da cidade. Durante a execução da obra, a via pública é alargada, e parte de um terreno particular, pertencente ao Sr. José, é ocupada sem que tenha havido qualquer ato formal da prefeitura para tomada de posse da área ou indenização prévia. Mesmo após a conclusão da obra, a prefeitura não formaliza nenhum processo administrativo ou judicial, tampouco paga qualquer valor ao proprietário. O imóvel do Sr. José permanece parcialmente ocupado por calçadas, postes de iluminação e uma ciclovia, integrando-se de forma permanente ao uso público. É correto afirmar que a situação descrita corresponde à chamada","opcoes":["requisição por estado de necessidade.","requisição administrativa.","desapropriação indireta.","desapropriação por utilidade pública.","desapropriação por interesse social."],"correta":2,"explicacao":"Gabarito: <strong>desapropriação indireta.</strong>.","banca":"VUNESP","ano":2025,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4255024,"enunciado":"Julgue o item a seguir, no que se refere à desapropriação, à proteção de dados e ao acesso à informação.\n\nSe uma propriedade for produtiva, ela será insuscetível de desapropriação para fins de reforma agrária.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4255066,"enunciado":"Com base no entendimento do STJ acerca da intervenção do Estado na propriedade privada, assinale a opção correta.","opcoes":["É indevida indenização por expropriação de imóvel adquirido após a imposição de limitação administrativa, pois se presume que as restrições de uso e gozo da propriedade já tenham sido consideradas na fixação do preço do imóvel.","No ato de tombamento geral, devem constar individualizados os bens abarcados pelo tombo, pois as restrições não se estendem à totalidade dos imóveis situados na área tombada.","Qualquer construção acrescida ao conjunto arquitetônico tombado deverá ser demolida, mesmo se inexistir ofensa à harmonia estética.","Será devida, em regra, indenização por limitação administrativa ao direito de edificar advinda da criação de área non aedificandi, mesmo que não fique demonstrado prejuízo causado ao proprietário.","O tombamento do Plano Piloto de Brasília está restrito à sua estrutura física, não abrangendo seu singular conceito paisagístico e urbanístico."],"correta":0,"explicacao":"Gabarito: <strong>É indevida indenização por expropriação de imóvel adquirido após a imposição de limitação administrativa, pois se presume que as restrições de uso e gozo da propriedade já tenham sido consideradas na fixação do preço do imóvel.</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Limitação e esvaziamento econômico","ancora":"limitacao-esvaziamento-economico"},"B":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"C":{"topico":"Tombamento — restrições aos vizinhos","ancora":"tombamento-vizinhos-art18"},"D":{"topico":"Limitação administrativa","ancora":"limitacao-administrativa"},"E":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"}}},{"id":4255119,"enunciado":"Embora o direito à propriedade esteja garantido constitucionalmente como um direito fundamental, ele não é absoluto. A propriedade deve atender à sua função social, e o Estado, em determinadas circunstâncias, pode intervir na propriedade privada para garantir o interesse público. Sobre a intervenção do Estado na propriedade, analise as situações abaixo: I.O plano diretor de um município estabelece regras urbanísticas que proíbem construções com mais de três pavimentos em determinada região. II.Para conter um incêndio que consumia uma residência, o Corpo de Bombeiros precisou adentrar e utilizar o imóvel vizinho para extinguir os focos ativos e evitar que o fogo se alastrasse para as edificações ao redor. III.Um imóvel com arquitetura barroca, considerado parte do patrimônio cultural do município Alfa, recebeu restrições do poder público quanto ao seu uso e modificação para garantir sua preservação. Assinale a alternativa que associa CORRETAMENTE cada situação à respectiva espécie de intervenção do Estado na propriedade:","opcoes":["I.Servidão Administrativa, II. Tombamento, III. Desapropriação.","I.Limitação Administrativa, II.Ocupação Temporária, III.Desapropriação.","I.Limitação Administrativa, II.Requisição Administrativa, III.Tombamento.","I.Requisição Administrativa, II.Ocupação Temporária, III. Tombamento."],"correta":2,"explicacao":"Gabarito: <strong>I.Limitação Administrativa, II.Requisição Administrativa, III.Tombamento.</strong>.","banca":"UNO Chapecó","ano":2025,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"1":{"topico":"Limitação administrativa","ancora":"limitacao-administrativa"},"2":{"topico":"Requisição administrativa","ancora":"requisicao-administrativa"},"3":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"}}},{"id":4255121,"enunciado":"A ação de desapropriação indireta:","opcoes":["Possui caráter de ação de natureza pessoal e prescreve em 5 (cinco) anos, contados do ato ilícito.","É ação real e prescreve em 10 (dez) anos na hipótese em que o Poder Público tenha realizado obras no local apossado ilicitamente ou atribuído natureza de utilidade pública ou de interesse social ao imóvel.","É hipótese de ação imprescritível.","Prescreve em 3 (três) anos, seguindo a regra geral do artigo 206, §3º do Código Civil, contados da ciência do ilícito.","Prescreve em 20 (vinte) anos."],"correta":1,"explicacao":"Gabarito: <strong>É ação real e prescreve em 10 (dez) anos na hipótese em que o Poder Público tenha realizado obras no local apossado ilicitamente ou atribuído natureza de utilidade pública ou de interesse social ao imóvel.</strong>.","banca":"Qconcursos","ano":2025,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4255273,"enunciado":"Julgue o item subsequente, a respeito da desapropriação e da proteção do patrimônio cultural, considerando, no que couber, a jurisprudência do STF.\n\n\n\n\nNo caso de desapropriação em que seja necessária a complementação da indenização, ao final do processo expropriatório, o pagamento deverá ser realizado mediante depósito judicial direto se o poder público não estiver em dia com os precatórios.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"stf tema 831 precatorios","ancora":"stf-tema-831-precatorios"},"E":{"topico":"stf tema 831 precatorios","ancora":"stf-tema-831-precatorios"}}},{"id":4255438,"enunciado":"No tocante ao tombamento, assinale a alternativa correta.","opcoes":["Caso um particular adquira bem tombado, de propriedade de outro particular, aquele, dentro do prazo de trinta dias, sob pena de multa de dez por cento sobre o respectivo valor, fazê-la constar do registro;","A coisa tombada poderá sair do país, com transferência de domínio, desde que, tenha prazo certo, por curto período, e que tenha finalidade de intercâmbio cultural, a juízo do Conselho Consultivo do Serviço do Patrimônio Histórico e Artístico Nacional;","Aquele que praticar o comércio de exportação de bens tombados, terá como pena, a aplicação de multa e a desapropriação do bem, caso seja proprietário, na mesma pena, incorre o proprietário do bem que autoriza a comercialização;","As coisas tombadas poderão ser destruídas, demolidas ou mutiladas, desde que seja autorizado previamente pelo Serviço do Patrimônio Histórico e Artístico Nacional."],"correta":0,"explicacao":"Gabarito: <strong>Caso um particular adquira bem tombado, de propriedade de outro particular, aquele, dentro do prazo de trinta dias, sob pena de multa de dez por cento sobre o respectivo valor, fazê-la constar do registro;</strong>.","banca":"Instituto JK","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"art14 saida territorio","ancora":"art14-saida-territorio"},"E":{"topico":"art14 saida territorio","ancora":"art14-saida-territorio"}}},{"id":4255534,"enunciado":"Considere a seguinte situação hipotética: Em ação ajuizada em desfavor do Município dos Lírios, o titular de uma propriedade rural próxima a um loteamento de casas, regularmente aprovado pela Administração municipal para implantação de um empreendimento imobiliário, relatou que a Prefeitura ocupou indevidamente parcela da área de sua propriedade para execução das obras de uma avenida que dá acesso ao novo residencial. Durante a instrução processual, restou demonstrado que a ocupação pelo ente municipal resultou na incorporação de forma irreversível e plena de parte do bem imóvel particular ao patrimônio público. Sobre a modalidade de intervenção do poder público na propriedade privada caracterizada na situação fática retratada e o respectivo prazo prescricional aplicável à pretensão indenizatória, é correto afirmar:","opcoes":["O prazo prescricional das ações indenizatórias por desapropriação indireta, na hipótese em que o Poder Público tenha realizado obras no local ou atribuído natureza de utilidade pública ao imóvel, é de 10 (dez) anos, conforme parágrafo único do art. 1.238 do Código Civil.","O prazo prescricional das ações indenizatórias por desapropriação indireta é de 15 (quinze) anos, na medida em que o parágrafo único do art. 1.238 do Código Civil destina-se especificamente a regular os direitos de posseiro particular que ocupa o imóvel para uso residencial ou produtivo.","O prazo prescricional das ações indenizatórias por desapropriação direta, na hipótese de ocupação de área privada pelo Poder Público para fins de utilidade pública, é de 10 (dez) anos, conforme regulado pelo Decreto-lei n.º 3.365/1941.","O prazo prescricional das ações indenizatórias por desapropriação direta, na hipótese de ocupação de propriedade privada pelo Poder Público para fins de interesse social, é de 15 (quinze) anos, conforme regulado pela Lei n.º 4.132/1962."],"correta":0,"explicacao":"Gabarito: <strong>O prazo prescricional das ações indenizatórias por desapropriação indireta, na hipótese em que o Poder Público tenha realizado obras no local ou atribuído natureza de utilidade pública ao imóvel, é de 10 (dez) anos, conforme parágrafo único do art. 1.238 do Código Civil.</strong>.","banca":"UFMT","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4255570,"enunciado":"Assinale a alternativa correta acerca do tombamento e dos efeitos do tombamento, com base nos Capítulos II e III do Decreto−Lei nº 25 de 1937.","opcoes":["No caso de extravio ou furto de qualquer objeto tombado, o respectivo proprietário deverá dar conhecimento do fato ao Serviço do Patrimônio Histórico e Artístico Nacional, dentro do prazo de dez dias, sob pena de multa de dez por cento sobre o valor da coisa.","O Serviço do Patrimônio Histórico e Artístico Nacional possuirá seis Livros do Tombo.","A coisa tombada não poderá sair do país, senão por curto prazo, com transferência de domínio e para fim de intercâmbio cultural, a juízo do Conselho Consultivo do Serviço do Patrimônio Histórico e Artístico Nacional.","O Serviço do Patrimônio Histórico e Artístico Nacional, por seu órgão competente, notificará o proprietário para anuir ao tombamento, dentro do prazo de trinta dias, a contar do recebimento da notificação, ou para, se o quiser impugnar, oferecer dentro do mesmo prazo as razões de sua impugnação.","O tombamento de coisa pertencente à pessoa natural ou à pessoa jurídica de direito privado se fará voluntária ou compulsoriamente."],"correta":1,"explicacao":"Gabarito: <strong>O Serviço do Patrimônio Histórico e Artístico Nacional possuirá seis Livros do Tombo.</strong>.","banca":"Instituto Abaré-eté","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Tombamento — obrigação de conservação","ancora":"tombamento-art19-conservacao"},"B":{"topico":"Livros do Tombo","ancora":"livros-tombo"},"C":{"topico":"Tombamento — saída do território nacional","ancora":"art14-saida-territorio"},"D":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"E":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"}}},{"id":4255764,"enunciado":"Considere que João, Prefeito do Município ABC, deseja desapropriar um imóvel de 500 m2 pertencente a Marcos para construir um parque naturalizado para as crianças, pois a cidade deseja receber um selo UNICEF, o que possibilitaria o recebimento de recursos para aperfeiçoar as políticas públicas para a primeira infância. Com base na situação hipotética, é correto afirmar que","opcoes":["a declaração expropriatória depende da edição de lei de iniciativa de João, que terá efeitos concretos e se equiparará a um ato administrativo, não sendo legítimo seu controle pelo Poder Judiciário.","uma vez publicada a lei expropriatória após a sanção de João, Marcos terá, imediatamente, suspensa a posse de seu imóvel e haverá a imissão provisória da posse em favor do ente exequente, ainda que antes da citação do processo judicial, considerando-se a supremacia do interesse público.","é incabível a submissão da desapropriação à mediação ou à arbitragem, pois o interesse público é indisponível.","proposta a ação de desapropriação na Justiça Estadual, caso a União posteriormente verifique interesse e intervenha no processo, em face da perpetuatio jurisdicitionis e do fato de que a competência para julgar é absoluta do foro da situação do bem, o processo deve permanecer no juízo estadual.","após Marcos ser devidamente citado, ele poderá apresentar contestação, alegando, inclusive, o direito de extensão, mas não sendo possível utilizar-se da reconvenção."],"correta":4,"explicacao":"Gabarito: <strong>após Marcos ser devidamente citado, ele poderá apresentar contestação, alegando, inclusive, o direito de extensão, mas não sendo possível utilizar-se da reconvenção.</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Iniciativa legislativa na desapropriação","ancora":"iniciativa-legislativa-desapropriacao"},"B":{"topico":"Imissão provisória na posse","ancora":"imissao-provisoria-posse"},"C":{"topico":"Conceito e natureza jurídica da desapropriação","ancora":"conceito-desapropriacao"},"D":{"topico":"Competência para desapropriar","ancora":"competencia-desapropriar"},"E":{"topico":"Direito de extensão","ancora":"direito-extensao"}}},{"id":4255767,"enunciado":"No que se refere à intervenção do Estado na propriedade privada e à  responsabilidade civil do Estado, julgue o item subsequente, com base na Constituição Federal de 1988 e na jurisprudência dos tribunais superiores.\n\n\n\n\nNo âmbito de ação de desapropriação indireta, o proprietário atual do imóvel, ainda que o tenha adquirido quando já existentes as limitações administrativas impostas pelo poder público, tem direito à indenização em razão dessas restrições de uso e gozo da propriedade.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4255768,"enunciado":"No que se refere à intervenção do Estado na propriedade privada e à  responsabilidade civil do Estado, julgue o item subsequente, com base na Constituição Federal de 1988 e na jurisprudência dos tribunais superiores.\n\n\n\n\nA desapropriação confiscatória pode alcançar propriedades urbanas e rurais — exceto bens públicos —, não ensejando indenização ao proprietário, além de admitir a cumulação com outras sanções previstas em lei.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"E":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"}}},{"id":4255769,"enunciado":"No que se refere à intervenção do Estado na propriedade privada e à  responsabilidade civil do Estado, julgue o item subsequente, com base na Constituição Federal de 1988 e na jurisprudência dos tribunais superiores.\n\n\n\n\nSegundo a jurisprudência do STF, é objetiva a responsabilidade civil do Estado decorrente de omissão, seja de pessoas jurídica de direito público, seja de pessoa jurídica de direito privado prestadora de serviço público, considerada a reparação de danos materiais suportados por terceiros.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"distincao instrumentos intervencao","ancora":"distincao-instrumentos-intervencao"},"E":{"topico":"distincao instrumentos intervencao","ancora":"distincao-instrumentos-intervencao"}}},{"id":4255946,"enunciado":"A empresa Z, concessionária de serviços públicos, ao realizar obra pública, utilizou-se de um terreno lindeiro à obra para a colocação de maquinários e formação de canteiro de obra. Terminada a obra, beneficiou a área, ali implantando uma praça pública. Nessa situação, ao proprietário do terreno cabe:","opcoes":["ingressar com ação de indenização contra o Poder Público concedente por apossamento administrativo.","não fazer nada, já que o terreno antes não era explorado e foi beneficiado, não cabendo qualquer indenização.","ingressar com ação de indenização contra a concessionária e desapropriação indireta contra o Poder Público pelo apossamento administrativo.","ingressar com desapropriação indireta contra a concessionária."],"correta":2,"explicacao":"Gabarito: <strong>ingressar com ação de indenização contra a concessionária e desapropriação indireta contra o Poder Público pelo apossamento administrativo.</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4256088,"enunciado":"O Decreto-lei nº 25/1937 (Lei do Tombamento) estatui que","opcoes":["bens do patrimônio natural não estão sujeitos ao tombamento, mas apenas às restrições constantes da legislação de proteção à natureza.","o tombamento voluntário será realizado por meio de manifestação unilateral do proprietário, dispensado o pronunciamento do órgão de proteção do patrimônio cultural.","em caso de extravio ou furto de qualquer objeto tombado, o respectivo proprietário deverá dar conhecimento do fato ao órgão de proteção do patrimônio cultural, dentro do prazo de cinco dias, sob pena de multa de dez por cento sobre o valor da coisa.","as obras de origem estrangeira são imunes ao tombamento, seja qual for sua natureza.","em face da alienação onerosa de bens tombados, pertencentes a pessoas naturais ou a pessoas jurídicas de direito privado, a União, os Estados e os Municípios terão, nesta ordem, o direito de preferência."],"correta":2,"explicacao":"Gabarito: <strong>em caso de extravio ou furto de qualquer objeto tombado, o respectivo proprietário deverá dar conhecimento do fato ao órgão de proteção do patrimônio cultural, dentro do prazo de cinco dias, sob pena de multa de dez por cento sobre o valor da coisa.</strong>.","banca":"FCC","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"B":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"C":{"topico":"Tombamento — obrigação de conservação","ancora":"tombamento-art19-conservacao"},"D":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"E":{"topico":"Tombamento — alienação do bem tombado","ancora":"tombamento-alienacao"}}},{"id":4256100,"enunciado":"O Estado do Rio Grande do Sul celebrou acordo com o Município de Ibirapuitã para desapropriar por utilidade pública bem de domínio do município. Bianca, recém-ingressante no serviço público do município na qualidade de procuradora, tem dúvidas sobre a validade do acordo firmado. Considerando a situação narrada e apenas as disposições do Decreto-Lei nº 3.365/1941, assinale a alternativa INCORRETA.","opcoes":["O acordo celebrado entre o Estado do Rio Grande do Sul e o Município de Ibirapuitã dispensa autorização legislativa para desapropriação do bem por utilidade pública.","Os bens desapropriados para fins de utilidade pública não poderão ser alienados a terceiros.","É possível que as entidades que exerçam funções delegadas do poder público promovam desapropriação, desde que haja autorização expressa constante de lei ou contrato.","A construção de monumentos públicos configura caso de utilidade pública que pode ensejar a desapropriação por utilidade pública.","No processo de desapropriação, não pode o Judiciário decidir se estão presentes ou não os casos de utilidade pública."],"correta":1,"explicacao":"Gabarito: <strong>Os bens desapropriados para fins de utilidade pública não poderão ser alienados a terceiros.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Competência para desapropriar","ancora":"competencia-desapropriar"},"B":{"topico":"Tredestinação e retrocessão","ancora":"tredestinacao-retrocessao"},"C":{"topico":"Competência para desapropriar","ancora":"competencia-desapropriar"},"D":{"topico":"Hipóteses de utilidade pública","ancora":"hipoteses-utilidade-publica"},"E":{"topico":"Limites da matéria em juízo","ancora":"limite-materia-juizo"}}},{"id":4256133,"enunciado":"Fato administrativo pelo qual o Poder Público se apropria de um bem particular, sem a observância dos requisitos da declaração e da indenização prévia, ensejando o direito do esbulhado à indenização. Esse fato é nomeado de:","opcoes":["Requisição.","Desapropriação indireta.","Desapropriação confiscatória.","Retrocessão.","Tombamento."],"correta":1,"explicacao":"Gabarito: <strong>Desapropriação indireta.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Requisição administrativa","ancora":"requisicao-administrativa"},"B":{"topico":"Desapropriação indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"Imunidade à reforma agrária","ancora":"imunidade-reforma-agraria"},"D":{"topico":"Tredestinação e retrocessão","ancora":"tredestinacao-retrocessao"},"E":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"}}},{"id":4256208,"enunciado":"O tombamento pode ser caracterizado como uma limitação administrativa do direito de propriedade, visando a proteger, dentre outros, bens imóveis com relevante valor histórico, artístico ou arquitetônico. Acerca deste instituto, é correto afirmar:","opcoes":["o tombamento decorre de exercício discricionário da Administração Pública, prescindindo, nestes casos, de justa motivação, podendo ser questionado em juízo apenas se verificada ilegalidade.","o tombamento importa em esvaziamento absoluto do valor econômico da propriedade, sendo análogo, portanto, à hipótese de desapropriação indireta.","o tombamento se efetiva sempre mediante lei de iniciativa do Poder Executivo que, acolhendo parecer técnico exarado por órgão competente, submete a matéria à apreciação do Poder Legislativo, para deliberação.","o instituto jurídico do tombamento não se encontra em grau de hierarquia normativa superior aos instrumentos da política urbana."],"correta":3,"explicacao":"Gabarito: <strong>o instituto jurídico do tombamento não se encontra em grau de hierarquia normativa superior aos instrumentos da política urbana.</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"B":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"C":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"D":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"}}},{"id":4256256,"enunciado":"O Município de Venâncio Aires, mediante lei municipal, realizou o tombamento de bem imóvel de titularidade de particular. Sobre a situação apresentada, assinale a alternativa correta.","opcoes":["O ato legislativo em questão é inconstitucional, pois o tombamento de imóvel particular somente pode ser realizado pelo Poder Executivo.","O tombamento implica privação do uso do referido imóvel pelo seu proprietário.","O tombamento, no caso, implica desapropriação indireta.","A lei municipal pode estabelecer o tombamento parcial ou total do bem.","O tombamento implica, necessariamente, indenização ao particular."],"correta":3,"explicacao":"Gabarito: <strong>A lei municipal pode estabelecer o tombamento parcial ou total do bem.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"B":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"C":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"D":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"E":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"}}},{"id":4256257,"enunciado":"A instalação de redes de energia elétrica com finalidade pública que passa por propriedades particulares é considerada como forma de:","opcoes":["Desapropriação indireta, e somente será indenizada mediante ação proposta pelo particular.","Desapropriação direta, e somente será efetivada mediante prévia e justa indenização em dinheiro.","Servidão administrativa.","Requisição temporária.","Ocupação temporária."],"correta":2,"explicacao":"Gabarito: <strong>Servidão administrativa.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4256307,"enunciado":"Considerando as restrições, limitações e sacrifícios do direito de propriedade, é correto afirmar que o direito que tem o expropriado de exigir de volta o seu imóvel caso o mesmo não tenha o destino para que se desapropriou, isto é, a alienação do bem ao próprio expropriado é denominada especificamente de:","opcoes":["Requisição.","Retrocessão.","Tombamento.","Servidão administrativa.","Tredestinação."],"correta":1,"explicacao":"Gabarito: <strong>Retrocessão.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4256309,"enunciado":"Com relação à desapropriação e à jurisprudência do Superior Tribunal de Justiça sobre o tema, é CORRETO o que se afirma em:","opcoes":["Os juros moratórios, na desapropriação direta ou indireta, contam-se desde a data de publicação da sentença.","O valor dos honorários advocatícios em sede de desapropriação deve respeitar os limites impostos pelo artigo 27, § 1º, do Decreto-lei 3.365/41, quais sejam: entre 1% e 5% da diferença entre o valor proposto inicialmente pelo imóvel e a indenização imposta judicialmente.","A indenização decorrente de desapropriação encerra ganho de capital a atrair a incidência de imposto de renda.","Os honorários de advogado em desapropriação direta são calculados sobre a diferença entre a indenização e a oferta, corrigidas monetariamente.","A revelia do desapropriado implica aceitação tácita da oferta."],"correta":3,"explicacao":"Gabarito: <strong>Os honorários de advogado em desapropriação direta são calculados sobre a diferença entre a indenização e a oferta, corrigidas monetariamente.</strong>.","banca":"Avança SP","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"B":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"C":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"D":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"E":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"}}},{"id":4256459,"enunciado":"Considere que o Ministério Público, no âmbito de um inquérito civil, está apurando a omissão do Município X na realização de medidas efetivas para impedir que famílias localizadas em comunidades próximas ao rio Y sejam afetadas no período das chuvas. Em reunião técnica realizada na última semana, na sede do Ministério Público, compareceu engenheiro da Secretaria X informando que há um projeto com estudos avançados para a construção de uma lagoa de captação em determinada região da cidade para garantir a retenção da água das chuvas de determinados bairros e que esta entre no sistema de drenagem, impedindo a sobrecarga do rio em anos com chuvas dentro da normalidade ou 30% (trinta por cento) acima da normalidade. Relata, contudo, haver um gargalo financeiro para a sua implementação, pois há dúvidas sobre como seria viabilizado o pagamento da indenização das desapropriações dos imóveis localizados na região em que será implantada a lagoa, bem como um gargalo político, pois os moradores da área já estão se articulando para propor ações judiciais, questionando a legitimidade das desapropriações, e sinalizaram que não aceitarão os valores que o Município pretenda pagar de forma administrativa. Com base na situação hipotética, na legislação e na jurisprudência do Supremo Tribunal Federal, o Promotor de Justiça pode afirmar, de maneira correta, que","opcoes":["o Município, em função da urgência, efetuará o depósito judicial para viabilizar a imissão provisória na posse, bem como juros compensatórios, que incidirão a partir do trânsito em julgado da ação de desapropriação.","caso o Município ajuíze ações de desapropriação, os interessados não poderão propor ações diferentes tratando do mesmo assunto, pois a cognição que o Poder Judiciário pode exercer nas ações de desapropriação é ampla, abarcando a justiça da desapropriação e o próprio valor das indenizações.","caso a desapropriação não seja feita de forma amigável, o Poder Público poderá propor ação de desapropriação para viabilizar a imissão provisória na posse, devendo efetuar o pagamento da indenização ao final da ação, por meio do sistema de precatórios.","as desapropriações, independentemente da existência ou não de débitos em precatórios, devem ser viabilizadas mediante a realização de depósitos judiciais em dinheiro, pois a Constituição Federal assegura que os indivíduos que tenham os seus bens expropriados sejam indenizados de forma prévia e justa.","se o Município estiver em débito com precatórios e desejar fazer a imissão provisória na posse dos bens, deverá alegar urgência e efetuar o pagamento da indenização, de acordo com os critérios previstos na legislação. Ao final da ação, caso reconhecido que o valor foi inferior ao devido, deverá efetuar novo depósito judicial da parcela remanescente, que não se sujeitará ao sistema de precatórios."],"correta":4,"explicacao":"Gabarito: <strong>se o Município estiver em débito com precatórios e desejar fazer a imissão provisória na posse dos bens, deverá alegar urgência e efetuar o pagamento da indenização, de acordo com os critérios previstos na legislação. Ao final da ação, caso reconhecido que o valor foi inferior ao devido, deverá efetuar novo depósito judicial da parcela remanescente, que não se sujeitará ao sistema de precatórios.</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"stf tema 831 precatorios","ancora":"stf-tema-831-precatorios"},"B":{"topico":"stf tema 831 precatorios","ancora":"stf-tema-831-precatorios"},"C":{"topico":"stf tema 831 precatorios","ancora":"stf-tema-831-precatorios"},"D":{"topico":"stf tema 831 precatorios","ancora":"stf-tema-831-precatorios"},"E":{"topico":"stf tema 831 precatorios","ancora":"stf-tema-831-precatorios"}}},{"id":4256495,"enunciado":"Com fundamento na legislação vigente e na jurisprudência do STF relativas às modalidades de intervenção do Estado na propriedade, à improbidade administrativa, ao processo administrativo disciplinar, aos bens públicos e à responsabilidade civil do Estado, julgue o próximo item.\n\n\n\n\nOs prefeitos municipais sujeitam-se a legislação específica acerca do seu regime de responsabilidade político-administrativa, por isso estão eximidos das normas da Lei de Improbidade Administrativa.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"E":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"}}},{"id":4256496,"enunciado":"Com fundamento na legislação vigente e na jurisprudência do STF relativas às modalidades de intervenção do Estado na propriedade, à improbidade administrativa, ao processo administrativo disciplinar, aos bens públicos e à responsabilidade civil do Estado, julgue o próximo item.\n\n\n\n\nÉ possível a requisição administrativa, pelo estado do Espírito Santo, de bens e insumos contratados pelo município de Cachoeiro de Itapemirim e destinados à execução do plano local de imunização, na hipótese de decretação de estado de emergência em saúde.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"E":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"}}},{"id":4256497,"enunciado":"Com fundamento na legislação vigente e na jurisprudência do STF relativas às modalidades de intervenção do Estado na propriedade, à improbidade administrativa, ao processo administrativo disciplinar, aos bens públicos e à responsabilidade civil do Estado, julgue o próximo item.\n\n\n\n\nSegundo o entendimento do STF, a responsabilização de município por acidente em loja de fogos de artifício depende da comprovação da violação do dever jurídico específico do poder público de agir, mediante a concessão de licença, sem as cautelas legais ou a ciência de eventuais irregularidades praticadas pelo particular.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"E":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"}}},{"id":4256582,"enunciado":"Sobre a desapropriação e seu procedimento, é correto afirmar que:","opcoes":["A competência para legislar sobre desapropriação é concorrente entre União, Estados, Municípios e o D. Federal.","Particulares contratados pela Administração Pública não podem promover desapropriação.","A declaração de utilidade pública tem o poder de transferir a propriedade do bem objeto do ato.","Para cercar de legalidade o ato expropriatório, um dos elementos a serem atendidos pela Administração Pública é a identificação do sujeito passivo.","O prazo de caducidade do ato declaratório da desapropriação para fins de interesse social é de 05 (cinco) anos."],"correta":3,"explicacao":"Gabarito: <strong>Para cercar de legalidade o ato expropriatório, um dos elementos a serem atendidos pela Administração Pública é a identificação do sujeito passivo.</strong>.","banca":"UNIVIDA","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"competencia desapropriar","ancora":"competencia-desapropriar"},"B":{"topico":"competencia desapropriar","ancora":"competencia-desapropriar"},"C":{"topico":"competencia desapropriar","ancora":"competencia-desapropriar"},"D":{"topico":"competencia desapropriar","ancora":"competencia-desapropriar"},"E":{"topico":"competencia desapropriar","ancora":"competencia-desapropriar"}}},{"id":4256618,"enunciado":"Raimundo é proprietário de um imóvel de grandes dimensões, localizado em área rural, no Município de Pilar do Sul. Nos últimos anos, Raimundo tem sido fiscalizado e autuado por órgãos ambientais, devido às constantes áreas desmatadas sem autorização ambiental para supressão de vegetação. Verificou-se que a área é totalmente improdutiva e não cumpre sua função social. Diante do exposto, esse imóvel poderá ser","opcoes":["desapropriado por interesse social, para fins de reforma agrária, mediante prévia e justa indenização em títulos da dívida agrária, cuja competência é do Município.","confiscado e destinado à reforma agrária, mediante prévia e justa indenização em títulos da dívida agrária, cuja competência é do Município.","confiscado e destinado à reforma agrária, sem qualquer indenização ao proprietário e sem prejuízo de outras sanções previstas em lei.","desapropriado por interesse social, para fins de reforma agrária, mediante prévia e justa indenização em títulos da dívida agrária, cuja competência é da União.","confiscado e destinado à reforma agrária, mediante prévia e justa indenização em títulos da dívida agrária, cuja competência é da União."],"correta":3,"explicacao":"Gabarito: <strong>desapropriado por interesse social, para fins de reforma agrária, mediante prévia e justa indenização em títulos da dívida agrária, cuja competência é da União.</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"distincao instrumentos intervencao","ancora":"distincao-instrumentos-intervencao"},"B":{"topico":"distincao instrumentos intervencao","ancora":"distincao-instrumentos-intervencao"},"C":{"topico":"distincao instrumentos intervencao","ancora":"distincao-instrumentos-intervencao"},"D":{"topico":"distincao instrumentos intervencao","ancora":"distincao-instrumentos-intervencao"},"E":{"topico":"distincao instrumentos intervencao","ancora":"distincao-instrumentos-intervencao"}}},{"id":4256651,"enunciado":"Com o intuito de promover programa de moradia destinado à população de baixa renda, o Estado “X” pretende implantar um conjunto habitacional em terreno pertencente a determinado Município. Para execução de sua obra, celebrou contratação integrada com a empreiteira “W”, sendo que o contrato prevê que a contratada deverá promover a desapropriação do terreno em questão. No citado terreno, há um núcleo urbano informal, ocupado predominantemente por população de baixa renda. Diante de tal situação e nos termos da legislação aplicável,","opcoes":["não é possível delegar à empreiteira contratada os poderes expropriatórios, visto que apenas as delegatárias de serviço público podem exercer tal incumbência.","a autorização legislativa para a desapropriação não será necessária, visto que promover programas de construção de moradias e a melhoria das condições habitacionais é matéria de competência comum dos entes envolvidos na situação.","corre o prazo de dois anos, a partir da decretação da referida desapropriação, para efetivação da aludida desapropriação e início das providências de aproveitamento do bem expropriado.","a existência de núcleo urbano informal não exige providências por parte do ente expropriante, visto que a questão da posse não é objeto da ação de desapropriação.","tendo em vista a natureza de desapropriação por interesse social para cumprimento da função social da propriedade urbana, deverá ser aprovada lei municipal específica autorizando a desapropriação."],"correta":2,"explicacao":"Gabarito: <strong>corre o prazo de dois anos, a partir da decretação da referida desapropriação, para efetivação da aludida desapropriação e início das providências de aproveitamento do bem expropriado.</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"B":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"C":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"D":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"E":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"}}},{"id":4256893,"enunciado":"Sobre a desapropriação, o Decreto-lei nº 3.365/1942, que estabelece normas gerais sobre o instituto, em sua redação vigente preceitua:","opcoes":["E dispensada a autorização legislativa para desapropriação de bem de outro ente federativo, desde que seja realizado acordo entre os entes envolvidos, com fixação das respectivas responsabilidades financeiras relativas às indenizações.","Em razão do princípio da indisponibilidade do interesse público, não se poderá empregar arbitragem nos processos de desapropriação.","A concordância escrita do expropriado com a imissão na posse do bem pelo expropriante implica renúncia ao seu direito de questionar o preço ofertado em juízo.","A desapropriação deverá efetivar-se mediante acordo ou intentar-se judicialmente, dentro de cinco anos, contados da data da expedição do respectivo decreto e findos os quais este caducará definitivamente, sem possibilidade de renovação.","O expropriante poderá constituir servidões, que não serão indenizáveis."],"correta":0,"explicacao":"Gabarito: <strong>E dispensada a autorização legislativa para desapropriação de bem de outro ente federativo, desde que seja realizado acordo entre os entes envolvidos, com fixação das respectivas responsabilidades financeiras relativas às indenizações.</strong>.","banca":"FCC","ano":2023,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4256977,"enunciado":"Assinale a opção em que é corretamente indicado o prazo prescricional aplicável à desapropriação indireta na hipótese de o poder público realizar obras no local ou atribuir natureza de utilidade pública ou de interesse social ao imóvel.","opcoes":["3 anos","5 anos","10 anos","15 anos","20 anos"],"correta":2,"explicacao":"Gabarito: <strong>10 anos</strong>.","banca":"CESPE / CEBRASPE","ano":2023,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4256980,"enunciado":"No que diz respeito à intervenção do Estado na propriedade mediante tombamento e desapropriação, assinale a opção correta.","opcoes":["O tombamento implica transferência de propriedade do bem para o poder público.","O procedimento de desapropriação pode ser encerrado, atingindo todos os seus objetivos, por tramitação apenas na esfera administrativa.","O tombamento deve ter como objeto bem de valor histórico reconhecido.","É juridicamente válido ato de tombamento cuja única finalidade seja evitar novas edificações em determinado local, por motivos urbanísticos.","Bens incorpóreos não são passíveis de desapropriação."],"correta":1,"explicacao":"Gabarito: <strong>O procedimento de desapropriação pode ser encerrado, atingindo todos os seus objetivos, por tramitação apenas na esfera administrativa.</strong>.","banca":"CESPE / CEBRASPE","ano":2023,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"B":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"C":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"D":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"E":{"topico":"tombamento conceito","ancora":"tombamento-conceito"}}},{"id":4257028,"enunciado":"Acerca do tombamento do patrimônio nacional, assinale a opção correta.","opcoes":["O tombamento pode ser aplicado a monumentos naturais, sítios e paisagens cuja conservação e proteção sejam relevantes em razão da feição notável com que tenham sido dotados pela natureza ou agenciados pela indústria humana.","Para o tombamento de uma obra, exige-se a conjugação concomitante dos requisitos de excepcional valor arqueológico, etnográfico, bibliográfico e artístico, além da vinculação a fatos memoráveis da história do Brasil.","Excluem-se do tombamento as obras de origem estrangeira, exceto quando constituírem bens públicos de valor histórico pertencentes ao país estrangeiro.","Prescinde-se de autorização do Serviço do Patrimônio Histórico e Artístico Nacional para a colocação de anúncios ou cartazes na área de vizinhança de coisa tombada.","No caso de o proprietário não ter recursos para obras de conservação e reparação, o Serviço do Patrimônio Histórico e Artístico Nacional deverá promover a desapropriação da coisa tombada."],"correta":0,"explicacao":"Gabarito: <strong>O tombamento pode ser aplicado a monumentos naturais, sítios e paisagens cuja conservação e proteção sejam relevantes em razão da feição notável com que tenham sido dotados pela natureza ou agenciados pela indústria humana.</strong>.","banca":"CESPE / CEBRASPE","ano":2023,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"B":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"C":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"D":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"E":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"}}},{"id":4257132,"enunciado":"Acerca da intervenção do Estado na propriedade privada, assinale a opção incorreta.","opcoes":["Na desapropriação indireta, o proprietário do bem afetado deve recorrer às vias judiciais para obter indenização do poder público, observado o prazo prescricional de cinco anos.","A imissão provisória na posse de imóvel objeto de expropriação depende de decisão judicial e exige a requisição de urgência da medida pelo expropriante, no prazo de 120 dias, bem como o depósito do montante arbitrado pelo juízo.","Por meio de ocupação temporária, o poder público utiliza, transitoriamente, bem imóvel privado, cuja utilidade pública é auxiliar à execução de determinada obra ou serviço público, indenizável ou não.","A limitação administrativa pode ocorrer por ato administrativo ou legislativo, caracterizando-se pela imposição geral a proprietários indeterminados, de obrigações positivas ou negativas, em benefício de interesse público genérico, sem direito à indenização por parte do Estado.","É exemplo de requisição administrativa ato do Corpo de Bombeiros Militar por meio do qual este utilize barcos particulares em operações de salvamento de pessoas vítimas de naufrágio."],"correta":0,"explicacao":"Gabarito: <strong>Na desapropriação indireta, o proprietário do bem afetado deve recorrer às vias judiciais para obter indenização do poder público, observado o prazo prescricional de cinco anos.</strong>.","banca":"CESPE / CEBRASPE","ano":2023,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"B":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"C":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"D":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"E":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"}}},{"id":4257159,"enunciado":"Sobre o Tombamento, assinale a alternativa correta:","opcoes":["O tombamento de coisa pertencente à pessoa natural ou à pessoa jurídica de direito privado se fará voluntária ou compulsoriamente.","Proceder-se-á ao tombamento compulsório sempre que o proprietário o pedir e a coisa se revestir dos requisitos necessários para constituir parte integrante do patrimônio histórico e artístico nacional, a juízo do Conselho Consultivo do Serviço do Patrimônio Histórico e Artístico Nacional, ou sempre que o mesmo proprietário anuir, por escrito, à notificação, que se lhe fizer, para a inscrição da coisa em qualquer dos Livros do Tombo.","As coisas tombadas, que pertençam à União, aos Estados ou aos Municípios, inalienáveis por natureza, só poderão ser transferidas por sentença judicial transitada em julgado.","Somente a Administração Pública Federal poderá realizar tombamentos."],"correta":0,"explicacao":"Gabarito: <strong>O tombamento de coisa pertencente à pessoa natural ou à pessoa jurídica de direito privado se fará voluntária ou compulsoriamente.</strong>.","banca":"TJ-AM","ano":2023,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"livros tombo","ancora":"livros-tombo"},"B":{"topico":"livros tombo","ancora":"livros-tombo"},"C":{"topico":"livros tombo","ancora":"livros-tombo"},"D":{"topico":"livros tombo","ancora":"livros-tombo"}}},{"id":4257252,"enunciado":"De acordo com o disposto na Constituição Federal de 1988 a respeito de política urbana, julgue o item subsequente.\nAs desapropriações de prédios urbanos serão feitas mediante justa indenização em títulos da dívida pública, aprovada pelo chefe do Executivo, com acordo de resgate até um ano após a imissão na posse pelo Estado no imóvel desapropriado.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2023,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"distincao instrumentos intervencao","ancora":"distincao-instrumentos-intervencao"},"E":{"topico":"distincao instrumentos intervencao","ancora":"distincao-instrumentos-intervencao"}}},{"id":4257253,"enunciado":"Acerca de desapropriação de bens, julgue o item seguinte. \n\n\n\n\nHavendo interesse coincidente entre a União, os estados e os municípios em desapropriar o mesmo bem privado, terá preferência o ente federativo que primeiro iniciar o processo de desapropriação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2023,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4257254,"enunciado":"Acerca de desapropriação de bens, julgue o item seguinte. \n\n\n\n\nSão passíveis de desapropriação bens de sociedade de economia mista federal, incumbida de explorar atividade econômica em regime de exclusividade, desde que mediante autorização do Congresso Nacional.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2023,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4257255,"enunciado":"Acerca de desapropriação de bens, julgue o item seguinte. \n\n\n\n\nOs estados e o Distrito Federal não podem desapropriar bens da União, assim como não podem os municípios desapropriar bens dos estados ou da União.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2023,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4257318,"enunciado":"Julgue o item a seguir, acerca da intervenção do Estado na propriedade, à luz da doutrina e do entendimento do Supremo Tribunal Federal (STF). \nSegundo entendimento jurisprudencial do STF, a requisição de bens e serviços de um ente federativo por outro não ofende o princípio federativo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2023,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"E":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"}}},{"id":4257319,"enunciado":"Julgue o item a seguir, acerca da intervenção do Estado na propriedade, à luz da doutrina e do entendimento do Supremo Tribunal Federal (STF). \nA servidão administrativa constitui direito real público que autoriza o Estado a usar propriedade imóvel particular para permitir a execução de obras ou serviços de interesse coletivo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2023,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4257382,"enunciado":"Com base na Constituição Federal, ressalvados os casos previstos nessa Constituição, mediante justa e prévia indenização em dinheiro, a lei estabelecerá o procedimento para desapropriação por: I. Necessidade Pública. II. Utilidade Privada. III. Interesse Social. Quais estão corretas?","opcoes":["Apenas II.","Apenas I e II.","Apenas I e III.","Apenas II e III.","I, II e III."],"correta":2,"explicacao":"Gabarito: <strong>Apenas I e III.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4257397,"enunciado":"No que se refere à intervenção do Estado na propriedade, assinale a opção correta.","opcoes":["O tombamento tem por objeto bens imóveis que tenham interesse cultural ou ambiental para a preservação da memória, mas não deve ser aplicado a bens móveis.","A desapropriação é um ato que suprime o direito de propriedade em razão da conduta de culpa do proprietário.","A utilização, pelo poder público, de uma escola privada, para a instalação de zonas eleitorais, configura limitação administrativa.","Nos casos em que houver a requisição administrativa, o proprietário do bem que sofrer a requisição terá direito a uma indenização posterior, independentemente de o bem ter ou não sofrido dano.","A servidão administrativa consiste no direito real de gozo, de natureza pública, sobre imóvel de propriedade alheia."],"correta":4,"explicacao":"Gabarito: <strong>A servidão administrativa consiste no direito real de gozo, de natureza pública, sobre imóvel de propriedade alheia.</strong>.","banca":"CESPE / CEBRASPE","ano":2023,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"B":{"topico":"Conceito e natureza jurídica da desapropriação","ancora":"conceito-desapropriacao"},"C":{"topico":"Requisição administrativa","ancora":"requisicao-administrativa"},"D":{"topico":"Requisição administrativa","ancora":"requisicao-administrativa"},"E":{"topico":"Servidão administrativa","ancora":"servidao-administrativa"}}},{"id":4257466,"enunciado":"Acerca do tombamento e à luz do Decreto-lei n.º 25/1937, assinale a opção correta.","opcoes":["O tombamento abarca tanto os bens culturais materiais, móveis e imóveis, quanto manifestações puramente simbólicas.","Qualquer obra de interesse público pode ser incluída no patrimônio histórico e artístico nacional, inclusive as obras de origem estrangeira, sem restrição.","O tombamento de coisa pertencente à pessoa natural ou à pessoa jurídica de direito privado se fará voluntária ou compulsoriamente.","Apesar de obras importantes, os bens tombados são alienáveis."],"correta":0,"explicacao":"Gabarito: <strong>O tombamento abarca tanto os bens culturais materiais, móveis e imóveis, quanto manifestações puramente simbólicas.</strong>.","banca":"CESPE / CEBRASPE","ano":2023,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"B":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"C":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"D":{"topico":"tombamento conceito","ancora":"tombamento-conceito"}}},{"id":4257467,"enunciado":"O Município de Campo Bom realizou a desapropriação de determinada área urbana para a ampliação de uma escola pública. No cálculo do valor a ser pago como retribuição pela desapropriação, os juros compensatórios incidem a partir do (a):","opcoes":["Decreto expropriatório.","Notificação do proprietário.","Trânsito em julgado.","Sentença.","Imissão na posse."],"correta":4,"explicacao":"Gabarito: <strong>Imissão na posse.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"B":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"C":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"D":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"E":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"}}},{"id":4257472,"enunciado":"A desapropriação por interesse social, para fins de reforma agrária, de imóvel rural que não esteja cumprindo sua função social compete","opcoes":["à União e aos estados, concorrentemente.","aos estados.","aos municípios.","à União."],"correta":3,"explicacao":"Gabarito: <strong>à União.</strong>.","banca":"CESPE / CEBRASPE","ano":2023,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4257528,"enunciado":"Dentre as modalidades de intervenção estatal na propriedade privada, estão a servidão administrativa e o tombamento. Doutrina majoritária, na esteira do pensamento de Celso Antônio Bandeira de Mello, firma entendimento de que o tombamento é um tipo específico de servidão, cuja finalidade é a preservação do patrimônio histórico, cultural, arqueológico, artístico, turístico ou paisagístico. Para a doutrina minoritária, a exemplo de José Cretella Júnior, a natureza jurídica do tombamento é de limitação administrativa, consistindo em instrumento de intervenção restritiva do Estado na propriedade privada. A respeito do tombamento, a partir dos balizamentos legais, é CORRETO afirmar que:","opcoes":["São susceptíveis de tombamento as obras de origem estrangeira que pertençam às representações diplomáticas ou consulares acreditadas no país.","São espécies de tombamento o voluntário e o compulsório, podendo, ambos, serem considerados provisórios ou definitivos, conforme esteja o respectivo processo iniciado pela notificação ou concluído pela inscrição dos referidos bens no competente Livro do Tombo.","Na hipótese de ampliação de um imóvel tombado, poderá o proprietário solicitar posterior autorização do Serviço do Patrimônio Histórico e Artístico para realizar reparos de natureza estética.","Podem ser tombados bens, exclusivamente os bens pertencentes às pessoas físicas."],"correta":1,"explicacao":"Gabarito: <strong>São espécies de tombamento o voluntário e o compulsório, podendo, ambos, serem considerados provisórios ou definitivos, conforme esteja o respectivo processo iniciado pela notificação ou concluído pela inscrição dos referidos bens no competente Livro do Tombo.</strong>.","banca":"CONSULPAM","ano":2023,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4257711,"enunciado":"A disciplina jurídica da desapropriação indireta aplica-se","opcoes":["à expropriação legal do espólio no curso do inventário.","à expropriação legal de ações de uma empresa privada.","à alienação de bem para descaracterizar tredestinação.","à expropriação legal de marca comercial de empresa.","ao apossamento, pelo poder público, de bem imóvel de propriedade privada."],"correta":4,"explicacao":"Gabarito: <strong>ao apossamento, pelo poder público, de bem imóvel de propriedade privada.</strong>.","banca":"CESPE / CEBRASPE","ano":2023,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4257790,"enunciado":"No que se refere a desapropriação urbana, assinale a alternativa que não corresponde ao entendimento sumulado do Superior Tribunal de Justiça:","opcoes":["Os honorários de advogado em desapropriação direta são calculados sobre a diferença entre a indenização e a oferta, corrigidos monetariamente.","Os juros compensatórios, na desapropriação indireta, incidem a partir da ocupação, calculados sobre o valor da indenização, corrigido monetariamente.","Os juros compensatórios, na desapropriação direta, incidem a partir da imissão na posse, calculados sobre o valor da indenização, corrigido monetariamente.","A incidência dos juros moratórios sobre os compensatórios, nas ações expropriatórias, constitui anatocismo vedado em lei."],"correta":3,"explicacao":"Gabarito: <strong>A incidência dos juros moratórios sobre os compensatórios, nas ações expropriatórias, constitui anatocismo vedado em lei.</strong>.","banca":"UniRV - GO","ano":2022,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"B":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"C":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"D":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"}}},{"id":4257791,"enunciado":"A desapropriação urbana, por utilidade pública, é regulamentada pelo Decreto-Lei n. 3.365/1941. Sobre esta norma, assinale a alternativa correta:","opcoes":["Ao Poder Judiciário é permitido, no processo de desapropriação, decidir se se verificam ou não os casos de utilidade pública.","A desapropriação deverá efetivar-se mediante acordo ou intentar-se judicialmente, dentro de dez anos, contados da data da expedição do respectivo decreto e findos os quais este caducará.","Intentada ação judicial de desapropriação, a contestação só poderá versar sobre vício do processo judicial ou impugnação do preço; qualquer outra questão deverá ser decidida por ação direta.","Os bens expropriados, uma vez incorporados à Fazenda Pública, podem ser objeto de reivindicação, ainda que fundada em nulidade do processo de desapropriação."],"correta":2,"explicacao":"Gabarito: <strong>Intentada ação judicial de desapropriação, a contestação só poderá versar sobre vício do processo judicial ou impugnação do preço; qualquer outra questão deverá ser decidida por ação direta.</strong>.","banca":"UniRV - GO","ano":2022,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4257796,"enunciado":"No início do ano de 2020, os diversos níveis de governo foram surpreendidos pela pandemia de coronavírus declarada pela Organização Mundial de Saúde (OMS). A rápida transmissão da covid-19 ocasionou a insuficiência de equipamentos e insumos hospitalares para atendimento da população contaminada pelo coronavírus na rede pública de saúde, tais como respiradores, máscaras, medicamentos, entre outros. Em razão desse quadro, governadores e prefeitos brasileiros passaram a utilizar, compulsória e temporariamente, bens e serviços de particulares para enfrentamento da situação de emergência de saúde pública. A modalidade de intervenção do Estado na propriedade privada que corresponde à situação narrada na questão é:","opcoes":["Limitação administrativa.","Requisição administrativa.","Servidão administrativa.","Desapropriação."],"correta":1,"explicacao":"Gabarito: <strong>Requisição administrativa.</strong>.","banca":"UniRV - GO","ano":2022,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Limitação administrativa","ancora":"limitacao-administrativa"},"B":{"topico":"Requisição administrativa","ancora":"requisicao-administrativa"},"C":{"topico":"Servidão administrativa","ancora":"servidao-administrativa"},"D":{"topico":"Conceito e natureza jurídica da desapropriação","ancora":"conceito-desapropriacao"}}},{"id":4257848,"enunciado":"É forma de intervenção do Estado supressiva da propriedade privada:","opcoes":["Servidão administrativa.","Requisição administrativa.","Tombamento.","Desapropriação.","Limitação administrativa."],"correta":3,"explicacao":"Gabarito: <strong>Desapropriação.</strong>.","banca":"FUNDATEC","ano":2022,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Servidão administrativa","ancora":"servidao-administrativa"},"B":{"topico":"Requisição administrativa","ancora":"requisicao-administrativa"},"C":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"D":{"topico":"Conceito e natureza jurídica da desapropriação","ancora":"conceito-desapropriacao"},"E":{"topico":"Limitação administrativa","ancora":"limitacao-administrativa"}}},{"id":4257914,"enunciado":"A servidão administrativa difere das demais modalidades de intervenção na propriedade nos seguintes termos:","opcoes":["da desapropriação, porque impõe sacrifício inerente à condição de administrado, não autorizando, portanto, indenização ao titular da propriedade que a suportar.","do tombamento, porque a servidão sempre obriga o ente público que a impõe o dever de indenizar o titular da propriedade que a suporta.","da limitação administrativa, que impõe sacrifício ordinário ao proprietário, enquanto a servidão administrativa pode acarretar restrição à exploração econômica da propriedade, ensejando direito à indenização.","da desapropriação, porque depende de anuência do proprietário do imóvel para sua imposição, não admitindo imposição mediante poder de império.","da requisição administrativa, porque esta se impõe apenas sobre parte do imóvel e a servidão acarreta restrição permanente na totalidade do imóvel onde for imposta."],"correta":2,"explicacao":"Gabarito: <strong>da limitação administrativa, que impõe sacrifício ordinário ao proprietário, enquanto a servidão administrativa pode acarretar restrição à exploração econômica da propriedade, ensejando direito à indenização.</strong>.","banca":"FCC","ano":2022,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4258033,"enunciado":"Constitui o patrimônio histórico e artístico nacional o conjunto dos bens móveis e imóveis existentes no país e cuja conservação seja de interesse público, quer por sua vinculação a fatos memoráveis da história do Brasil, quer por seu excepcional valor arqueológico ou etnográfico, bibliográfico ou artístico. Acerca da organização e da proteção do patrimônio histórico e artístico nacional é correto afirmar, EXCETO:","opcoes":["Proceder-se-á ao tombamento compulsório quando o proprietário se recusar a anuir à inscrição da coisa.","As coisas tombadas, que pertençam à União, aos Estados ou aos Municípios, inalienáveis por natureza, só poderão ser transferidas de uma a outra das referidas entidades.","No livro do tombo das belas artes serão inscritas as obras que se incluírem na categoria das artes aplicadas, nacionais ou estrangeiras.","Coisa tombada não poderá sair do país, senão por curto prazo, sem transferência de domínio e para fim de intercâmbio cultural, a juízo do Conselho Consultivo do Serviço do Patrimônio Histórico e Artístico Nacional."],"correta":2,"explicacao":"Gabarito: <strong>No livro do tombo das belas artes serão inscritas as obras que se incluírem na categoria das artes aplicadas, nacionais ou estrangeiras.</strong>.","banca":"IESES","ano":2022,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"livros tombo","ancora":"livros-tombo"},"B":{"topico":"livros tombo","ancora":"livros-tombo"},"C":{"topico":"livros tombo","ancora":"livros-tombo"},"D":{"topico":"livros tombo","ancora":"livros-tombo"}}},{"id":4258072,"enunciado":"Assinale a opção correta acerca da intervenção do Estado na propriedade.","opcoes":["As restrições ao direito de propriedade impostas por normas ambientais não configuram desapropriação indireta.","A servidão administrativa, em regra, depende de registro para produzir seus efeitos.","As limitações administrativas geram, em regra, o dever de indenizar.","Na desapropriação confiscatória, a indenização se dá por títulos da dívida pública.","Com o efetivo registro no livro do tombo, a coisa tombada passar a ser considerada como bem público."],"correta":0,"explicacao":"Gabarito: <strong>As restrições ao direito de propriedade impostas por normas ambientais não configuram desapropriação indireta.</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Desapropriação indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"Servidão administrativa","ancora":"servidao-administrativa"},"C":{"topico":"Limitação administrativa","ancora":"limitacao-administrativa"},"D":{"topico":"Imunidade à reforma agrária","ancora":"imunidade-reforma-agraria"},"E":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"}}},{"id":4258242,"enunciado":"De acordo com o Superior Tribunal de Justiça, o prazo prescricional aplicável à desapropriação indireta, na hipótese em que poder público tenha realizado obras no local ou atribuído natureza de utilidade pública ou de interesse social ao imóvel, é de","opcoes":["20 anos.","10 anos.","2 anos.","3 anos.","5 anos."],"correta":1,"explicacao":"Gabarito: <strong>10 anos.</strong>.","banca":"VUNESP","ano":2022,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4258266,"enunciado":"O poder público, visando à interiorização da energia elétrica em determinado estado, instalou torres de transmissão em pequenas áreas de algumas propriedades privadas. Assinale a opção que apresenta a modalidade de intervenção do Estado na propriedade retratada na situação hipotética apresentada.","opcoes":["ocupação temporária","requisição","tombamento","servidão administrativa","limitação administrativa"],"correta":3,"explicacao":"Gabarito: <strong>servidão administrativa</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Ocupação temporária","ancora":"ocupacao-temporaria"},"B":{"topico":"Requisição administrativa","ancora":"requisicao-administrativa"},"C":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"D":{"topico":"Servidão administrativa","ancora":"servidao-administrativa"},"E":{"topico":"Limitação administrativa","ancora":"limitacao-administrativa"}}},{"id":4258301,"enunciado":"O Prefeito de Teresina editou decreto de tombamento de imóvel de propriedade de sua família sem estudo que comprove o seu valor histórico. O ato administrativo é","opcoes":["ilegal diante da ausência de competência para o ato, que é exclusivo do Conselho Municipal do Patrimônio Cultural de Teresina.","legítimo, pois o tombamento, independentemente de seu fundamento, traz proteção para o imóvel.","lícito, desde que se comprove a ausência de prejuízo a terceiro de boa-fé.","lícito, pois cabe ao Chefe do Poder Executivo Municipal, de forma discricionária, promover o tombamento do Patrimônio Municipal.","ilegal diante do desvio de finalidade."],"correta":4,"explicacao":"Gabarito: <strong>ilegal diante do desvio de finalidade.</strong>.","banca":"FCC","ano":2022,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"B":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"C":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"D":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"E":{"topico":"tombamento conceito","ancora":"tombamento-conceito"}}},{"id":4258302,"enunciado":"A Administração pública pretende impor um recuo de 10 metros para um único lote existente em determinada quadra, mantendo-se o recuo de 2 metros previsto em lei aos demais. Analisando o processo, o Procurador do Município deverá","opcoes":["deixar de se manifestar por ser tema de competência do Ministério Público.","sugerir que o processo seja encaminhado para manifestação do Tribunal de Contas.","chancelar a limitação administrativa pretendida.","consignar que o ato administrativo pretendido tem natureza de servidão administrativa sem direito à indenização.","consignar que o ato administrativo pretendido acarretará o ajuizamento de uma ação de desapropriação indireta."],"correta":4,"explicacao":"Gabarito: <strong>consignar que o ato administrativo pretendido acarretará o ajuizamento de uma ação de desapropriação indireta.</strong>.","banca":"FCC","ano":2022,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4258346,"enunciado":"A respeito do Programa Minha Casa, Minha Vida (PMCMV), do parcelamento do solo urbano, da política urbana, da desapropriação, da proteção do patrimônio cultural, entre outros temas do direito urbanístico, julgue o item a seguir.\n\n\n\n\nEmbora as modalidades de desapropriação por utilidade pública e por interesse social se diferenciem quanto às hipóteses de cabimento e à finalidade, ambas adotam o mesmo procedimento expropriatório.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4258506,"enunciado":"No que tange ao instituto da desapropriação, conforme os mandamentos constitucionais e legais aplicáveis à espécie, assinale a opção correta.","opcoes":["Toda desapropriação de propriedade nociva à coletividade prescindirá de prévia e justa indenização.","A desapropriação é uma forma de aquisição originária da propriedade, na medida em que a aquisição não está vinculada à situação jurídica anterior e o bem ingressa no domínio público livre de ônus, gravames ou relações jurídicas de natureza real ou pessoal.","A desapropriação decorre de ato administrativo, pautado no interesse público, pelo qual o Estado transforma um imóvel de terceiro em bem público, com fundamento na necessidade pública ou no interesse social, desde que esse imóvel não cumpra sua função social.","No procedimento de desapropriação, o poder público transfere para si a propriedade de outrem, sem necessidade de prévia reparação financeira, desde que por razões de utilidade pública ou de interesse social.","A desapropriação é a transferência compulsória da propriedade do particular ao poder público, decorrente da supremacia do interesse público sobre o particular, de maneira tal que prescinde de indenização."],"correta":1,"explicacao":"Gabarito: <strong>A desapropriação é uma forma de aquisição originária da propriedade, na medida em que a aquisição não está vinculada à situação jurídica anterior e o bem ingressa no domínio público livre de ônus, gravames ou relações jurídicas de natureza real ou pessoal.</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4258534,"enunciado":"Em relação ao tombamento, de acordo com o decreto-lei nº 25/1937, assinale a alternativa CORRETA.","opcoes":["Proceder-se-à ao tombamento compulsório sempre que o proprietário o pedir e a coisa se revestir dos requisitos necessários para constituir parte integrante do patrimônio histórico e artístico nacional, a juízo do Conselho Consultivo do Serviço do Patrimônio Histórico e Artístico Nacional, ou sempre que o mesmo proprietário anuir, por escrito, à notificação, que se lhe fizer, para a inscrição da coisa em qualquer dos Livros do Tombo.","A coisa tombada poderá sair do país, por longo prazo, com transferência de domínio e para fim de intercâmbio cultural, a juízo do Conselho Consultivo do Serviço do Patrimônio Histórico e Artístico Nacional.","O tombamento dos bens pertencentes à União, aos Estados e aos Municípios se fará de ofício, por ordem do diretor do Serviço do Patrimônio Histórico e Artístico Nacional, mas deverá ser notificado à entidade a quem pertencer, ou sob cuja guarda estiver a coisa tombada, afim de produzir os necessários efeitos.","O Poder Legislativo providenciará a realização de acordos entre a União e os Estados, para melhor coordenação e desenvolvimento das atividades relativas à proteção do patrimônio histórico e artístico nacional e para a uniformização da legislação estadual complementar sobre o mesmo assunto.","Proceder-se-á ao tombamento voluntário quando o proprietário se recusar a anuir à inscrição da coisa."],"correta":2,"explicacao":"Gabarito: <strong>O tombamento dos bens pertencentes à União, aos Estados e aos Municípios se fará de ofício, por ordem do diretor do Serviço do Patrimônio Histórico e Artístico Nacional, mas deverá ser notificado à entidade a quem pertencer, ou sob cuja guarda estiver a coisa tombada, afim de produzir os necessários efeitos.</strong>.","banca":"Unesc","ano":2022,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"B":{"topico":"Tombamento — saída do território nacional","ancora":"art14-saida-territorio"},"C":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"D":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"E":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"}}},{"id":4258535,"enunciado":"A desapropriação é regulamentada pelo decreto-lei nº 3.365/1941. Neste sentido, assinale a alternativa CORRETA.","opcoes":["Os bens do domínio dos Estados, Municípios, Distrito Federal e Territórios poderão ser desapropriados pela União, e os dos Municípios pelos Estados, e não há necessidade do ato preceder autorização legislativa.","A desapropriação poderá abranger a área contígua necessária ao desenvolvimento da obra a que se destina, e as zonas que se valorizarem extraordinariamente, em consequência da realização do serviço. Em qualquer caso, a declaração de utilidade pública deverá compreendê-las, mencionando-se quais as indispensaveis à continuação da obra e as que se destinam à revenda.","Ao imóvel desapropriado para implantação de parcelamento popular, destinado às classes de menor renda, poderá se dar outra utilização, assim como poderá ocorrer retrocessão.","A desapropriação do espaço aéreo ou do subsolo só se tornará necessária, quando de sua utilização resultar benefício patrimonial do proprietário do solo.","Em regra, é facultativa a desapropriação, pelos Estados, Distrito Federal, Territórios e Municípios de ações, cotas e direitos representativos do capital de instituições e empresas cujo funcionamento dependa de autorização do Governo Federal e se subordine à sua fiscalização."],"correta":1,"explicacao":"Gabarito: <strong>A desapropriação poderá abranger a área contígua necessária ao desenvolvimento da obra a que se destina, e as zonas que se valorizarem extraordinariamente, em consequência da realização do serviço. Em qualquer caso, a declaração de utilidade pública deverá compreendê-las, mencionando-se quais as indispensaveis à continuação da obra e as que se destinam à revenda.</strong>.","banca":"Unesc","ano":2022,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4258585,"enunciado":"O governo do estado do Piauí, por meio do Decreto n.º 20.201/2021, determinou o tombamento do edifício do Sanatório Meduna e seu entorno. Acerca desse contexto, com base no regramento sobre o tombamento, é correto afirmar que","opcoes":["o tombamento do imóvel se efetivou com a publicação do referido decreto.","o ato de tombamento envolve duas fases: uma administrativa, outra judicial.","a propriedade do imóvel onde está localizado o edifício do Sanatório Meduna passou a ser do estado do Piauí.","o proprietário do imóvel onde se localiza o Sanatório Meduna deve ter sido indenizado.","as coisas tombadas não poderão, em caso nenhum, ser destruídas, demolidas ou mutiladas."],"correta":4,"explicacao":"Gabarito: <strong>as coisas tombadas não poderão, em caso nenhum, ser destruídas, demolidas ou mutiladas.</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"B":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"C":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"D":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"E":{"topico":"tombamento conceito","ancora":"tombamento-conceito"}}},{"id":4258691,"enunciado":"Acerca da desapropriação com pagamento em títulos, prevista na Lei n. 10.257/2001, que estabelece diretrizes gerais da política urbana, é correto afirmar:","opcoes":["O aproveitamento do imóvel poderá ser efetivado diretamente pelo Poder Público ou por meio de alienação ou concessão a terceiros, observando-se, nesses casos, o devido procedimento licitatório.","Decorridos três anos de cobrança do IPTU progressivo sem que o proprietário tenha cumprido a obrigação de parcelamento, edificação ou utilização, o Município poderá proceder à desapropriação do imóvel, com pagamento em títulos da dívida pública.","O valor real da indenização computará expectativas de ganhos, lucros cessantes e juros compensatórios.","Os títulos da dívida pública terão prévia aprovação pelo Congresso Nacional e serão resgatados no prazo de até dez anos, em prestações anuais, iguais e sucessivas, assegurados o valor real da indenização e os juros legais de seis por cento ao ano."],"correta":0,"explicacao":"Gabarito: <strong>O aproveitamento do imóvel poderá ser efetivado diretamente pelo Poder Público ou por meio de alienação ou concessão a terceiros, observando-se, nesses casos, o devido procedimento licitatório.</strong>.","banca":"IESES","ano":2021,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"B":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"C":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"D":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"}}},{"id":4258692,"enunciado":"Leia atentamente as proposições abaixo e assinale a que se apresentar INCORRETA:","opcoes":["Na concessão, o poder de alteração unilateral das cláusulas regulamentares confere à administração a possibilidade de alterar as condições do funcionamento do serviço, podendo o concessionário se opor às alterações exigidas, desde que o objeto da concessão não tenha sido desnaturado.","Para o STJ, há necessidade do efetivo desapossamento para a caracterização da desapropriação indireta.","O prazo prescricional aplicável à desapropriação indireta, na hipótese em que o Poder Público tenha realizado obras no local ou atribuído natureza de utilidade pública ou de interesse social ao imóvel, é de 10 anos, conforme parágrafo único do art. 1.238 do CC.","É quinquenal o prazo prescricional para pleitear reparação decorrente de limitação administrativa."],"correta":0,"explicacao":"Gabarito: <strong>Na concessão, o poder de alteração unilateral das cláusulas regulamentares confere à administração a possibilidade de alterar as condições do funcionamento do serviço, podendo o concessionário se opor às alterações exigidas, desde que o objeto da concessão não tenha sido desnaturado.</strong>.","banca":"IESES","ano":2021,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Desapropriação indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"Desapropriação indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"Desapropriação indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"Limitação administrativa","ancora":"limitacao-administrativa"}}},{"id":4258696,"enunciado":"O poder público editou um decreto de desapropriação com a finalidade de construir um aeroporto regional em determinado município. Tal decreto incluiu, além da área necessária à realização do empreendimento, zona do entorno que se valorizará extraordinariamente em consequência da realização da obra pública e onde o poder público planeja a construção de um distrito industrial, com a consequente revenda da área urbanizada para particulares. Acerca dessa situação hipotética, assinale a opção correta à luz da legislação federal pertinente.","opcoes":["O decreto de desapropriação, relativamente à zona do entorno, é ilegal, uma vez que a legislação exige a comprovação da destinação específica da área para o objeto principal da desapropriação, que é a construção do aeroporto.","A desapropriação do entorno do futuro aeroporto é ilegal por ausência de previsão legal de desapropriação por zona e porque o poder público já dispõe de instrumento específico para tributar áreas que, em razão de obras públicas, tiverem elevada valorização, como é o caso da contribuição de melhoria.","Será legal a desapropriação da zona do entorno do futuro aeroporto, desde que esta seja objeto de declaração de utilidade pública específica, sendo vedada a utilização do mesmo decreto desapropriatório para as duas áreas.","É legal a desapropriação, inclusive em relação à zona do entorno do futuro aeroporto."],"correta":3,"explicacao":"Gabarito: <strong>É legal a desapropriação, inclusive em relação à zona do entorno do futuro aeroporto.</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao por zona","ancora":"desapropriacao-por-zona"},"B":{"topico":"desapropriacao por zona","ancora":"desapropriacao-por-zona"},"C":{"topico":"desapropriacao por zona","ancora":"desapropriacao-por-zona"},"D":{"topico":"desapropriacao por zona","ancora":"desapropriacao-por-zona"}}},{"id":4258787,"enunciado":"O direito real de gozo pelo Poder Público ou seus delegados sobre imóvel de propriedade alheia, mediante autorização legal, em favor de um serviço público ou de um bem afetado a fim de utilidade pública, é conhecido como","opcoes":["desapropriação indireta.","perdimento de bens.","tombamento.","retrocessão.","servidão administrativa."],"correta":4,"explicacao":"Gabarito: <strong>servidão administrativa.</strong>.","banca":"VUNESP","ano":2021,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4258842,"enunciado":"Acerca da intervenção do Estado na propriedade, assinale a opção correta.","opcoes":["A servidão administrativa pode ser formalmente estabelecida por edição de decreto do chefe do Poder Executivo.","A requisição de bens imóveis de particulares depende de autorização do Poder Judiciário.","Instituição de limitação administrativa, ainda que frustre pretensão de particular, não enseja o pagamento de indenização.","Por serem bens públicos inalienáveis, imóveis de patrimônio de município não pode ser desapropriado pela União.","Retrocessão consiste na utilização do bem desapropriado em finalidade pública diversa daquela que justificou o ato desapropriatório."],"correta":2,"explicacao":"Gabarito: <strong>Instituição de limitação administrativa, ainda que frustre pretensão de particular, não enseja o pagamento de indenização.</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Servidão administrativa","ancora":"servidao-administrativa"},"B":{"topico":"Requisição administrativa","ancora":"requisicao-administrativa"},"C":{"topico":"Limitação administrativa","ancora":"limitacao-administrativa"},"D":{"topico":"Regime jurídico dos bens públicos","ancora":"regime-bens-publicos"},"E":{"topico":"Tredestinação e retrocessão","ancora":"tredestinacao-retrocessao"}}},{"id":4258857,"enunciado":"Com relação a uma casa hipotética situada em um centro histórico municipal que constitui área tombada pelo Instituto do Patrimônio Histórico e Artístico Nacional (IPHAN), julgue o item subsequente, com base nas disposições legais relacionadas ao tema e na jurisprudência do STJ.\nA prefeitura municipal pode estabelecer um tombamento municipal sobre a mesma área já tombada pelo IPHAN.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"E":{"topico":"tombamento conceito","ancora":"tombamento-conceito"}}},{"id":4258959,"enunciado":"Sobre a requisição administrativa, pode-se afirmar que","opcoes":["é ato administrativo negocial em que a administração pública e o particular negociam as cláusulas principais de sua realização como tempo e indenização.","tem natureza de direito real, no qual o Poder Público passa a deter a propriedade do bem requisitado.","está no âmbito da competência legislativa privativa da União.","podem ser objeto de requisição administrativa apenas bens imóveis e móveis; os serviços particulares só podem ser contratados, ainda que emergencialmente.","a requisição e a desapropriação são institutos administrativos semelhantes se diferenciando apenas porque a indenização, no primeiro caso, é prévia e, no segundo, é a posteriori."],"correta":4,"explicacao":"Gabarito: <strong>a requisição e a desapropriação são institutos administrativos semelhantes se diferenciando apenas porque a indenização, no primeiro caso, é prévia e, no segundo, é a posteriori.</strong>.","banca":"FADESP","ano":2021,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"B":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"C":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"D":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"E":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"}}},{"id":4259128,"enunciado":"A propósito do procedimento da desapropriação, a redação vigente do Decreto-lei n° 3.365/1941 estatui que","opcoes":["a desapropriação deverá se efetivar mediante acordo ou judicialmente, dentro de 5 (cinco) anos, contados da data da expedição do respectivo decreto e, decorrido tal prazo, este caducará.","notificado administrativamente o expropriado, ele terá o prazo de 15 (quinze) dias para aceitar ou rejeitar a oferta de indenização, sendo que o silêncio será considerado aceitação.","a alegação de urgência deve constar obrigatoriamente do decreto de utilidade pública e obrigará o expropriante a requerer a imissão provisória dentro do prazo improrrogável de 120 (cento e vinte) dias a contar de sua publicação.","uma vez notificado pelo expropriante, o particular que não concordar com a indenização oferecida poderá optar por resolver a questão por mediação ou arbitragem.","a ação, quando a União for autora, será proposta no Distrito Federal ou no foro da Capital do Estado onde for domiciliado o réu, perante o juízo privativo, se houver; se for o Estado o autor, será proposta no foro da Capital respectiva; sendo outro o autor, no foro da situação dos bens."],"correta":3,"explicacao":"Gabarito: <strong>uma vez notificado pelo expropriante, o particular que não concordar com a indenização oferecida poderá optar por resolver a questão por mediação ou arbitragem.</strong>.","banca":"FCC","ano":2020,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"B":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"C":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"D":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"E":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"}}},{"id":4259140,"enunciado":"O instituto que garante ao expropriado o direito de exigir a devolução do bem objeto da desapropriação que não foi utilizado pela Administração para atendimento do interesse público denomina-se","opcoes":["desapropriação por zona.","direito de extensão.","direito de preferência.","direito de retrocessão.","tredestinação."],"correta":3,"explicacao":"Gabarito: <strong>direito de retrocessão.</strong>.","banca":"VUNESP","ano":2020,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4259144,"enunciado":"No tocante ao instituto jurídico da desapropriação, assinale a alternativa correta.","opcoes":["A desapropriação atinge o caráter perpétuo do direito de propriedade.","A desapropriação de glebas que contenham culturas ilegais de plantas psicotrópicas dispensa indenização prévia.","O pagamento de indenização na desapropriação por necessidade pública pode ser feito em títulos da dívida pública.","Os bens de concessionárias de serviço público não são passíveis de desapropriação.","O Estado pode desapropriar bem de empresa pública federal afeto a serviço público."],"correta":0,"explicacao":"Gabarito: <strong>A desapropriação atinge o caráter perpétuo do direito de propriedade.</strong>.","banca":"VUNESP","ano":2020,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4259236,"enunciado":"No Direito Administrativo, sobre a desapropriação confiscatória, é possível afirmar que:","opcoes":["É vedada por previsão expressa na Constituição Federal.","Possui caráter excepcional, sendo autorizada apenas nos casos previstos na Constituição Federal.","Possui caráter excepcional e será indenizada em títulos da dívida pública, resgatáveis em vinte anos.","Ocorre quando o ente público se apodera de bem particular para a construção de obra pública, sem prévio procedimento expropriatório.","A indenização será paga em dinheiro, no prazo de vinte anos."],"correta":3,"explicacao":"Gabarito: <strong>Ocorre quando o ente público se apodera de bem particular para a construção de obra pública, sem prévio procedimento expropriatório.</strong>.","banca":"FUNDATEC","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4259252,"enunciado":"Julgue os itens a seguir sobre a desapropriação: I- A desapropriação não é autorizada pelo ordenamento jurídico brasileiro, por força do princípio da inviolabilidade da propriedade privada; II- O procedimento de licitação é realizado em uma fase única denominada declaratória, na qual a Administração Pública declara o interesse público no imóvel e passa a se tornar titular da posse imediatamente; III- A natureza jurídica da desapropriação é de direito público, compreende procedimento complexo, em cujas fases se observam, sucessivamente o direito constitucional, administrativo, e se houver processo judicial, também o direito processual civil; IV- Desapropriação é instituto de direito público que se consubstancia em procedimento mediante o qual o Poder Público ou o delegatário, quando autorizado por lei ou contrato, visa alcançar a transferência compulsória da propriedade de outrem, fundado em declaração de necessidade de utilidade pública ou interesse social, mediante o pagamento de justa indenização. Dos itens acima:","opcoes":["Apenas os itens I e IV estão corretos.","Apenas os itens II e III estão corretos.","Apenas os itens III e IV estão corretos.","Apenas os itens I e III estão corretos.","Apenas os itens I e II estão corretos."],"correta":2,"explicacao":"Gabarito: <strong>Apenas os itens III e IV estão corretos.</strong>.","banca":"IDCAP","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4259281,"enunciado":"A desapropriação por necessidade pública, utilidade pública ou interesse social, assegurada prévia a justa indenização em dinheiro, prevista no inciso XXIV do art. 5° da Constituição Federal.","opcoes":["constitui sanção pelo descumprimenlo da função social dá propriedade urbana.","pode ter por objeto imóvel que cumpre a função social da propriedade.","trata do confisco de imóvel utilizado para o cultivo de plantas psicotrópicas","caracteriza sanção pelo descumprimento à função social da propriedade rural."],"correta":1,"explicacao":"Gabarito: <strong>pode ter por objeto imóvel que cumpre a função social da propriedade.</strong>.","banca":"VUNESP","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4259332,"enunciado":"O tombamento é um ato administrativo realizado pelo Poder Público com o objetivo de preservar bens de valores históricos, culturais, arquitetônicos e ambientais para a população como um todo. Sobre o instituto do tombamento, analise as afirmativas a seguir: I. O tombamento não poderá atingir bens móveis particulares, pois se trata de ato do poder público de interesse coletivo; II. O tombamento poderá ter duas formas, sendo estas compulsórias (de ofício) ou voluntárias (por solicitação ou anuência do interessado); III. O proprietário de um bem particular poderá dispor livremente do bem tombado para fins de alienação, apenas sendo necessário que o adquirente tenha o compromisso de conservar este bem, em conformidade com o ato; IV. O tombamento definitivo dos bens de propriedade particular será, por iniciativa do órgão competente do Serviço do Patrimônio Histórico e Artístico Nacional, transcrito para os devidos efeitos em livro a cargo dos oficiais do registro de imóveis e averbado ao lado da transcrição do domínio. Com base nas assertivas, assinale a opção correta:","opcoes":["Estão incorretas as alternativas I e III, apenas;","Está correto a alternativa II, apenas;","Está incorreta a alternativa I, apenas;","Estão corretas as alternativas I e IV, apenas."],"correta":2,"explicacao":"Gabarito: <strong>Está incorreta a alternativa I, apenas;</strong>.","banca":"INSTITUTO PRÓ-MUNICÍPIO","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tombamento alienacao","ancora":"tombamento-alienacao"},"B":{"topico":"tombamento alienacao","ancora":"tombamento-alienacao"},"C":{"topico":"tombamento alienacao","ancora":"tombamento-alienacao"},"D":{"topico":"tombamento alienacao","ancora":"tombamento-alienacao"}}},{"id":4259333,"enunciado":"A desapropriação por utilidade pública regula-se por legislação especial própria, e pode ser conceituada como um processo administrativo, no qual ocorre a transferência de um bem particular ao domínio público, com fundamento na necessidade pública, utilidade pública ou no interesse social. Levando em conta o que foi dito acima, quanto à lei especial para desapropriação por utilidade pública, marque a alternativa correta:","opcoes":["Todos os bens poderão ser desapropriados pela União e pelos Estados, apenas;","A desapropriação por necessidade pública advém de uma situação de emergência, na qual o ente público se vê na obrigação de resolver a situação o mais breve possível, de maneira imediata;","A desapropriação irá abranger somente a área necessária para a realização da obra a que se destina o ato, não sendo incorporadas a isso áreas que valorizem por consequência do serviço;","A declaração de utilidade pública só poderá ser feita pelo Presidente da República, ainda que se trate de ato emergencial."],"correta":2,"explicacao":"Gabarito: <strong>A desapropriação irá abranger somente a área necessária para a realização da obra a que se destina o ato, não sendo incorporadas a isso áreas que valorizem por consequência do serviço;</strong>.","banca":"INSTITUTO PRÓ-MUNICÍPIO","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4259345,"enunciado":"A desapropriação, hipótese de sacrifício do direito de propriedade particular é, o procedimento pelo qual, o Poder Público retira de seu dono a propriedade de certo bem móvel ou imóvel, compulsoriamente, adquirindo-o para si em caráter originário. Sobre o assunto, assinale a alternativa que apresenta corretamente o entendimento sumulado do Supremo Tribunal Federal e/ou do Superior Tribunal de Justiça.","opcoes":["A imissão provisória na posse não viola a Constituição Federal","Os juros compensatórios, na desapropriação indireta, incidem a partir da citação no processo de desapropriação","Não cabem honorários do advogado do expropriado na indenização por desapropriação","A invasão do imóvel é causa de prosseguimento do processo expropriatório para fins de reforma agrária"],"correta":0,"explicacao":"Gabarito: <strong>A imissão provisória na posse não viola a Constituição Federal</strong>.","banca":"IBFC","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"E":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"}}},{"id":4259349,"enunciado":"Acerca da intervenção do estado na propriedade, marque a alternativa INCORRETA:","opcoes":["a servidão pública não precisa recair sobre bens imóveis determinados, nem precisa, necessariamente, ser registrada no Cartório de Registro de Imóveis, produzindo efeitos erga omnes desde sua decretação publicada em imprensa oficial.","a servidão administrativa ostenta a qualidade de direito real, sendo, neste caso, de natureza pública.","a servidão se configura na utilização na utilização de um bem privado pelo ente estatal para a prestação de um determinado serviço público ou execução de atividade de interesse público.","caso o particular não concorde com o valor ofertado pelo Estado, a servidão deverá ser instituída mediante sentença judicial que, após a realização de perícia, determinará o pagamento de montante indenizatório justo previamente à utilização do bem pelo Estado."],"correta":0,"explicacao":"Gabarito: <strong>a servidão pública não precisa recair sobre bens imóveis determinados, nem precisa, necessariamente, ser registrada no Cartório de Registro de Imóveis, produzindo efeitos erga omnes desde sua decretação publicada em imprensa oficial.</strong>.","banca":"FADESP","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4259390,"enunciado":"No tocante à ação de desapropriação por utilidade pública, analise os seguintes itens. I. Conforme entendimento do STJ, o possuidor de terras faz jus à indenização decorrente da perda do direito possessório em consequência da desapropriação. II. Nos termos da lei, o valor da indenização será contemporâneo à data da avaliação judicial, não sendo relevante a data em que ocorreu a imissão na posse. III. A base de cálculo dos honorários de advogado em desapropriação é a diferença entre a oferta e a indenização, corrigidas ambas monetariamente. IV. Na ação de desapropriação por utilidade pública, a citação do proprietário do imóvel desapropriado dispensa a citação do respectivo cônjuge. Nesse contexto, pode-se afirmar:","opcoes":["Todos os itens são corretos.","Todos os itens são incorretos.","São corretos os itens II e IV, apenas.","São corretos os itens I e III, apenas."],"correta":0,"explicacao":"Gabarito: <strong>Todos os itens são corretos.</strong>.","banca":"FUNDEP (Gestão de Concursos)","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"notificacao oferta indenizacao","ancora":"notificacao-oferta-indenizacao"},"B":{"topico":"notificacao oferta indenizacao","ancora":"notificacao-oferta-indenizacao"},"C":{"topico":"notificacao oferta indenizacao","ancora":"notificacao-oferta-indenizacao"},"D":{"topico":"notificacao oferta indenizacao","ancora":"notificacao-oferta-indenizacao"}}},{"id":4259392,"enunciado":"Sobre a intervenção do Estado na propriedade privada, analise as afirmativas a seguir. I. Servidão administrativa consiste na autorização do Poder Público para usar o imóvel de propriedade particular, desde que mediante lei previamente editada. II. A obrigação de observar o recuo de alguns metros das construções em terrenos urbanos e a proibição de construir além de determinado número de pavimentos são exemplos de limitações administrativas. III. Pela requisição, o Poder Público fica autorizado a utilizar de maneira permanente bens móveis, imóveis e serviços particulares em situação de perigo público iminente. IV. Caso a administração dê destinação diferente daquela para a qual o imóvel foi desapropriado, o expropriado tem direito de preferência, pelo preço atual da coisa, salvo no caso de tredestinação lícita. Estão corretas as afirmativas","opcoes":["II e IV, apenas.","I e III, apenas","II, III, IV, apenas.","I, II, III e IV."],"correta":0,"explicacao":"Gabarito: <strong>II e IV, apenas.</strong>.","banca":"FUNDEP (Gestão de Concursos)","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"1":{"topico":"Servidão administrativa","ancora":"servidao-administrativa"},"2":{"topico":"Limitação administrativa","ancora":"limitacao-administrativa"},"3":{"topico":"Requisição administrativa","ancora":"requisicao-administrativa"},"4":{"topico":"Tredestinação e retrocessão","ancora":"tredestinacao-retrocessao"}}},{"id":4259419,"enunciado":"Uma empresa privada venceu licitação para construir e explorar uma linha elevada de monotrilho. Todavia, ao iniciar a execução da obra, observou que o traçado planejado passaria sobre terrenos privados ainda não construídos, atualmente explorados para plantio de hortaliças pelos respectivos proprietários, incentivados por programa municipal de horta urbana, que lhes concede isenção do IPTU. Sabe-se que a operação da linha elevada não impedirá a continuidade dessa exploração pelos proprietários, ressalvada a ocupação temporária de parcela dos terrenos, durante a execução das obras. O instituto adequado para promover a intervenção na propriedade, no caso em tela, é","opcoes":["o tombamento.","a desapropriação.","a requisição administrativa.","a servidão administrativa.","o arrendamento compulsório."],"correta":3,"explicacao":"Gabarito: <strong>a servidão administrativa.</strong>.","banca":"FCC","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4259453,"enunciado":"Assinale a opção que indica a denominação dada ao direito do expropriado de exigir de volta o imóvel objeto de desapropriação na hipótese de o poder público não dar o destino adequado ao bem desapropriado.","opcoes":["desapropriação indireta","enfiteuse","tredestinação","retrocessão","servidão administrativa"],"correta":3,"explicacao":"Gabarito: <strong>retrocessão</strong>.","banca":"CESPE / CEBRASPE","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4259472,"enunciado":"A respeito da Requisição, Servidão Administrativa e Tombamento, assinale a alternativa correta.","opcoes":["As servidões administrativas podem incidir sobre bens imóveis, móveis e direitos.","As requisições administrativas incidem sobre bens móveis ou serviços de particulares, não podendo incidir sobre bens imóveis.","De acordo com o STJ, como não há dispositivo expresso proibindo a hierarquização para o tombamento, os municípios podem tombar bens públicos estaduais.","O tombamento pode ser voluntário ou compulsório, mas não pode ser instituído de ofício.","O tombamento geral ou global depende da individualização de todos os bens no ato do tombamento e exige a prévia notificação de cada proprietário, de acordo com o STJ."],"correta":2,"explicacao":"Gabarito: <strong>De acordo com o STJ, como não há dispositivo expresso proibindo a hierarquização para o tombamento, os municípios podem tombar bens públicos estaduais.</strong>.","banca":"VUNESP","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Servidão administrativa","ancora":"servidao-administrativa"},"B":{"topico":"Requisição administrativa","ancora":"requisicao-administrativa"},"C":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"D":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"E":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"}}},{"id":4259473,"enunciado":"Suponha que o Município de São José dos Campos deseja desapropriar, por razões de utilidade pública, um imóvel localizado na zona urbana da cidade e que pertence a Maria. Após a fase declaratória do procedimento para consumação da desapropriação, iniciou-se a fase executória e o Poder Público ofereceu proposta a Maria, mas ela não concordou. Em face da impossibilidade do acordo na via administrativa, o Município de São José dos Campos propôs ação judicial de desapropriação em face da proprietária do bem. Visando promover o interesse público, o Poder Público deseja imitir-se provisoriamente na posse do bem ainda no curso do processo judicial. Considerando a situação hipotética, é correto afirmar que","opcoes":["a imissão provisória na posse pressupõe urgência e depósito prévio. Cabe ao Município avaliar discricionariamente a urgência na imissão provisória e ao Judiciário analisar o ato que alegou urgência, sendo lícito ao juiz substituir o mérito administrativo.","após alegar a urgência, que poderá ser renovada pelo tempo necessário, o Poder Público tem o prazo improrrogável de 180 (cento e oitenta dias) para requerer a imissão provisória.","para que a declaração de urgência com fins de imissão provisória na posse seja considerada como válida, deve ser realizada exclusivamente no próprio decreto expropriatório.","de acordo com o entendimento do STJ, o depósito judicial do valor simplesmente apurado pelo corpo técnico do ente público, sendo inferior ao valor arbitrado por perito judicial e ao valor cadastral do imóvel, não viabiliza a imissão provisória na posse.","Maria poderá levantar, independentemente de concordância do Município de São José dos Campos, até 70% (setenta por cento) do depósito efetivado com fins de imissão provisória na posse."],"correta":3,"explicacao":"Gabarito: <strong>de acordo com o entendimento do STJ, o depósito judicial do valor simplesmente apurado pelo corpo técnico do ente público, sendo inferior ao valor arbitrado por perito judicial e ao valor cadastral do imóvel, não viabiliza a imissão provisória na posse.</strong>.","banca":"VUNESP","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"},"B":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"},"C":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"},"D":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"},"E":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"}}},{"id":4259506,"enunciado":"Sobre a ação de desapropriação por utilidade pública, marque V para as afirmativas verdadeiras e F para as falsas. ( ) São devidos honorários advocatícios em percentual fixado pelo juiz sobre a diferença entre a oferta e a indenização, corrigidas ambas monetariamente. ( ) Ficam sub-rogados no valor da indenização quaisquer ônus incidentes sobre o bem expropriado, tais como hipoteca, penhora ou usufruto. ( ) Não cabe desistência da ação desapropriatória após o depósito judicial do preço e o deferimento da imissão provisória do expropriante na posse. ( ) Os débitos fiscais serão deduzidos dos valores depositados para pagamento da indenização, ainda que não inscritos em dívida ativa. Assinale a sequência correta.","opcoes":["F, F, V, V","V, F, F, V","F, V, V, F","V, V, F, F"],"correta":3,"explicacao":"Gabarito: <strong>V, V, F, F</strong>.","banca":"Prefeitura de Rondonópolis - MT","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"B":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"C":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"D":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"}}},{"id":4259511,"enunciado":"O Município de Fortaleza, na defesa do patrimônio histórico da cidade, promoveu o tombamento de um casarão. O proprietário do imóvel ingressou em juízo pleiteando indenização, que","opcoes":["será devida se houver o esvaziamento do direito de propriedade, sendo o tombamento, neste caso, uma desapropriação indireta.","será devida em razão da natureza jurídica de limitação administrativa ao direito de propriedade do tombamento.","não será devida, ainda que haja o esvaziamento do direito de propriedade, tendo em vista a natureza jurídica de limitação administrativa ao direito de propriedade do tombamento.","será destinada, pelo Poder Judiciário, ao Fundo de Interesses Difusos e Coletivos, cabendo ao proprietário do imóvel apresentar projetos de restauração do bem para captar o valor.","será utilizada, por determinação do Poder Judiciário, apenas para a manutenção e para a restauração do bem."],"correta":0,"explicacao":"Gabarito: <strong>será devida se houver o esvaziamento do direito de propriedade, sendo o tombamento, neste caso, uma desapropriação indireta.</strong>.","banca":"FCC","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4259554,"enunciado":"A respeito da desapropriação, assinale a alternativa correta.","opcoes":["A aquisição de imóvel por desapropriação é derivada, ficando o Poder Público responsável pelos débitos relativos ao bem.","Os bens da União, sem a sua concordância, poderão ser desapropriados por Estados e Municípios.","A declaração de utilidade pública far-se-á por decreto do Presidente da República, Governador, Interventor ou Prefeito.","Ao Poder Judiciário é permitido, no processo de desapropriação, decidir se se verificam ou não os casos de utilidade pública.","A revelia do desapropriado implica aceitação tácita da oferta, autorizando a dispensa da avaliação."],"correta":2,"explicacao":"Gabarito: <strong>A declaração de utilidade pública far-se-á por decreto do Presidente da República, Governador, Interventor ou Prefeito.</strong>.","banca":"VUNESP","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4259579,"enunciado":"De acordo com o STJ, a indenização pela limitação administrativa ao direito de edificar, advinda da criação de área non aedificandi, somente é devida na hipótese de","opcoes":["a limitação ser imposta sobre imóvel rural, independentemente do prejuízo causado ao proprietário da área.","a restrição administrativa configurar situação de desapropriação indireta.","ficar demonstrado o prejuízo causado ao proprietário da área, independentemente da localização do imóvel.","a restrição administrativa ter sido criada por disposição legal genérica e o imóvel situar-se em área rural.","a limitação ser imposta sobre imóvel urbano, desde que fique demonstrado o prejuízo causado ao proprietário da área."],"correta":4,"explicacao":"Gabarito: <strong>a limitação ser imposta sobre imóvel urbano, desde que fique demonstrado o prejuízo causado ao proprietário da área.</strong>.","banca":"CESPE / CEBRASPE","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4259599,"enunciado":"A Administração pública de determinado município executou a implantação de um emissário de esgoto subterrâneo em área de expansão urbana que ainda não era atendida por serviço de saneamento básico. Diante da urgência da obra, segundo narrativa da própria Administração, somente após a execução da obra o Município deu início à regularização do equipamento, o que, levando em conta as suas características e finalidade,","opcoes":["deve se dar por meio de desapropriação, tendo em vista que o equipamento instalado acarreta transferência dominial do local de instalação ao município, como bem reversível.","deve se dar mediante desapropriação indireta, porque a aquisição da propriedade pelo Município se deu posteriormente à execução da obra.","pode ser regularizada mediante a instituição de servidão administrativa, não se alterando a titularidade dominial da área para o Município.","prescinde da edição de qualquer ato formal, considerando a natureza de limitação administrativa da restrição, porque prestante à execução de serviço público essencial.","pode se dar por meio de ocupação temporária, porque a obra, embora destinada à prestação de serviços público, tem instalação reversível."],"correta":2,"explicacao":"Gabarito: <strong>pode ser regularizada mediante a instituição de servidão administrativa, não se alterando a titularidade dominial da área para o Município.</strong>.","banca":"FCC","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4259669,"enunciado":"A respeito da desapropriação, assinale a alternativa correta.","opcoes":["A declaração de utilidade pública ou de interesse social para fins de desapropriação caduca em cinco anos, caso não efetivada a desapropriação nesse período.","A desapropriação é procedimento de competência privativa do Poder Público e, como tal, não comporta a delegação de qualquer de seus atos a agentes privados.","É facultado ao Poder Público municipal exigir do proprietário do solo urbano não edificado ou subutilizado que promova seu adequado aproveitamento, sob pena de desapropriação com pagamento mediante títulos da dívida pública, com prazo de resgate de até dez anos.","É facultado ao Poder Público municipal desapropriar por interesse social, para fins de reforma agrária, o imóvel rural que não esteja cumprindo sua função social, mediante prévia e justa indenização em títulos da dívida agrária.","A desapropriação por necessidade ou utilidade pública, ou por interesse social, exige justa e prévia indenização em dinheiro, sem exceções."],"correta":2,"explicacao":"Gabarito: <strong>É facultado ao Poder Público municipal exigir do proprietário do solo urbano não edificado ou subutilizado que promova seu adequado aproveitamento, sob pena de desapropriação com pagamento mediante títulos da dívida pública, com prazo de resgate de até dez anos.</strong>.","banca":"VUNESP","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4259701,"enunciado":"Na intervenção do Estado na propriedade particular, as limitações administrativas:","opcoes":["Decorrem de atos administrativos de caráter específico, dirigidos a indivíduos determinados.","Tem caráter transitório.","Representa forma de desapropriação por interesse social.","Não geram direito à indenização.","Implica a perda da propriedade."],"correta":0,"explicacao":"Gabarito: <strong>Decorrem de atos administrativos de caráter específico, dirigidos a indivíduos determinados.</strong>.","banca":"FUNDATEC","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4259715,"enunciado":"A desapropriação de área contígua necessária ao desenvolvimento da obra a que se destina, caracteriza:","opcoes":["Desapropriação por zona.","Desapropriação por interesse social.","Desapropriação urbanística.","Desapropriação indireta."],"correta":0,"explicacao":"Gabarito: <strong>Desapropriação por zona.</strong>.","banca":"IESES","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao por zona","ancora":"desapropriacao-por-zona"},"B":{"topico":"desapropriacao por zona","ancora":"desapropriacao-por-zona"},"C":{"topico":"desapropriacao por zona","ancora":"desapropriacao-por-zona"},"D":{"topico":"desapropriacao por zona","ancora":"desapropriacao-por-zona"}}},{"id":4259725,"enunciado":"A respeito da declaração de utilidade pública para fins de desapropriação, afirma-se que","opcoes":["declarada a utilidade pública, ficam as autoridades administrativas autorizadas a penetrar nos prédios compreendidos na declaração, podendo recorrer, em caso de oposição, ao auxílio de força policial.","a declaração de utilidade pública far-se-á por lei de iniciativa do Chefe do Executivo.","ao Poder Judiciário é permitido, no processo de desapropriação, decidir se se verificam ou não os casos de utilidade pública.","a desapropriação poderá abranger a área contígua necessária ao desenvolvimento da obra a que se destina, ainda que a declaração de utilidade pública não a compreenda.","a desapropriação deverá efetivar-se dentro de cinco anos, contados da data da expedição da declaração e findos os quais esta caducará, sendo, neste caso, vedada nova declaração de utilidade pública do mesmo bem."],"correta":0,"explicacao":"Gabarito: <strong>declarada a utilidade pública, ficam as autoridades administrativas autorizadas a penetrar nos prédios compreendidos na declaração, podendo recorrer, em caso de oposição, ao auxílio de força policial.</strong>.","banca":"VUNESP","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"art7 penetrar predios","ancora":"art7-penetrar-predios"},"B":{"topico":"art7 penetrar predios","ancora":"art7-penetrar-predios"},"C":{"topico":"art7 penetrar predios","ancora":"art7-penetrar-predios"},"D":{"topico":"art7 penetrar predios","ancora":"art7-penetrar-predios"},"E":{"topico":"art7 penetrar predios","ancora":"art7-penetrar-predios"}}},{"id":4259730,"enunciado":"A Lei nº 9.790/99, que dispõe sobre a qualificação de pessoas jurídicas de direito privado, sem fins lucrativos, como Organizações da Sociedade Civil de Interesse Público, instituiu uma das principais inovações no Terceiro Setor. É correto afirmar que o enunciado se refere a um novo instrumento jurídico, denominado","opcoes":["protocolo de intenções.","acordo de leniência.","termo de parceria.","desapropriação indireta.","contrato de consórcio."],"correta":2,"explicacao":"Gabarito: <strong>termo de parceria.</strong>.","banca":"VUNESP","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4259733,"enunciado":"A desapropriação consiste em modalidade de intervenção do Estado na propriedade, por meio da qual o poder público, por motivo de necessidade ou utilidade pública, adquire determinado bem considerado relevante para o desempenho das funções estatais. A respeito do instituto, assinale a alternativa correta.","opcoes":["Em caso de desapropriação judicial, a diferença entre o valor depositado pela Administração e o arbitrado na sentença não se sujeita ao regime de precatórios, devendo a entidade pública efetuar o pagamento em dinheiro.","Os bens expropriados, uma vez incorporados à Fazenda Pública, podem ser objeto de reivindicação, caso o bem seja empregado em atividade diversa da finalidade pública que justificou a desapropriação.","Se houver concordância, reduzida a termo, do expropriado, a decisão concessiva da imissão provisória na posse implicará a aquisição da propriedade pelo expropriante com o consequente registro da propriedade na matrícula do imóvel.","A imissão provisória na posse, realizada em função da desapropriação, pressupõe a citação do desapropriado e o pagamento de indenização prévia e justa em dinheiro, nos termos do art. 5º , XXIV, da Constituição Federal.","A desapropriação, que conte com a concordância do particular, equivale a um contrato de compra e venda, o que implicará na manutenção dos ônus reais incidentes sobre o bem após a transferência da propriedade para o Estado."],"correta":2,"explicacao":"Gabarito: <strong>Se houver concordância, reduzida a termo, do expropriado, a decisão concessiva da imissão provisória na posse implicará a aquisição da propriedade pelo expropriante com o consequente registro da propriedade na matrícula do imóvel.</strong>.","banca":"VUNESP","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"B":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"C":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"D":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"E":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"}}},{"id":4259751,"enunciado":"A respeito da desapropriação, é correto afirmar que","opcoes":["é forma secundária de aquisição da propriedade.","a desapropriação indireta enseja juros compensatórios desde a perda da posse.","é vedada por lei a desapropriação por zona.","a declaração de utilidade pública deve ser feita, em regra, por meio de lei.","a imissão provisória na posse é concedida com o depósito de 50% do valor da avaliação provisória."],"correta":1,"explicacao":"Gabarito: <strong>a desapropriação indireta enseja juros compensatórios desde a perda da posse.</strong>.","banca":"VUNESP","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao por zona","ancora":"desapropriacao-por-zona"},"B":{"topico":"desapropriacao por zona","ancora":"desapropriacao-por-zona"},"C":{"topico":"desapropriacao por zona","ancora":"desapropriacao-por-zona"},"D":{"topico":"desapropriacao por zona","ancora":"desapropriacao-por-zona"},"E":{"topico":"desapropriacao por zona","ancora":"desapropriacao-por-zona"}}},{"id":4259797,"enunciado":"Na hipótese de rescisão unilateral de contrato administrativo, a administração pública poderá promover a apropriação provisória dos bens e do serviço vinculado ao objeto do contrato para evitar a interrupção de sua execução. Essa medida representa uma cláusula exorbitante que se materializa em intervenção do Estado na propriedade privada na modalidade denominada","opcoes":["limitação administrativa.","requisição administrativa.","ocupação temporária.","servidão administrativa.","retrocessão."],"correta":2,"explicacao":"Gabarito: <strong>ocupação temporária.</strong>.","banca":"CESPE / CEBRASPE","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4259849,"enunciado":"Em relação ao tema desapropriação e conforme as Súmulas do Supremo Tribunal Federal e do Superior Tribunal de Justiça, assinale a alternativa correta.","opcoes":["No processo de desapropriação, não são devidos juros compensatórios desde a antecipada imissão de posse, ordenada pelo juiz, por motivo de urgência.","Verificados os pressupostos legais para o licenciamento de uma obra, impedem a declaração de utilidade pública para desapropriação do imóvel.","Pela demora no pagamento do preço da desapropriação cabe indenização complementar além dos juros compensatórios.","Na desapropriação para instituir servidão administrativa não são devidos os juros compensatórios pela limitação de uso da propriedade.","É necessária prévia autorização do Presidente da República para desapropriação, pelos Estados, de empresa de energia elétrica."],"correta":4,"explicacao":"Gabarito: <strong>É necessária prévia autorização do Presidente da República para desapropriação, pelos Estados, de empresa de energia elétrica.</strong>.","banca":"VUNESP","ano":2018,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"B":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"C":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"D":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"E":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"}}},{"id":4260027,"enunciado":"“Corresponde à obrigação do expropriante de ofertar ao expropriado o bem, sempre que receber destinação diversa da pretendida e indicada no ato expropriatório, mediante a devolução da indenização paga”. O enunciado corresponde corretamente ao conceito de","opcoes":["imissão provisória.","desapropriação imprópria.","servidão administrativa.","retrocessão.","ocupação temporária."],"correta":4,"explicacao":"Gabarito: <strong>ocupação temporária.</strong>.","banca":"VUNESP","ano":2018,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4260037,"enunciado":"Em relação ao tombamento de bens imóveis, considere: I. Será determinado, no entorno do bem tombado, área de proteção que garanta a sua visibilidade, ambiência e integração, devendo ser previamente autorizados quaisquer tipos de alterações, tais como obras, mobiliário urbano, propaganda e iluminação que direta ou indiretamente interfiram no bem tombado. II. O ato de tombamento poderá ser cancelado no caso de perecimento do bem tombado, ou de desvirtuamento completo do objeto em relação ao motivo do tombamento. III. Os documentos oficiais comprobatórios da propriedade de imóveis tombados individualmente ou localizados em áreas de tombamento de conjunto, expedidos por tabeliães do Estado, ficarão dispensados de quaisquer taxas ou emolumentos quando solicitados pelo Departamento de Patrimônio Histórico, Artístico e Paisagístico da Secretaria da Cultura, para efeitos de proteção e preservação do Acervo Cultural Maranhense. IV. O pedido de tombamento poderá ser feito por qualquer cidadão ou pelo Governo do Estado. Está correto o que consta em","opcoes":["II e III, apenas.","I e III, apenas.","II e IV, apenas.","I, II, III e IV.","I e IV, apenas."],"correta":3,"explicacao":"Gabarito: <strong>I, II, III e IV.</strong>.","banca":"FCC","ano":2018,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tombamento vizinhos art18","ancora":"tombamento-vizinhos-art18"},"B":{"topico":"tombamento vizinhos art18","ancora":"tombamento-vizinhos-art18"},"C":{"topico":"tombamento vizinhos art18","ancora":"tombamento-vizinhos-art18"},"D":{"topico":"tombamento vizinhos art18","ancora":"tombamento-vizinhos-art18"},"E":{"topico":"tombamento vizinhos art18","ancora":"tombamento-vizinhos-art18"}}},{"id":4260063,"enunciado":"Acerca da desapropriação é correto afirmar o seguinte:","opcoes":["considera-se caso de utilidade pública, para fins de desapropriação, nos termos do Decreto-lei nº 3.365/41 a assistência pública, as obras de higiene e decoração, casas de saúde, clínicas, estações de clima e fontes medicinais.","as propriedades rurais e urbanas de qualquer região do País onde forem localizadas culturas ilegais de plantas psicotrópicas ou a exploração de trabalho escravo na forma da lei serão expropriadas e destinadas à reforma agrária e a programas de habitação popular, mediante prévia e justa indenização em títulos da dívida agrária, com cláusula de preservação do valor real, resgatáveis no prazo de até vinte anos, a partir do segundo ano de sua emissão, e cuja utilização será definida em lei.","pela demora no pagamento do preço da desapropriação cabe indenização complementar além dos juros.","a concordância escrita do expropriado implica renúncia ao seu direito de questionar o preço ofertado em juízo."],"correta":0,"explicacao":"Gabarito: <strong>considera-se caso de utilidade pública, para fins de desapropriação, nos termos do Decreto-lei nº 3.365/41 a assistência pública, as obras de higiene e decoração, casas de saúde, clínicas, estações de clima e fontes medicinais.</strong>.","banca":"FADESP","ano":2018,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4260065,"enunciado":"A desapropriação é forma de Intervenção do Estado, e tem como nortes legais e jurisprudenciais o seguinte preceito:","opcoes":["o desapropriado receberá indenização correspondente à área real na desapropriação por interesse social se ficar constatado que a área medida do bem é maior do que a escriturada no Registro de Imóveis.","o cumprimento das exigências do Plano Diretor é requisito dispensável para a caracterização da função social da propriedade urbana.","a indenização deve ser prévia, justa e em dinheiro, sendo a avaliação o momento balizador do quantum a ser indenizado.","a desapropriação indireta é comportamento regular da administração que pressupõe o apossamento de bem particular sem as formalidades necessárias."],"correta":2,"explicacao":"Gabarito: <strong>a indenização deve ser prévia, justa e em dinheiro, sendo a avaliação o momento balizador do quantum a ser indenizado.</strong>.","banca":"IV - UFG","ano":2018,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4260069,"enunciado":"“O direito real de gozo, de natureza pública, instituído sobre imóvel de propriedade alheia, com base em lei, por entidade pública ou por seus delegados, em face de um serviço público ou de um bem afetado a fim de utilidade pública”, denomina-se (Maria Sylvia Zanella Di Pietro)","opcoes":["tombamento.","retrocessão.","requisição administrativa.","desapropriação.","servidão administrativa."],"correta":4,"explicacao":"Gabarito: <strong>servidão administrativa.</strong>.","banca":"VUNESP","ano":2018,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4260074,"enunciado":"Sobre o tombamento, assinale a alternativa correta.","opcoes":["O mesmo bem não pode sofrer mais de um tombamento, simultaneamente, pois um ato de tombamento interfere nos outros.","O tombamento apenas pode recair sobre bens imóveis, não sendo possível tombar bens móveis e incorpóreos.","O poder público não possui direito de preferência sobre bem tombado quando o particular desejar aliená-lo, ou seja, quando for hipótese de alienação extrajudicial.","Via de regra, entende-se que o dever de preservação do bem tombado configura efetivo prejuízo ao seu proprietário, cabendo indenização prévia.","O ato de tombamento é vinculado e poderá ser geral ou individual. Admite-se o tombamento voluntário, e o compulsório ainda aguarda regulamentação legal."],"correta":2,"explicacao":"Gabarito: <strong>O poder público não possui direito de preferência sobre bem tombado quando o particular desejar aliená-lo, ou seja, quando for hipótese de alienação extrajudicial.</strong>.","banca":"VUNESP","ano":2018,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tombamento alienacao","ancora":"tombamento-alienacao"},"B":{"topico":"tombamento alienacao","ancora":"tombamento-alienacao"},"C":{"topico":"tombamento alienacao","ancora":"tombamento-alienacao"},"D":{"topico":"tombamento alienacao","ancora":"tombamento-alienacao"},"E":{"topico":"tombamento alienacao","ancora":"tombamento-alienacao"}}},{"id":4260238,"enunciado":"Na situação em que o particular seja prejudicado por ação da Administração Pública que resulte na ocupação de imóvel de sua propriedade, como resultado da implantação de equipamento público, sem o adequado procedimento de desapropriação e pagamento de indenização, poderá o interessado:","opcoes":["ingressar com interdito proibitório, como forma de retomar a posse do seu imóvel, a qual foi perdida em favor da Administração Pública.","ingressar com ação direta de desapropriação, para que a Administração Pública apresente oferta de compra do imóvel, considerando-se a perda da posse.","apresentar reclamação ao Supremo Tribunal Federal, com base na alegação de descumprimento das regras constitucionais relativas ao respeito à propriedade privada e às espécies de desapropriação.","valer-se do seu poder de autotutela, deixando de pagar os tributos incidentes sobre o imóvel em questão, como forma de compensar as perdas decorrentes da ação da Administração Pública.","promover ação de desapropriação indireta, desde que se afigure impossibilidade fática de reversão da ocupação, tornando ineficaz tutela judicial específica."],"correta":4,"explicacao":"Gabarito: <strong>promover ação de desapropriação indireta, desde que se afigure impossibilidade fática de reversão da ocupação, tornando ineficaz tutela judicial específica.</strong>.","banca":"VUNESP","ano":2018,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4260251,"enunciado":"Considere que, visando realizar obras de saneamento básico, o Estado do Amapá edita decreto no qual declara a utilidade pública, para fins de desapropriação, de imóvel residencial urbano habitado pelo respectivo proprietário, em favor da Companhia de Água e Esgoto do Amapá (CAESA). A referida empresa estatal ajuíza a ação de desapropriação e, na petição inicial, alega urgência e requer a imissão provisória no imóvel expropriando. Nesse caso,","opcoes":["não deve ser concedida a imissão provisória, visto que a urgência deveria ser previamente declarada no decreto de utilidade pública.","se houver impugnação pelo expropriado, haverá arbitramento de indenização provisória pelo juiz, que somente autorizará a imissão, se o expropriante complementar o depósito para que este atinja a metade do valor arbitrado.","não é possível imissão provisória, pois o direito à moradia se sobrepõe à conveniência da Administração Pública.","deve haver a citação do expropriado antes da decisão sobre a imissão provisória na posse.","a empresa estatal nunca terá competência para ajuizar ação de desapropriação, que deve ser proposta diretamente pelo ente que emitiu o decreto de utilidade pública."],"correta":1,"explicacao":"Gabarito: <strong>se houver impugnação pelo expropriado, haverá arbitramento de indenização provisória pelo juiz, que somente autorizará a imissão, se o expropriante complementar o depósito para que este atinja a metade do valor arbitrado.</strong>.","banca":"FCC","ano":2018,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"competencia desapropriar","ancora":"competencia-desapropriar"},"B":{"topico":"competencia desapropriar","ancora":"competencia-desapropriar"},"C":{"topico":"competencia desapropriar","ancora":"competencia-desapropriar"},"D":{"topico":"competencia desapropriar","ancora":"competencia-desapropriar"},"E":{"topico":"competencia desapropriar","ancora":"competencia-desapropriar"}}},{"id":4260271,"enunciado":"Conforme entendimento jurisprudencial do STJ, a limitação administrativa sobre determinado bem constitui modalidade de intervenção restritiva na propriedade de caráter","opcoes":["exclusivo e pode dar ensejo a indenização de natureza jurídica de direito real em favor do proprietário, ainda que não seja demonstrada a efetiva redução do valor econômico do bem em função da referida limitação.","geral e condição inerente ao exercício do direito de propriedade, inexistindo hipóteses de indenização.","geral, mas que pode dar ensejo a indenização em favor do proprietário na hipótese de a limitação causar redução do valor econômico do bem, independentemente do momento em que tenha sido instituída a restrição.","exclusivo e pode dar ensejo a indenização de natureza jurídica de direito real em favor do proprietário, desde que a aquisição do bem tenha ocorrido anteriormente à instituição da restrição.","geral, mas que pode dar ensejo a indenização de natureza jurídica de direito pessoal, se a limitação causar redução do valor econômico do bem e a sua aquisição tiver ocorrido anteriormente à instituição da restrição."],"correta":4,"explicacao":"Gabarito: <strong>geral, mas que pode dar ensejo a indenização de natureza jurídica de direito pessoal, se a limitação causar redução do valor econômico do bem e a sua aquisição tiver ocorrido anteriormente à instituição da restrição.</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"limitacao administrativa","ancora":"limitacao-administrativa"},"B":{"topico":"limitacao administrativa","ancora":"limitacao-administrativa"},"C":{"topico":"limitacao administrativa","ancora":"limitacao-administrativa"},"D":{"topico":"limitacao administrativa","ancora":"limitacao-administrativa"},"E":{"topico":"limitacao administrativa","ancora":"limitacao-administrativa"}}},{"id":4260358,"enunciado":"Sobre a intervenção administrativa na propriedade, é correto:","opcoes":["O tombamento é imposto por ato administrativo unilateral, de cunho singular, incidente sobre bens imóveis particulares, que uma vez tombados não poderão ser alienados pelo respectivo proprietário, ressalvada a hipótese de reversão administrativa ou judicial do ato de tombamento.","No caso do parcelamento e edificação compulsórios, esses institutos podem ser usados pelo Poder Público municipal e estadual na hipótese de o proprietário do imóvel não utilizado ou subutilizado questionar a aplicação do IPTU com alíquota progressiva no tempo ou a desapropriação para fins de reforma urbana.","A desapropriação indireta ocorre nos casos em que o Poder Público apreende bens ilegalmente comercializados, e também nos casos de expropriações de terras utilizadas para o cultivo de substâncias ilegais, situações em que a respectiva indenização ocorrerá mediante títulos da dívida pública.","Compete à União desapropriar por interesse social, para fins de reforma agrária, o imóvel rural que não esteja cumprindo sua função social, mediante prévia e justa indenização em títulos da dívida agrária, com cláusula de preservação do valor real, resgatáveis no prazo de até vinte anos, a partir do segundo ano de sua emissão, e cuja utilização será definida em lei."],"correta":3,"explicacao":"Gabarito: <strong>Compete à União desapropriar por interesse social, para fins de reforma agrária, o imóvel rural que não esteja cumprindo sua função social, mediante prévia e justa indenização em títulos da dívida agrária, com cláusula de preservação do valor real, resgatáveis no prazo de até vinte anos, a partir do segundo ano de sua emissão, e cuja utilização será definida em lei.</strong>.","banca":"IESES","ano":2018,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4260367,"enunciado":"Assinale a alternativa INCORRETA:","opcoes":["O patrimônio cultural brasileiro é constituído pelos bens de natureza material e imaterial, tomados individualmente ou em conjunto, portadores de referência à identidade, à ação, à memória dos diferentes grupos formadores da sociedade brasileira.","São formas de promoção e de proteção do patrimônio cultural brasileiro o inventário, o registro, a vigilância, o tombamento e a desapropriação, sem prejuízo de outras formas de acautelamento e preservação.","O tombamento, a desapropriação, a ocupação temporária e a limitação administrativa são formas de intervenção do Estado na propriedade privada, que se perfazem mediante prévia e justa indenização ao proprietário.","A servidão administrativa é ônus real de uso, imposto pela Administração Pública à propriedade privada, para assegurar a realização de obra ou serviço de utilidade pública, mediante indenização dos prejuízos efetivamente suportados pelo proprietário."],"correta":2,"explicacao":"Gabarito: <strong>O tombamento, a desapropriação, a ocupação temporária e a limitação administrativa são formas de intervenção do Estado na propriedade privada, que se perfazem mediante prévia e justa indenização ao proprietário.</strong>.","banca":"FUNDEP (Gestão de Concursos)","ano":2018,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4260385,"enunciado":"O direito do proprietário de exigir que na desapropriação se inclua a parte restante do bem expropriado, que se tornou inútil ou de difícil utilização, é denominado de","opcoes":["Retrocessão.","Desapropriação indireta.","Direito de extensão.","Indenização de benfeitorias.","Direito de acrescer."],"correta":2,"explicacao":"Gabarito: <strong>Direito de extensão.</strong>.","banca":"VUNESP","ano":2018,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4260416,"enunciado":"Assinale a alternativa correta a respeito da intervenção do Estado na propriedade privada.","opcoes":["A servidão administrativa consiste em direito real público, por meio do qual o dono do prédio dominante se obriga a tolerar o uso de seu imóvel pelo dono do prédio serviente.","De acordo com a Constituição Federal, no caso de iminente perigo público, a autoridade competente poderá se valer da requisição administrativa a fim de usar de propriedade particular, sendo sempre assegurada ao proprietário retribuição financeira pelo uso do bem.","No âmbito do Sistema Único de Saúde, poderão as autoridades competentes dos entes federativos, para atendimento de necessidades coletivas, urgentes e transitórias, decorrentes de situações de perigo iminente, de calamidade pública ou de irrupção de epidemias, requisitar bens e serviços, tanto de pessoas naturais como de jurídicas, sendo-lhes assegurada justa indenização.","Tanto na requisição administrativa, quanto na servidão administrativas, mostra-se imprescindível a presença de perigo público iminente.","A limitação administrativa caracteriza-se como determinações de caráter individual, por meio das quais o Poder Público impõe a proprietário de bem imóvel obrigações positivas, negativas ou permissivas, para o fim de condicionar o direito de propriedade ao atendimento da função social."],"correta":2,"explicacao":"Gabarito: <strong>No âmbito do Sistema Único de Saúde, poderão as autoridades competentes dos entes federativos, para atendimento de necessidades coletivas, urgentes e transitórias, decorrentes de situações de perigo iminente, de calamidade pública ou de irrupção de epidemias, requisitar bens e serviços, tanto de pessoas naturais como de jurídicas, sendo-lhes assegurada justa indenização.</strong>.","banca":"FAUEL","ano":2018,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4260478,"enunciado":"A seguir são apresentadas ações realizadas pelo Estado. I Alocação provisória de determinadas máquinas e equipamentos utilizados em execução de obra pública em propriedade privada desocupada. II Instalação de redes elétricas em determinada propriedade privada para fins de execução de serviço público. III Determinação de ordem urbanística de proibição de construção além de determinada altura em região do município. As hipóteses apresentadas correspondem, respectivamente, às seguintes modalidades de intervenção do Estado na propriedade","opcoes":["ocupação temporária, servidão administrativa e limitação administrativa.","requisição administrativa, servidão administrativa e ocupação temporária.","requisição administrativa, ocupação temporária e limitação administrativa.","servidão administrativa, requisição administrativa e limitação administrativa.","ocupação temporária, limitação administrativa e servidão administrativa."],"correta":0,"explicacao":"Gabarito: <strong>ocupação temporária, servidão administrativa e limitação administrativa.</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"1":{"topico":"Ocupação temporária","ancora":"ocupacao-temporaria"},"2":{"topico":"Servidão administrativa","ancora":"servidao-administrativa"},"3":{"topico":"Limitação administrativa","ancora":"limitacao-administrativa"}}},{"id":4260489,"enunciado":"Analise as afirmativas a seguir, relativas à distinção, adotada na doutrina, entre tredestinação lícita e tredestinação ilícita. I. A ocorrência da tredestinação significa que não se deu ao bem expropriado a destinação para a qual se desapropriou. II. A hipótese de retrocessão relaciona-se apenas com a tredestinação ilícita. III. A tredestinação lícita é cabível em todas as hipóteses em que se desapropria validamente um bem e posteriormente se utiliza o bem expropriado para qualquer outra finalidade legalmente prevista. Está(ão) correta(s) a(s) afirmativa(s):","opcoes":["I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III.","III, apenas."],"correta":0,"explicacao":"Gabarito: <strong>I e II, apenas.</strong>.","banca":"FUNDEP (Gestão de Concursos)","ano":2018,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4260637,"enunciado":"Sobre a desapropriação, a Carta Magna brasileira dispõe que","opcoes":["será paga em títulos da dívida pública quando o imóvel for para uso do próprio poder público.","a utilidade pública é uma das finalidades que embasam o procedimento de desapropriação.","ela será implementada sobre bens imóveis, mas a Constituição veda que recaia sobre bens móveis ou direitos.","o pagamento ao proprietário do bem desapropriado será feito imediatamente após o trânsito em julgado da ação de desapropriação.","a Constituição Federal veda, expressamente, a desapropriação de bens públicos."],"correta":1,"explicacao":"Gabarito: <strong>a utilidade pública é uma das finalidades que embasam o procedimento de desapropriação.</strong>.","banca":"VUNESP","ano":2017,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"B":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"C":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"D":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"E":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"}}},{"id":4260644,"enunciado":"Em cada uma das opções a seguir é apresentada uma situação hipotética acerca das formas de intervenção do Estado na propriedade, seguida de uma assertiva a ser julgada. Assinale a opção correspondente à assertiva correta.","opcoes":["O comprador de um imóvel com restrição pretende ser indenizado por ter sofrido limitação administrativa preexistente constante em nota non aedificandi — proibição de construir — referente a parte do imóvel, em razão de normas ambientais. Nesse caso, é indevida a indenização pretendida, pois não há perda da propriedade, mas apenas restrições de uso.","Um imóvel de propriedade privada situado às margens de um rio navegável que atravessa todo o estado foi objeto de decreto expropriatório. Nessa situação, é devida ao proprietário a indenização de toda a propriedade, incluindo-se a área situada às margens do rio.","Uma propriedade particular foi objeto de decreto expropriatório para a construção de um parque público no local. No entanto, o desabamento de uma escola pública situada em área de risco levou o estado a construir emergencialmente uma escola na referida propriedade. Nessa situação, o particular cujo bem foi expropriado poderá utilizar-se da retrocessão para readquirir a sua propriedade, considerando-se a alteração da finalidade do decreto expropriatório.","Decreto do presidente da República instituiu estado de defesa em determinado estado da Federação, em razão de fortes chuvas que causaram destruição e fizeram muitos habitantes desabrigados em determinada região. Em virtude do decreto, foi possível a ocupação temporária de uma propriedade privada próxima ao local mais afetado. Nessa situação, considerando-se a relevância do interesse público e a urgência da situação, a União não responderá pelos custos decorrentes da ocupação temporária.","Um imóvel de propriedade da União situa-se no centro histórico de um município e conserva todas as características históricas e arquitetônicas da época colonial. Nesse caso, o município é impedido de efetuar o tombamento desse imóvel, pois, apesar de se tratar de hipótese de exercício de competência concorrente, incide o princípio da hierarquia federativa."],"correta":0,"explicacao":"Gabarito: <strong>O comprador de um imóvel com restrição pretende ser indenizado por ter sofrido limitação administrativa preexistente constante em nota non aedificandi — proibição de construir — referente a parte do imóvel, em razão de normas ambientais. Nesse caso, é indevida a indenização pretendida, pois não há perda da propriedade, mas apenas restrições de uso.</strong>.","banca":"CESPE / CEBRASPE","ano":2017,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Limitação e esvaziamento econômico","ancora":"limitacao-esvaziamento-economico"},"B":{"topico":"Regime jurídico dos bens públicos","ancora":"regime-bens-publicos"},"C":{"topico":"Tredestinação e retrocessão","ancora":"tredestinacao-retrocessao"},"D":{"topico":"Ocupação temporária","ancora":"ocupacao-temporaria"},"E":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"}}},{"id":4260664,"enunciado":"Para preservar área de proteção ambiental permanente, uma lei municipal determinou recuo obrigatório de construção em propriedades situadas em localidade de certo município. Nessa situação hipotética, ocorre restrição ao direito de propriedade denominada","opcoes":["servidão administrativa.","tombamento.","apossamento administrativo.","desapropriação por utilidade pública.","limitação administrativa."],"correta":4,"explicacao":"Gabarito: <strong>limitação administrativa.</strong>.","banca":"CESPE / CEBRASPE","ano":2017,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4260727,"enunciado":"A respeito da desapropriação, assinale a alternativa correta.","opcoes":["Somente bens imóveis ou bens móveis economicamente avaliáveis podem ser objeto de desapropriação.","Bem municipal pode ser desapropriado pela União, desde que haja prévia autorização legislativa.","Por se tratar de exercício de poder extroverso, concessionários do poder público não poderão promover desapropriações, mesmo que autorizados por contrato ou lei.","Ao Poder Judiciário é permitido, no processo de desapropriação, decidir se se verificam ou não os casos de utilidade pública.","A imissão provisória na posse, no processo de desapropriação, deve ser precedida do pagamento de integral indenização em dinheiro."],"correta":1,"explicacao":"Gabarito: <strong>Bem municipal pode ser desapropriado pela União, desde que haja prévia autorização legislativa.</strong>.","banca":"VUNESP","ano":2017,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"B":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"C":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"D":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"E":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"}}},{"id":4260733,"enunciado":"Com relação à intervenção do Estado na propriedade, assinale a opção correta.","opcoes":["Compete à União, aos estados e ao DF legislar, de forma concorrente, sobre desapropriação, estando a competência da União limitada ao estabelecimento de normas gerais.","Expropriação ou confisco consiste na supressão punitiva de propriedade privada pelo Estado, a qual dispensa pagamento de indenização e incide sobre propriedade urbana ou rural onde haja cultura ilegal de psicotrópico ou ocorra exploração de trabalho escravo.","Servidão administrativa é a modalidade de intervenção que impõe obrigações de caráter geral a proprietários indeterminados, em benefício do interesse geral abstratamente considerado, e afeta o caráter absoluto do direito de propriedade.","Requisição é a modalidade de intervenção do Estado supressiva de domínio, incidente sobre bens móveis e imóveis, públicos ou privados, e, em regra, sem posterior indenização."],"correta":1,"explicacao":"Gabarito: <strong>Expropriação ou confisco consiste na supressão punitiva de propriedade privada pelo Estado, a qual dispensa pagamento de indenização e incide sobre propriedade urbana ou rural onde haja cultura ilegal de psicotrópico ou ocorra exploração de trabalho escravo.</strong>.","banca":"CESPE / CEBRASPE","ano":2017,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4260747,"enunciado":"Concluído determinado processo de desapropriação, com o pagamento integral do valor e a incorporação do bem ao patrimônio do poder público, este decidiu devolver o bem expropriado ao antigo dono, por não lhe ter sido atribuída a destinação prevista no decreto expropriatório nem qualquer outra destinação pública. Essa reversão do procedimento expropriatório é denominada","opcoes":["tredestinação lícita.","desapropriação indireta.","desistência da desapropriação.","retrocessão."],"correta":3,"explicacao":"Gabarito: <strong>retrocessão.</strong>.","banca":"CESPE / CEBRASPE","ano":2017,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4260759,"enunciado":"A respeito de parcelamento do solo, impacto de vizinhança, regularização fundiária de interesse social, desapropriação e tombamento, julgue o item a seguir com base na legislação urbanística.\n\nSe imóvel integrante do patrimônio cultural for objeto de tombamento compulsório, poderá o proprietário requerer o cancelamento do tombamento se, após notificar o Instituto do Patrimônio Histórico e Artístico Nacional da impossibilidade financeira de proceder às obras de conservação e reparação necessárias, o poder público não adotar nenhuma providência dentro do prazo de seis meses.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2017,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"tombamento art19 conservacao","ancora":"tombamento-art19-conservacao"},"E":{"topico":"tombamento art19 conservacao","ancora":"tombamento-art19-conservacao"}}},{"id":4260760,"enunciado":"A respeito de parcelamento do solo, impacto de vizinhança, regularização fundiária de interesse social, desapropriação e tombamento, julgue o item a seguir com base na legislação urbanística.\n\nEm se tratando de desapropriação por utilidade pública em que a imissão prévia na posse tenha se dado por ordem judicial e o ente expropriante tenha depositado em juízo o preço ofertado, é incabível o pagamento de juros compensatórios.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2017,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"E":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"}}},{"id":4260767,"enunciado":"Acerca da intervenção do Estado na propriedade, das licitações e dos contratos administrativos, julgue o seguinte item.\n\nSegundo o entendimento do STJ, ao contrário do que ocorre em desapropriação para fins de reforma agrária, é irregular, nos casos de desapropriação por utilidade pública, a imissão provisória na posse pelo poder público.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2017,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"E":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"}}},{"id":4260768,"enunciado":"Acerca da intervenção do Estado na propriedade, das licitações e dos contratos administrativos, julgue o seguinte item.\n\nNo caso de parceria a ser firmada entre a administração pública e organização da sociedade civil, se não houver transferências voluntárias de recursos, deverá ser utilizado o instrumento jurídico estabelecido em lei denominado acordo de cooperação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2017,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"distincao instrumentos intervencao","ancora":"distincao-instrumentos-intervencao"},"E":{"topico":"distincao instrumentos intervencao","ancora":"distincao-instrumentos-intervencao"}}},{"id":4260780,"enunciado":"Diversas são as formas de intervenção do Estado na propriedade, o que revela o poder de império estatal ao qual se sujeitam os particulares. Desse modo, é CORRETO afirmar que o direito à preempção municipal é:","opcoes":["Ocupação temporária.","Servidão administrativa.","Limitação administrativa.","Requisição."],"correta":2,"explicacao":"Gabarito: <strong>Limitação administrativa.</strong>.","banca":"FUNDEP (Gestão de Concursos)","ano":2017,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4260785,"enunciado":"Analise as assertivas e, depois, assinale a opção correta: I- Ocorre o apossamento administrativo de propriedade privada sem regular desapropriação, mas a área foi afetada para destinação apta a ensejar a expropriação. No caso, é quinquenal o prazo prescricional para o proprietário postular indenização, em face da Administração Pública, pela perda da propriedade. II- No âmbito da desapropriação por interesse social, intentada a ação, o proprietário pode discutir, em seu bojo, o preço ofertado c a presença ou não dos pressupostos para a declaração de interesse social, mas não a conveniência e a oportunidade da declaração de interesse social. III- Não há que se subtrair do Judiciário a apreciação de lesão a direito, de modo que a conveniência e a oportunidade da declaração de interesse social podem ser debatidas no bojo da expropriatória.","opcoes":["Apenas a assertiva I é correta.","Apenas a assertiva II é correta.","Apenas a assertiva III é correta.","Todas as assertivas são falsas.","Apenas as assertivas I e II estão corretas."],"correta":3,"explicacao":"Gabarito: <strong>Todas as assertivas são falsas.</strong>.","banca":"TRF - 2ª Região","ano":2017,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4260789,"enunciado":"Sobre Desapropriação, marque a assertiva correta:","opcoes":["Decretada a utilidade pública do bem a ser expropriado, e desde que passado o prazo legal para o acordo administrativo, ficam as autoridades administrativas autorizadas a penetrar nos prédios compreendidos na declaração.","O decreto de utilidade pública marca o início do prazo de caducidade da ação de desapropriação indireta.","A declaração de utilidade pública marca o início do prazo prescricional da ação de desapropriação indireta.","O decreto de utilidade pública implica vedação de licenciamento de obra no bem objeto do ato expropriatório.","A expedição do Decreto de utilidade pública marca o início de prazo quinquenal findo o qual, não havendo acordo e não intentada a ação, o ato caducará."],"correta":4,"explicacao":"Gabarito: <strong>A expedição do Decreto de utilidade pública marca o início de prazo quinquenal findo o qual, não havendo acordo e não intentada a ação, o ato caducará.</strong>.","banca":"TRF - 2ª Região","ano":2017,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"art7 penetrar predios","ancora":"art7-penetrar-predios"},"B":{"topico":"art7 penetrar predios","ancora":"art7-penetrar-predios"},"C":{"topico":"art7 penetrar predios","ancora":"art7-penetrar-predios"},"D":{"topico":"art7 penetrar predios","ancora":"art7-penetrar-predios"},"E":{"topico":"art7 penetrar predios","ancora":"art7-penetrar-predios"}}},{"id":4260822,"enunciado":"Determinado Município necessitará, nestas eleições, utilizar-se da edificação de uma Instituição de ensino superior privada, ante a escassez de escolas públicas na localidade. Neste caso, é correto afirmar que:","opcoes":["deverá realizar a requisição do imóvel do particular, garantindo a prévia e justa indenização equivalente ao aluguel do bem utilizado.","deverá instituir servidão administrativa temporária, mediante acordo administrativo, assegurando a posterior indenização por danos e prejuízos que o uso possa causar ao imóvel.","deverá promover a ocupação temporária, sendo assegurada indenização ao proprietário do imóvel apenas nas hipóteses em que o uso acarrete prejuízo.","deverá instituir limitação administrativa temporária sobre o imóvel, sem direito de indenização ao particular."],"correta":2,"explicacao":"Gabarito: <strong>deverá promover a ocupação temporária, sendo assegurada indenização ao proprietário do imóvel apenas nas hipóteses em que o uso acarrete prejuízo.</strong>.","banca":"FAUEL","ano":2017,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4260845,"enunciado":"Um policial andava pela rua quando presenciou um assalto. Ao ver o assaltante fugir, o policial parou um carro, identificou-se ao motorista, entrou no carro e pediu que ele perseguisse o criminoso. Nessa situação, conforme a CF e a doutrina pertinente, tem-se um exemplo típico da modalidade de intervenção do Estado na propriedade privada denominada","opcoes":["limitação administrativa, cabendo indenização ao proprietário, se houver dano ao bem deste.","requisição administrativa, cabendo indenização ao proprietário, se houver dano ao bem deste.","desapropriação, não cabendo indenização ao proprietário, independentemente de dano ao bem deste.","servidão administrativa, não cabendo indenização ao proprietário, independentemente de dano ao bem deste.","ocupação temporária, não cabendo indenização ao proprietário, mesmo que haja dano ao bem deste."],"correta":1,"explicacao":"Gabarito: <strong>requisição administrativa, cabendo indenização ao proprietário, se houver dano ao bem deste.</strong>.","banca":"CESPE / CEBRASPE","ano":2017,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4260849,"enunciado":"A respeito da desapropriação, é correto afirmar que","opcoes":["é forma derivada de aquisição da propriedade.","a ação expropriatória não pode ser intentada se o proprietário do bem não puder ser identificado.","mesmo se anulado o processo expropriatório, o bem expropriado, uma vez incorporado à Fazenda Pública, não pode ser reivindicado.","se o poder expropriante requerer urgência, a imissão provisória na posse poderá ser efetivada sem o depósito do preço inicial.","o expropriado pode requerer o levantamento de noventa por cento do valor inicial depositado, desde que apresente prova de domínio do bem."],"correta":2,"explicacao":"Gabarito: <strong>mesmo se anulado o processo expropriatório, o bem expropriado, uma vez incorporado à Fazenda Pública, não pode ser reivindicado.</strong>.","banca":"VUNESP","ano":2017,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"B":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"C":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"D":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"E":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"}}},{"id":4261003,"enunciado":"Sobre a desapropriação, assinale a alternativa correta.","opcoes":["No processo judicial, a contestação só poderá versar sobre vício do processo judicial ou impugnação do preço.","Em caso de segurança nacional, o Estado poderá desapropriar bens da União, ouvindo-se o Advogado Geral da União.","A construção de edifícios públicos não é uma das causas de utilidade pública para fins de desapropriação.","Pode haver retrocessão no caso de imóvel desapropriado para implantação de parcelamento popular destinado às classes de menor renda."],"correta":0,"explicacao":"Gabarito: <strong>No processo judicial, a contestação só poderá versar sobre vício do processo judicial ou impugnação do preço.</strong>.","banca":"VUNESP","ano":2016,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4261011,"enunciado":"É notório que a Constituição Federal possui diversos artigos que tratam do tema da desapropriação. Nessa toada, assinale a alternativa que NÃO possui um fundamento ensejador da desapropriação, a teor do disposto no art. 5º, inc. XXIV.","opcoes":["Segurança jurídica.","Necessidade pública.","Utilidade pública.","Interesse social."],"correta":0,"explicacao":"Gabarito: <strong>Segurança jurídica.</strong>.","banca":"FAFIPA","ano":2016,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4261041,"enunciado":"Tocante às limitações legais e constitucionais ao direito de propriedade, segundo a jurisprudência do Superior Tribunal de Justiça, é incorreto afirmar que:","opcoes":["A indenização pela cobertura vegetal, de forma destacada da terra nua, está condicionada à efetiva comprovação da exploração econômica lícita dos recursos vegetais.","Não enseja indenização ao proprietário do solo a desapropriação de jazidas de substâncias minerais (areia, pedregulho e 'rachão'), de emprego imediato na construção civil, sem concessão, autorização ou licenciamento para serem exploradas pelo expropriado.","Na desapropriação para instituir servidão administrativa são devidos os juros compensatórios pela limitação de uso da propriedade.","O desvio de finalidade que leva à retrocessão é o simples descumprimento dos objetivos que justificaram a desapropriação, sendo indiferente, para que o expropriado tenha direito à devolução do imóvel, que o Poder Público dê ao bem destinação que não atenda ao interesse público."],"correta":3,"explicacao":"Gabarito: <strong>O desvio de finalidade que leva à retrocessão é o simples descumprimento dos objetivos que justificaram a desapropriação, sendo indiferente, para que o expropriado tenha direito à devolução do imóvel, que o Poder Público dê ao bem destinação que não atenda ao interesse público.</strong>.","banca":"MPE-GO","ano":2016,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4261065,"enunciado":"Com o escopo de promover melhoria no sistema de mobilidade urbana, o Estado do Rio de Janeiro resolveu ampliar determinada estrada que comportará significativo aumento no tráfego de veículos em razão dos jogos olímpicos. Durante as obras de reforma e ampliação da via expressa, foi necessária a utilização temporária de terrenos particulares contíguos à estrada, para a alocação transitória de máquinas de asfalto, equipamentos de serviço e pequenas barracas de operários. Para viabilizar tal utilização dos imóveis privados, o Governo do Estado, ao intervir na propriedade, se valeu do instituto da:","opcoes":["servidão administrativa, que acarreta a prévia indenização ao particular, cujo valor pode ser arbitrado pela via administrativa caso haja acordo, ou judicialmente;","ocupação temporária, que enseja indenização ao particular se o uso pelo poder público acarretar comprovado prejuízo ao proprietário;","requisição administrativa, que, independentemente de risco iminente, enseja ao particular indenização na proporção da diminuição do uso de sua propriedade;","desapropriação temporária, que acarreta a prévia indenização ao particular, cujo valor pode ser arbitrado pela via administrativa caso haja acordo, ou judicialmente;","limitação administrativa, que enseja necessária e ulterior indenização ao particular, cujo valor varia de acordo com a diminuição do uso de sua propriedade."],"correta":1,"explicacao":"Gabarito: <strong>ocupação temporária, que enseja indenização ao particular se o uso pelo poder público acarretar comprovado prejuízo ao proprietário;</strong>.","banca":"FGV","ano":2016,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4261075,"enunciado":"Determinado bem é objeto de ato de desapropriação por utilidade pública. Constitui um efeito da declaração de desapropriação o inicio do prazo de caducidade do decreto expropriatório que, nos termos do Decreto-Lei no. 3.365-41, o prazo de conclusão da desapropriação é de:","opcoes":["cinco anos","seis anos","sete anos","oito anos","nove anos"],"correta":0,"explicacao":"Gabarito: <strong>cinco anos</strong>.","banca":"FUNRIO","ano":2016,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"B":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"C":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"D":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"E":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"}}},{"id":4261129,"enunciado":"Assinale a opção correta, segundo a qual a modalidade de intervenção na propriedade privada sujeita o bem, cuja conservação seja de interesse público, por sua importância histórica, artística, arqueológica, bibliográfica ou etnológica, a restrições parciais, mediante procedimento administrativo.","opcoes":["tombamento","ocupação temporária","servidão administrativa","limitação administrativa","desapropriação"],"correta":0,"explicacao":"Gabarito: <strong>tombamento</strong>.","banca":"CESPE / CEBRASPE","ano":2016,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4261225,"enunciado":"Intervenção do Estado na propriedade pode ser conceituada como toda e qualquer atividade estatal que, amparada em lei, tenha por fim ajustá-la aos inúmeros fatores exigidos pela função social a que está condicionada, com base na supremacia do interesse público sobre o privado. Como modalidade de intervenção do Estado na propriedade, destaca-se:","opcoes":["a requisição administrativa, que ocorre na hipótese de o Poder Público procurar proteger o patrimônio cultural brasileiro, determinando restrições quanto ao uso de determinado imóvel pelo seu proprietário;","o tombamento, que ocorre na hipótese de utilização do espaço físico de uma escola particular para abrigar desalojados em razão de fortes chuvas que causaram o decreto de estado de calamidade pelo iminente risco público;","a ocupação temporária, que ocorre na hipótese de o poder público proceder diretamente à limpeza de determinado terreno que esteja sendo foco de proliferação de vetores, caso seu proprietário não atenda à obrigação positiva de limpeza que lhe foi imposta;","a limitação administrativa, que ocorre na hipótese de utilização temporária de terrenos particulares contíguos a estradas (em construção ou em reforma), para a alocação transitória de máquinas de asfalto e equipamentos de serviço;","a servidão administrativa, que ocorre na hipótese de direito real público de implantação de gasodutos e oleodutos pelo poder público em áreas privadas para a execução de determinados serviços públicos."],"correta":3,"explicacao":"Gabarito: <strong>a limitação administrativa, que ocorre na hipótese de utilização temporária de terrenos particulares contíguos a estradas (em construção ou em reforma), para a alocação transitória de máquinas de asfalto e equipamentos de serviço;</strong>.","banca":"FGV","ano":2015,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4261235,"enunciado":"Sobre a desapropriação indireta, assinale a alternativa correta.","opcoes":["A jurisprudência dos tribunais superiores consolidou o critério segundo o qual não incidem juros para compensar o que o desapropriado deixou de ganhar com a perda antecipada do imóvel, tampouco para ressarci-lo pelo impedimento do uso e gozo econômico do imóvel.","A ação de desapropriação indireta é de natureza indenizatória, de cunho patrimonial, que a vincula ao denominado interesse público primário, cuja titularidade é atribuída à Fazenda Pública.","Em regra, a ação de indenização por desapropriação indireta não pressupõe automática intervenção do Ministério Público.","É de quinze anos o prazo prescricional aplicável nas ações de desapropriação indireta.","Trata-se de um ato administrativo pelo qual o Estado se apropria de bem particular, sem a observância dos requisitos constitucionais da declaração e da indenização prévia."],"correta":2,"explicacao":"Gabarito: <strong>Em regra, a ação de indenização por desapropriação indireta não pressupõe automática intervenção do Ministério Público.</strong>.","banca":"FMP Concursos","ano":2015,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4261314,"enunciado":"No que se refere à intervenção do Estado na propriedade, assinale a alternativa que contém afirmativa correta.","opcoes":["Em todas as hipóteses de desapropriação de bens pelo Estado, o pagamento ao desapropriado será efetuado exclusivamente em dinheiro.","Somente os bens privados de particulares poderão ser objeto de desapropriação.","Na desapropriação para fins de reforma agrária por interesse social, as benfeitorias úteis e necessárias do imóvel desapropriado serão indenizadas em títulos da dívida agrária.","No caso de iminente perigo público, a autoridade competente poderá usar de propriedade particular, assegurada ao proprietário indenização ulterior, se houver dano."],"correta":3,"explicacao":"Gabarito: <strong>No caso de iminente perigo público, a autoridade competente poderá usar de propriedade particular, assegurada ao proprietário indenização ulterior, se houver dano.</strong>.","banca":"FAURGS","ano":2015,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"B":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"C":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"D":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"}}},{"id":4261323,"enunciado":"Julgue o próximo item, referente à utilização dos bens públicos e à desapropriação.\nDe acordo com o STJ, ao contrário do que ocorre nos casos de desapropriação para fins de reforma agrária, é vedada a imissão provisória na posse de terreno pelo poder público em casos de desapropriação para utilidade pública.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"E":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"}}},{"id":4261339,"enunciado":"Relativamente à intervenção do Estado na propriedade privada,","opcoes":["as limitações administrativas se consubstanciam em atos administrativos de caráter individual, mediante os quais o Poder Público impõe posturas positivas, negativas ou, ainda, permissivas, com a finalidade de adequar o dado imóvel à sua função social.","por não ensejar a perda da propriedade e em vista da supremacia do interesse público sobre o particular, a servidão administrativa não comporta a possibilidade de indenização ao proprietário do imóvel, mesmo no caso de esse suportar prejuízos.","o instituto da ocupação temporária recairá sobre bem imóvel com a finalidade de permitir ao poder público executar serviços, existindo ou não perigo público iminente a ser confrontado. A exemplo da servidão administrativa, a ocupação temporária é direito real e, assim, deverá ser levada a registro no cartório de registro de imóveis para gerar efeitos.","o ato de tombamento implica restrições ao uso do bem móvel e imóvel por seu proprietário ou possuidor, que deverá conservá-lo segundo as características culturais que motivaram sua proteção. No caso de tombamento de bens imóveis, o proprietário que não possuir recursos financeiros suficientes para realizar obras de preservação ou de conservação deverá informar tal fato à autoridade competente, que deverá proceder à mencionada obra, vedada a desapropriação.","ao contestar ação de desapropriação, o Defensor Público somente poderá versar sobre vícios do processo judicial ou impugnar o preço apresentado pelo expropriante, vedada a reconvenção."],"correta":4,"explicacao":"Gabarito: <strong>ao contestar ação de desapropriação, o Defensor Público somente poderá versar sobre vícios do processo judicial ou impugnar o preço apresentado pelo expropriante, vedada a reconvenção.</strong>.","banca":"FCC","ano":2015,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4261385,"enunciado":"Sobre Desapropriação, julgue as afirmativas abaixo. I. Não obstante a declaração de utilidade pública ou de interesse social seja atividade administrativa afeta ao Poder Executivo, o art. 8 do Decreto-lei n. 3.365/41 autoriza o Poder Legislativo a tomar a iniciativa da desapropriação cumprindo, neste caso, ao Executivo, praticar os atos necessários à sua efetivação. II. É lícito ao proprietário construir no bem declarado de utilidade pública ou de interesse social. Portanto o valor das eventuais construções que venham a ser realizadas será incluído no valor da indenização quando a desapropriação for efetivada. III. Somente é lícito discutir no âmbito da ação de desapropriação o valor a ser pago a título de indenização e eventuais incidentes da própria ação de desapropriação. Outros aspectos relativos à desapropriação que podem resultar na anulação do processo, como o desvio de finalidade, devem ser levados à apreciação judicial por meio de ação rescisória, consoante previsto no Decreto-lei n. 3. 365/41. IV. É legítimo ao poder público expropriante solicitar, em casos de urgência, a imissão provisória na posse do bem, o que poderá ser feita após despacho nesse sentido pelo juízo do feito, independentemente da citação do réu, mediante o depósito da quantia arbitrada de conformidade legal. A alternativa que contém todas as afirmativas corretas é:","opcoes":["I e II","I e III","I, II e IV","I e IV","II e III"],"correta":3,"explicacao":"Gabarito: <strong>I e IV</strong>.","banca":"UEPA","ano":2015,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"B":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"C":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"D":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"E":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"}}},{"id":4261411,"enunciado":"Uma autarquia estadual que atua na área previdenciária é proprietária de vasto patrimônio imobiliário, especialmente porque fazia parte da política de gestões anteriores o financiamento de imóveis residenciais e comerciais para servidores públicos, especialmente em regiões com necessidade de revitalização. Assim, referida autarquia era proprietária de um casarão na região central de determinado município, construído no início do século XX. O Município, ouvindo rumores de que a autarquia pretendia alienar seu patrimônio que não estivesse formalmente destinado às finalidades institucionais do ente, providenciou regular procedimento e, por meio de seu órgão competente, editou Resolução tombando o imóvel. O imóvel, apurou-se posteriormente, já era tombado pelo órgão estadual competente. Diante desse cenário,","opcoes":["a autarquia pode impugnar o tombamento, tendo em vista que o Município não poderia decretar o tombamento de bens pertencentes a pessoas jurídicas de direito público, tendo em vista que o tombamento constituiu uma limitação à propriedade privada.","o Município somente poderia tombar o bem da autarquia caso não houvesse tombamento anterior, tendo em vista que sobre o mesmo imóvel não podem se sobrepor duas intervenções à propriedade.","não obstante a autarquia tenha personalidade jurídica híbrida e seus bens estejam sujeitos ao regime jurídico de direito privado, o tombamento estadual prefere ao tombamento municipal, que fica por aquele ato absorvido.","a alienação onerosa do bem tombado ficou inviabilizada, tendo em vista que limitação à propriedade dessa natureza impõe gravame ao proprietário e exige que a propriedade do bem remanesça sendo de pessoa jurídica de direito público.","o tombamento municipal, cuja imposição seguiu trâmite regular, permanece válido, tendo em vista que sobre o mesmo bem, ainda que pertencente a pessoa jurídica de direito público, pode existir mais de uma limitação daquela natureza, desde que compatíveis, cabendo ao proprietário observar as posturas e restrições impostas pelos dois entes federados."],"correta":4,"explicacao":"Gabarito: <strong>o tombamento municipal, cuja imposição seguiu trâmite regular, permanece válido, tendo em vista que sobre o mesmo bem, ainda que pertencente a pessoa jurídica de direito público, pode existir mais de uma limitação daquela natureza, desde que compatíveis, cabendo ao proprietário observar as posturas e restrições impostas pelos dois entes federados.</strong>.","banca":"FCC","ano":2015,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tombamento alienacao","ancora":"tombamento-alienacao"},"B":{"topico":"tombamento alienacao","ancora":"tombamento-alienacao"},"C":{"topico":"tombamento alienacao","ancora":"tombamento-alienacao"},"D":{"topico":"tombamento alienacao","ancora":"tombamento-alienacao"},"E":{"topico":"tombamento alienacao","ancora":"tombamento-alienacao"}}},{"id":4261419,"enunciado":"Assinale a opção correta relativamente às formas de intervenção do Estado na propriedade privada.","opcoes":["Em regra, a desapropriação de imóveis urbanos deve ser realizada mediante prévia e justa indenização, a ser adimplida com títulos da dívida pública de emissão previamente aprovada pelo Senado Federal.","As limitações administrativas são medidas fundamentadas no poder de polícia do Estado, incidem sobre bens individualizados discriminados em ato administrativo e geram obrigações para o proprietário de cada um desses bens.","A extinção da servidão administrativa pode ocorrer em razão da perda da coisa gravada ou da desafetação da coisa dominante.","O tombamento somente poderá ter como objeto bens imóveis e pode incidir sobre imóveis públicos ou privados.","A ocupação temporária é a utilização transitória pelo Estado de bens imóveis de propriedade particular para fins de interesse público, uso que não suscita direito a indenização ante a efemeridade da limitação do uso do bem."],"correta":2,"explicacao":"Gabarito: <strong>A extinção da servidão administrativa pode ocorrer em razão da perda da coisa gravada ou da desafetação da coisa dominante.</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Conceito e natureza jurídica da desapropriação","ancora":"conceito-desapropriacao"},"B":{"topico":"Limitação administrativa","ancora":"limitacao-administrativa"},"C":{"topico":"Extinção da servidão administrativa","ancora":"extincao-servidao"},"D":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"E":{"topico":"Ocupação temporária","ancora":"ocupacao-temporaria"}}},{"id":4261444,"enunciado":"A União publicou decreto expropriatório por utilidade pública de imóvel urbano. No decreto, declarou-se o interesse de instalar, no referido imóvel, a sede de determinado órgão público federal. A administração pública imitiu-se na posse do bem e realizou as reformas necessárias. Em seguida, as atividades do órgão público foram inauguradas no imóvel. O prazo do decreto expropriatório caducou sem que a administração propusesse acordo para o pagamento da indenização nem ajuizasse, para esse fim, a ação judicial. Acerca dessa situação hipotética, assinale a opção correta à luz das normas e precedentes jurisprudenciais a respeito da desapropriação.","opcoes":["A ação de indenização tem natureza pessoal e deve ser proposta pelo proprietário no foro de domicílio da pessoa jurídica expropriante.","Conforme o entendimento atual do STJ, o prazo para a interposição da ação indenizatória, pelo proprietário, é de vinte anos, contados da imissão na posse.","O proprietário poderá obter a restituição do bem mediante a propositura de ação reivindicatória contra a União.","Ocorreu desapropriação indireta, que, comparada à desapropriação comum, caracteriza-se pela inversão entre as fases de pagamento da indenização e apossamento do bem desapropriado.","Não houve ilegalidade na imissão na posse ocorrida, visto que o ato administrativo é dotado de autoexecutoriedade e decorreu dos poderes transferidos à administração pelo decreto expropriatório."],"correta":3,"explicacao":"Gabarito: <strong>Ocorreu desapropriação indireta, que, comparada à desapropriação comum, caracteriza-se pela inversão entre as fases de pagamento da indenização e apossamento do bem desapropriado.</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4261445,"enunciado":"Com a finalidade de garantir a preservação ambiental em áreas rurais, determinada autoridade competente editou decreto que estabeleceu a proibição de corte, exploração ou supressão de vegetação em áreas caracterizadas como componentes da mata atlântica. Nessa situação hipotética, o ato descrito","opcoes":["ensejará indenização apenas se provocar prejuízo ao proprietário e desde que a aquisição da propriedade se tenha dado antes da intervenção do Estado.","ensejará ação de indenização que, no caso, será classificada como real e terá prazo prescricional de vinte anos, contados a partir da data em que se iniciar a intervenção do Estado na propriedade.","constituiu uma limitação administrativa, a qual se caracteriza pela restrição ao caráter exclusivo da propriedade e por ser promovida por meio de ato geral de efeitos abstratos que atinge um número indeterminado de bens que se encontrem na situação descrita.","constituiu uma servidão administrativa; por essa razão, o direito a indenização ocorre excepcionalmente e restringe-se aos casos de grave redução do valor econômico do bem.","constituiu uma desapropriação indireta; diante disso, o Estado deve indenizar o proprietário pelo valor da terra nua e das benfeitorias nela existentes."],"correta":0,"explicacao":"Gabarito: <strong>ensejará indenização apenas se provocar prejuízo ao proprietário e desde que a aquisição da propriedade se tenha dado antes da intervenção do Estado.</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4261456,"enunciado":"Julgue o item abaixo, com relação à intervenção do Estado na propriedade.\n\nSalvo as impossibilidades jurídicas e materiais, mediante declaração de utilidade pública, formalizada por meio de decreto do chefe do Poder Executivo, todos os bens podem ser desapropriados pelos entes que compõem a Federação. Poderá também o Poder Legislativo tomar a iniciativa da desapropriação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"iniciativa legislativa desapropriacao","ancora":"iniciativa-legislativa-desapropriacao"},"E":{"topico":"iniciativa legislativa desapropriacao","ancora":"iniciativa-legislativa-desapropriacao"}}},{"id":4261498,"enunciado":"Acerca de limitações administrativas, direito de construir, desapropriação e tombamento, julgue o item a seguir.\n\nAs limitações administrativas, modalidade de intervenção do Estado na propriedade privada, caracterizam-se por serem imposições gerais e abstratas que visam a um número indeterminado de propriedades, tendo por fundamentos a função social da propriedade e a supremacia do interesse público sobre o particular.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"E":{"topico":"tombamento conceito","ancora":"tombamento-conceito"}}},{"id":4261638,"enunciado":"Assinale a opção correta:","opcoes":["A retrocessão é direito subjetivo do particular expropriado, de caráter real, e nasce para o interessado toda a vez que, um ano após a imissão na posse, o expropriante não deu ao bem a exata destinação indicada no ato declaratório.","Uma vez declarada a utilidade pública do bem a ser expropriado, presente o pressuposto indicado no ato declaratório, o proprietário perde a possibilidade de aliená- lo, mas não está inibido de sobre ele fazer melhorias, não computáveis no cálculo da indenização.","A tredestinação sana o vício causal eventualmente constante no ato expropriatório","Declarada a utilidade pública do bem a ser expropriado, e intentada a respectiva ação expropriatória, o proprietário réu não tem o direito de pretender discutir, no bojo de tal ação, a ausência de pressuposto efetivo a caracterizar a utilidade pública.","O sistema legal brasileiro não permite que a ação de desapropriação possa ser proposta por pessoa jurídica de direito privado."],"correta":3,"explicacao":"Gabarito: <strong>Declarada a utilidade pública do bem a ser expropriado, e intentada a respectiva ação expropriatória, o proprietário réu não tem o direito de pretender discutir, no bojo de tal ação, a ausência de pressuposto efetivo a caracterizar a utilidade pública.</strong>.","banca":"TRF - 2ª Região","ano":2014,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4261658,"enunciado":"A empresa responsável pelo abastecimento de água e saneamento local precisa implantar um emissário subterrâneo de esgoto em um terreno particular próximo à estação de tratamento existente, onde se cultiva cana-de-açúcar. Para tanto","opcoes":["poderá instituir ocupação temporária ou requisição administrativa, que perdurarão pelo tempo necessário para a utilização do emissário, dispensando-se indenização ao proprietário.","deverá adquirir a porção do terreno necessária à instalação da infraestrutura subterrânea.","poderá desapropriar a porção de terreno necessária à instalação da infraestrutura, dispensada indenização, tendo em vista que não haverá restrição à exploração econômica.","deverá decretar o tombamento da área, com a consequente preservação e impossibilidade de utilização da porção do terreno para outra finalidade além do emissário de esgoto.","poderá instituir servidão administrativa, indenizando o proprietário do terreno pelos prejuízos experimentados pela restrição operada."],"correta":4,"explicacao":"Gabarito: <strong>poderá instituir servidão administrativa, indenizando o proprietário do terreno pelos prejuízos experimentados pela restrição operada.</strong>.","banca":"FCC","ano":2014,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4261687,"enunciado":"Assinale a alternativa que corretamente discorre acerca da desapropriação indireta.","opcoes":["Para realizar a desapropriação indireta basta afetar o bem particular ao fim público.","É uma espécie de desapropriação de fato, permitida expressamente pela legislação.","Em nenhuma hipótese o tombamento ambiental acarretará desapropriação indireta.","O proprietário poderá sempre solicitar em juízo que o Poder Público restitua a coisa.","É um esbulho possessório praticado pelo Estado, que invade área privada sem contraditório ou indenização."],"correta":4,"explicacao":"Gabarito: <strong>É um esbulho possessório praticado pelo Estado, que invade área privada sem contraditório ou indenização.</strong>.","banca":"VUNESP","ano":2014,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4261691,"enunciado":"João detém uma autorização de exploração de um restaurante que funciona dentro de uma área pública de determinada prefeitura, onde, há cerca de trinta anos, abre para o almoço e lanche dos servidores que ali trabalham. Contudo, o novo prefeito deseja construir uma praça de convivência no local onde se situa o restaurante de João, de modo que expediu ato administrativo revogando a autorização de uso do bem público, conferindo prazo de sessenta dias para que se desocupasse a área em questão. João procurou a Defensoria Pública para obter orientação jurídica com relação à situação, já que depende do restaurante para sustentar sua família. Considerando essa situação hipotética e de acordo com ordenamento jurídico, a doutrina e jurisprudências pátrias, será orientado ao interessado que:","opcoes":["tratando-se de autorização de mais de trinta anos, configura-se ato administrativo estável, de modo que prefeitura deveria ter ajuizado ação de despejo a fim de reaver o imóvel, devendo João aguardar a notificação judicial de retirada","caracterizando-se o ato do prefeito como unilateral e discricionário, a única medida possível é verificar a regularidade do ato revogador, a fim de aferir possíveis vícios na sua constituição.","caberá impetração de mandado de segurança para questionar o ato, sob fundamento de que o ato do prefeito consiste, em verdade, em desapropriação indireta.","caberá ajuizamento de medida cautelar para garantir a continuidade do funcionamento do restaurante, com fundamento na ilegalidade do ato do prefeito e na ausência de motivação idônea.","caberá ajuizamento de demanda sob o rito ordinário para questionar os motivos da revogação da autorização com pleito para impedir, até o fim da lide, a realização de novas obras que afetem o funcionamento do restaurante."],"correta":1,"explicacao":"Gabarito: <strong>caracterizando-se o ato do prefeito como unilateral e discricionário, a única medida possível é verificar a regularidade do ato revogador, a fim de aferir possíveis vícios na sua constituição.</strong>.","banca":"IV - UFG","ano":2014,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4261699,"enunciado":"O poder público estadual resolveu realizar obras necessárias para reforma e manutenção de uma rodovia. Para tal, fez-se necessária a utilização transitória de alguns imóveis privados contíguos à via pública, como meio à execução das obras, especialmente para serem alocadas as máquinas, equipamentos e barracões de operários. Todos os proprietários dos terrenos a serem utilizados concordaram com a providência, exceto o Senhor Antônio, que alegou que a Constituição da República lhe assegura o direito de propriedade. Ao buscar orientação jurídica, Antônio foi informado de que a propriedade deve atender à sua função social e, por força da prevalência do interesse público sobre o privado, a utilização de seu imóvel pelo Estado é obrigatória, inclusive com indenização ao final, no caso de comprovado prejuízo. A modalidade de intervenção do Estado na propriedade no caso em tela é chamada de:","opcoes":["poder de polícia.","servidão administrativa.","requisição temporária.","ocupação temporária.","desapropriação temporária."],"correta":3,"explicacao":"Gabarito: <strong>ocupação temporária.</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4261700,"enunciado":"O desvio de finalidade na desapropriação, ou seja, o uso do bem desapropriado para fim diverso daquele mencionado no ato expropriatório denomina-se:","opcoes":["retrocessão.","desdestinação.","adestinação.","desapropriação indireta.","tredestinação."],"correta":4,"explicacao":"Gabarito: <strong>tredestinação.</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4261753,"enunciado":"Assinale a alternativa correta a respeito do instituto da desapropriação.","opcoes":["O decreto expropriatório permite ao poder expropriante penetrar no imóvel atingido pelo decreto para fazer avaliações e verificações por meio da imissão provisória na posse.","O poder expropriante terá o prazo de cinco anos, contados da publicação da declaração expropriatória para efetivar a desapropriação por interesse social.","A desapropriação de imóveis urbanos não utilizados ou mal utilizados pode ser efetivada pelos Estados ou pelos Municípios.","A desapropriação por interesse social do imóvel rural que não cumpra sua função social importa prévia e justa indenização em títulos da dívida agrária, e as benfeitorias úteis e necessárias serão indenizadas em dinheiro."],"correta":3,"explicacao":"Gabarito: <strong>A desapropriação por interesse social do imóvel rural que não cumpra sua função social importa prévia e justa indenização em títulos da dívida agrária, e as benfeitorias úteis e necessárias serão indenizadas em dinheiro.</strong>.","banca":"VUNESP","ano":2014,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"B":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"C":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"D":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"}}},{"id":4261761,"enunciado":"O Governador do Estado expede Decreto-expropriatório que tem por objeto determinado imóvel de particular com o objetivo de servir como instalação de unidade administrativa de uma sociedade de economia mista que presta serviço público. Essa sociedade ingressa com a ação de desapropriação. Após a avaliação prévia do imóvel por perito judicial, depositado o valor indicado, a autora (sociedade de economia mista prestadora de serviço público) é imitida na posse do imóvel e inicia as suas funções. Após o devido processo legal, o processo é sentenciado com a fixação de um valor de indenização. Em grau de recurso, a decisão é mantida e, em execução de sentença, a sociedade de economia mista espontaneamente paga o saldo residual existente em favor do expropriado. Por último, registra-se a propriedade na matrícula do imóvel. Sobre esta situação narrada, assinale a alternativa correta.","opcoes":["A propriedade em favor da expropriante é condição à qualificação jurídica do imóvel como bem público de uso especial.","O imóvel torna-se bem público de uso especial a partir da imissão na posse e a propriedade é transferida à sociedade de economia mista com o pagamento integral do valor de indenização.","A propriedade do imóvel deve ser registrada em favor do Governo do Estado, pois apenas a posse pode ser reconhecida em benefício da sociedade de economia mista e, mesmo assim, enquanto afetado o bem ao serviço público por ela prestado.","O imóvel qualifica-se como bem público de uso geral com a imissão na posse; a partir do trânsito em julgado do processo torna-se bem público de uso especial, e com o registro na matrícula do imóvel é que se transfere a propriedade."],"correta":1,"explicacao":"Gabarito: <strong>O imóvel torna-se bem público de uso especial a partir da imissão na posse e a propriedade é transferida à sociedade de economia mista com o pagamento integral do valor de indenização.</strong>.","banca":"VUNESP","ano":2014,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4261832,"enunciado":"Assinale a opção correta com relação aos bens públicos.","opcoes":["Em face do interesse público envolvido, a servidão administrativa não gera, para o proprietário do bem alcançado pela servidão, o direito a indenização. Todavia, na ocupação temporária do bem, a administração pública tem o dever legal de indenizar o proprietário.","O cessionário do direito de uso sobre bem imóvel da União exerce animus domini sobre a coisa, por se tratar de uma relação de direito real.","A exploração dos serviços de concessão de lotes e jazigos em cemitério público compete à União e, supletivamente, aos municípios.","Os terrenos de marinha são bens públicos de uso especial de propriedade da União, e o Código Civil adotou a presunção relativa no que se refere ao registro de sua propriedade imobiliária","Os bens tombados não podem ser destruídos, demolidos ou mutilados, e, para tanto, a administração pública pode se utilizar tanto do tombamento provisório quanto do tombamento definitivo, limitando o exercício do direito sobre o bem."],"correta":4,"explicacao":"Gabarito: <strong>Os bens tombados não podem ser destruídos, demolidos ou mutilados, e, para tanto, a administração pública pode se utilizar tanto do tombamento provisório quanto do tombamento definitivo, limitando o exercício do direito sobre o bem.</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"B":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"C":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"D":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"E":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"}}},{"id":4261834,"enunciado":"Assinale a opção correta acerca da intervenção no domínio econômico por meio da desapropriação.","opcoes":["No cálculo da verba advocatícia nas ações de desapropriação, devem ser excluídas as parcelas relativas aos juros compensatórios e moratórios.","As concessionárias de serviços públicos, quando do exercício das funções delegadas pelo poder público, poderão promover desapropriações mediante autorização expressa, constante de lei ou contrato.","O poder público pode desistir do processo expropriatório, inclusive no curso da ação judicial, sem a obrigação de pagar indenização ao expropriado.","O expropriado pode pleitear indenização, pelo instituto da retrocessão, em razão de o imóvel não ter sido utilizado para os fins declarados no decreto expropriatório, sendo-lhe vedado, contudo, reivindicar a propriedade expropriada, por se tratar de bem já incorporado ao patrimônio público.","Compete privativa e exclusivamente à União legislar sobre desapropriação, competindo, no entanto, a todos os entes federativos declarar a utilidade pública ou o interesse social de bem imóvel para fins de reforma agrária"],"correta":1,"explicacao":"Gabarito: <strong>As concessionárias de serviços públicos, quando do exercício das funções delegadas pelo poder público, poderão promover desapropriações mediante autorização expressa, constante de lei ou contrato.</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4261880,"enunciado":"O prefeito de determinado município realizou a desapropriação de um imóvel para fins de implantação de um parque ecológico, tendo a prefeitura instalado posteriormente, na área expropriada, um conjunto habitacional popular. Nesse caso hipotético,","opcoes":["como a área expropriada não foi utilizada para a implantação do parque ecológico, cabe indenização dos expropriados por perdas e danos sofridos, desde que devidamente comprovados.","não houve desvio de finalidade, dado o atendimento do interesse público, estando configurada a tredestinação lícita.","embora tenha ocorrido desvio de finalidade, o bem expropriado foi incorporado ao patrimônio público, o que torna inviável a retrocessão, cabendo, entretanto, indenização por perdas e danos.","houve desvio de finalidade, dado o descumprimento dos objetivos que justificaram a desapropriação, cabendo a retrocessão.","houve desvio de finalidade, devendo ser decretada a nulidade do ato expropriatório com a reintegração dos expropriados na posse do imóvel e indenização em lucros cessantes."],"correta":1,"explicacao":"Gabarito: <strong>não houve desvio de finalidade, dado o atendimento do interesse público, estando configurada a tredestinação lícita.</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4262081,"enunciado":"Acerca da intervenção do Estado na propriedade privada, está CORRETA a seguinte proposição:","opcoes":["A autoridade pública poderá requisitar bem particular para prevenir possível dano a prédio tombado pelo patrimônio histórico.","A desapropriação para fins de reforma agrária depende de prévia e justa indenização em dinheiro.","É lícita a desapropriação de bem imóvel particular por utilidade pública para fins de construção de casas populares.","A expropriação de terras em que sejam cultivadas substâncias ilícitas enseja indenização em títulos da dívida pública, resgatáveis em até 20 anos","O expropriado tem direito de discutir, na ação de desapropriação, a efetiva ocorrência da hipótese de utilidade pública."],"correta":2,"explicacao":"Gabarito: <strong>É lícita a desapropriação de bem imóvel particular por utilidade pública para fins de construção de casas populares.</strong>.","banca":"PGE-GO","ano":2013,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4262106,"enunciado":"O Prefeito de determinado Município fez publicar um decreto de desapropriação de imóvel, com a finalidade de usar o bem para a construção de escola. Entretanto, na verdade, o ato foi editado com o fim de prejudicar seu desafeto político. Considerando tais fatos:","opcoes":["O decreto não pode ser anulado, pois encontra fundamento no Decreto-lei n° 3.365, de 21 de junho de 1941, que dispõe sobre a desapropriação por utilidade pública.","Não apresenta vício ou desvio de finalidade, pois a intenção manifestada no ato é de interesse público, não importando a questão pessoal entre a autoridade e o proprietário do imóvel desapropriado.","Apresenta vício pela ilegalidade do ato, pois não foi observada a sua forma.","Constitui desvio de finalidade ou de poder.","Poderá ser anulado pelo Poder Judiciário, mas não pela própria Administração Pública."],"correta":3,"explicacao":"Gabarito: <strong>Constitui desvio de finalidade ou de poder.</strong>.","banca":"IBFC","ano":2013,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4262113,"enunciado":"Assinale a alternativa que entender CORRETA quanto à modalidade de Intervenção do Estado na propriedade privada:","opcoes":["A servidão administrativa constitui ônus real sobre bem imóvel, em prol de uma utilidade pública e caracteriza-se como espécie de restrição parcial da propriedade.","O tombamento transfere a propriedade em razão da utilidade pública ou interesse social, podendo recair sobre bens imóveis ou móveis que tenham valor patrimonial, razão pela qual é passível de indenização.","A desapropriação pode recair sobre bens móveis, imóveis ou serviços, quando caracterizada a existência de perigo público iminente, de natureza transitória, e a indenização será ulterior.","A requisição administrativa tem por finalidade proteger o patrimônio cultural, não gera direito à indenização e representa restrição parcial do bem."],"correta":0,"explicacao":"Gabarito: <strong>A servidão administrativa constitui ônus real sobre bem imóvel, em prol de uma utilidade pública e caracteriza-se como espécie de restrição parcial da propriedade.</strong>.","banca":"MPE-MG","ano":2013,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Servidão administrativa","ancora":"servidao-administrativa"},"B":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"C":{"topico":"Conceito e natureza jurídica da desapropriação","ancora":"conceito-desapropriacao"},"D":{"topico":"Requisição administrativa","ancora":"requisicao-administrativa"}}},{"id":4262169,"enunciado":"No que se refere à servidão administrativa, assinale a opção correta.","opcoes":["A exemplo da requisição, a servidão, direito pessoal da administração, é caracterizada pela transitoriedade.","Embora normalmente incida sobre a propriedade imóvel, a servidão administrativa pode ser instituída também sobre bens móveis, desde que, em ambos os casos, sejam bens privados, e não públicos.","Caracteriza-se como servidão administrativa a proibição, imposta pelo poder público ao particular, de construir além de certo número de pavimentos, ou de promover desmatamento além de determinado percentual em área de sua propriedade.","A servidão administrativa, seja ela decorrente diretamente de lei, de contrato ou de decisão judicial, gera para o Estado, como regra, o dever de indenizar o proprietário do imóvel atingido.","Por encerrar apenas o uso da propriedade alheia para possibilitar a execução de serviços públicos, a servidão não enseja, ao contrário da desapropriação, a perda da propriedade."],"correta":4,"explicacao":"Gabarito: <strong>Por encerrar apenas o uso da propriedade alheia para possibilitar a execução de serviços públicos, a servidão não enseja, ao contrário da desapropriação, a perda da propriedade.</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4262170,"enunciado":"Assinale a opção correta no que diz respeito às limitações administrativas, à requisição e ao tombamento como formas de intervenção do Estado na propriedade.","opcoes":["O tombamento, forma de intervenção do poder público na propriedade, pode incidir tanto sobre bens móveis quanto sobre bens imóveis.","Ainda que haja inconformismo e resistência do proprietário, o poder público poderá promover o tombamento de determinado bem, razão pela qual se diz que o tombamento é, quanto à constituição, um ato compulsório, visto que sua realização independe do consentimento do particular.","As limitações administrativas são determinações por meio das quais o Estado impõe ao proprietário obrigações de caráter positivo, que implicam o dever de fazer algo em prol do interesse público.","A passagem subterrânea, por determinado terreno particular, de dutos para o transporte de gás configura exemplo de limitação administrativa.","A requisição é modalidade de intervenção por meio da qual o Estado, em face de perigo iminente, utiliza serviços, mas não bens, de particulares."],"correta":0,"explicacao":"Gabarito: <strong>O tombamento, forma de intervenção do poder público na propriedade, pode incidir tanto sobre bens móveis quanto sobre bens imóveis.</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"B":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"C":{"topico":"Limitação administrativa","ancora":"limitacao-administrativa"},"D":{"topico":"Servidão administrativa","ancora":"servidao-administrativa"},"E":{"topico":"Requisição administrativa","ancora":"requisicao-administrativa"}}},{"id":4262173,"enunciado":"Acerca da desapropriação, assinale a opção correta.","opcoes":["Bens públicos não podem ser desapropriados, razão pela qual a União, os estados e os municípios não podem desapropriar bens pertencentes a qualquer ente federativo.","O procedimento da desapropriação compreende a fase declaratória e a executória, esta última obrigatoriamente a ser desenvolvida na instância judicial.","Considera-se desapropriação indireta aquela pela qual o Estado se apropria de bem particular sem observância dos requisitos que compõem o procedimento expropriatório, como o ato declaratório e a indenização prévia.","A desapropriação por interesse social para fins de reforma agrária de imóvel rural que não esteja cumprindo sua função social compete à União, com pagamento mediante títulos da dívida pública de emissão aprovada pelo Senado Federal, com prazo de resgate de até dez anos, em parcelas anuais e sucessivas, assegurados o valor real da indenização e os juros legais.","As glebas em que forem localizadas culturas ilegais de plantas psicotrópicas devem ser imediatamente expropriadas e especificamente destinadas ao assentamento de colonos, para fins de reforma agrária, garantido o pagamento das benfeitorias úteis e necessárias."],"correta":2,"explicacao":"Gabarito: <strong>Considera-se desapropriação indireta aquela pela qual o Estado se apropria de bem particular sem observância dos requisitos que compõem o procedimento expropriatório, como o ato declaratório e a indenização prévia.</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"},"B":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"},"C":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"},"D":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"},"E":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"}}},{"id":4262258,"enunciado":"Assinale a alternativa incorreta:","opcoes":["De acordo com o Decreto-lei n° 3365/41, os concessionários de serviços públicos poderão promover desapropriações desde que haja autorização expressa, constante de lei ou contrato.","A desapropriação para fins de criação ou ampliação de distritos industriais só pode ser levada a efeito em havendo aprovação, prévia e expressa, pelo Poder Público competente, do respectivo projeto de implantação.","A denominada “tredestinação” pode ser caracterizada como sendo lícita ou ilícita, sendo que em ambos os casos deve ser reconhecido ao expropriado o direito à retrocessão.","Os bens do domínio dos Estados, Municípios, Distrito Federal e Territórios poderão ser desapropriados pela União, e os dos Municípios pelos Estados, mas o ato deverá ser precedido de autorização legislativa.","O apossamento, pelo Poder Público, de um bem imóvel particular, com ânimo definitivo, sem observar os pressupostos legais exigidos para a sua efetivação, configura desapropriação indireta."],"correta":2,"explicacao":"Gabarito: <strong>A denominada “tredestinação” pode ser caracterizada como sendo lícita ou ilícita, sendo que em ambos os casos deve ser reconhecido ao expropriado o direito à retrocessão.</strong>.","banca":"TRF - 3ª REGIÃO","ano":2013,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4262273,"enunciado":"Acerca da intervenção do Estado na propriedade e no domínio econômico, julgue os próximos itens.\n\nA desapropriação é forma originária de aquisição de propriedade que libera o bem de qualquer ônus que sobre ele incida, ou seja, se o bem estiver gravado com algum encargo, será repassado para o poder público sem nenhum ônus, não havendo, inclusive, a incidência de imposto sobre esse tipo de operação de transferência de imóveis. Entretanto, segundo o STJ, incidirá imposto de renda sobre verba recebida pelo proprietário a título de indenização decorrente de desapropriação","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4262274,"enunciado":"Acerca da intervenção do Estado na propriedade e no domínio econômico, julgue os próximos itens.\n\nA requisição administrativa é ato unilateral e autoexecutório por meio do qual o Estado, em caso de iminente perigo público, utiliza bem móvel ou imóvel. Esse instituto administrativo, a exemplo da desapropriação, não incide sobre serviços.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"E":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"}}},{"id":4262315,"enunciado":"Assinale a alternativa que corretamente trata da desapropria­ção como forma de intervenção do Estado na propriedade.","opcoes":["A expedição do decreto expropriatório possui como efeito, dentre outros, a fixação do estado da coisa para fins de indenização, devendo as benfeitorias voluptuá­ rias realizadas após a expedição do decreto serem indenizadas.","A desapropriação por interesse social para política u rbana tem função sancionatória, pois recai sobre imó­ veis que desatendem sua função social, mas a indeniza­ ção, ainda em títulos da dívida pública, terá valor real, refletindo o valor da base de cálculo do IPTU e compu­ tando lucros cessantes e juros compensatórios","A desapropriação por zona poderá ser realizada em qualquer região do País onde forem encontra­ das culturas ilegais de plantas psicotrópicas, sendo imediatament e destinadas ao assentamento de colo­ nos para cultivo de produtos alimentícios e medica­ mentosos.","São isentas de impostos federais, estaduais e municipais as operações de transferência de imóveis desapropria­ dos para fins de reforma agrária e de interesse social para política urbana.","Na hipótese de desapropriação por interesse social, o prazo de caducidade é de 2 (dois) anos, contados da e xpedição do decreto. Nas desapropriações por necessi­ dade ou interesse público, o prazo é de 5 (cinco) anos."],"correta":4,"explicacao":"Gabarito: <strong>Na hipótese de desapropriação por interesse social, o prazo de caducidade é de 2 (dois) anos, contados da e xpedição do decreto. Nas desapropriações por necessi­ dade ou interesse público, o prazo é de 5 (cinco) anos.</strong>.","banca":"VUNESP","ano":2013,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"B":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"C":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"D":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"E":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"}}},{"id":4262420,"enunciado":"Acerca da intervenção do Estado na propriedade, assinale a opção correta.","opcoes":["A ocupação temporária, pela administração, de imóvel particular para fins de interesse público será sempre gratuita.","A limitação administrativa é imposição de ordem geral que gera o dever de indenizar.","Os bens públicos são insuscetíveis de tombamento.","Conforme disposição da CF, o poder público deve proteger o patrimônio cultural brasileiro por meio de desapropriação, tombamento e registro, entre outras formas de acautelamento e preservação.","Servidão administrativa é o ato administrativo unilateral, autoexecutório e oneroso que consiste na utilização pela administração, para atender a necessidade coletiva em tempos de guerra ou em caso de perigo público iminente, de bens ou serviços particulares."],"correta":3,"explicacao":"Gabarito: <strong>Conforme disposição da CF, o poder público deve proteger o patrimônio cultural brasileiro por meio de desapropriação, tombamento e registro, entre outras formas de acautelamento e preservação.</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"B":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"C":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"D":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"E":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"}}},{"id":4262461,"enunciado":"Tendo em vista que a desapropriação e o tombamento podem ser considerados formas de intervenção do Estado no domínio privado, assinale a opção correta.","opcoes":["O tombamento pode ocorrer por iniciativa da administração pública ou do proprietário do bem, sendo devida indenização prévia em ambos os casos, a qual representa condição para que o tombamento se aperfeiçoe.","Segundo a jurisprudência do STJ, os municípios podem realizar o tombamento de bens pertencentes à União.","Somente os bens privados podem ser objeto de tombamento.","Segundo entendimento firmado pelo STJ, caso desapareçam os motivos que tenham provocado a iniciativa do processo expropriatório, o expropriante terá o poder jurídico de desistir da desapropriação, inclusive no curso da ação judicial. Nessa situação, será considerada irrelevante a situação na qual o imóvel se apresente quando da manifestação de desistência.","No procedimento desapropriatório, sempre que o administrador pratica a tredestinação do bem, tal fato enseja a nulidade do ato declaratório e, por conseguinte, dá ensejo a retrocessão."],"correta":1,"explicacao":"Gabarito: <strong>Segundo a jurisprudência do STJ, os municípios podem realizar o tombamento de bens pertencentes à União.</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4262466,"enunciado":"No que diz respeito à desapropriação e suas espécies como forma de intervenção no domínio econômico, assinale a opção correta.","opcoes":["O valor do bem expropriado, no caso de desapropriação para fins de utilidade pública, deve ser entendido como sendo o valor da terra nua cumulativamente ao valor dos acessórios, os quais são entendidos como sendo as benfeitorias necessárias, úteis e voluptuárias, que devem ser pagos em parcela única.","A jurisprudência do STJ no tocante à indenização de mata nativa ou de cobertura vegetal tem exigido, para reconhecimento do direito à indenização, a efetiva comprovação, por parte do expropriado, de que, antes do início do processo expropriatório, a exploração econômica se mostrava compatível com a lei.","Conforme o entendimento do STF, os juros moratórios relacionados a uma ação de desapropriação ajuizada em 2011 devem ser fixados em 12% ao ano.","Os juros compensatórios e moratórios, na desapropriação, não são cumuláveis, sendo devidos apenas os juros compensatórios, os quais são pagos na desapropriação direta, a partir da efetiva ocupação do imóvel.","A hipótese do art. 243 da CF é considerada uma das hipóteses de desapropriação. Além disso, esse instituto atinge toda a extensão do imóvel, e , não apenas a área onde houve o plantio de drogas."],"correta":1,"explicacao":"Gabarito: <strong>A jurisprudência do STJ no tocante à indenização de mata nativa ou de cobertura vegetal tem exigido, para reconhecimento do direito à indenização, a efetiva comprovação, por parte do expropriado, de que, antes do início do processo expropriatório, a exploração econômica se mostrava compatível com a lei.</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"B":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"C":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"D":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"E":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"}}},{"id":4262478,"enunciado":"Ainda acerca da intervenção do Estado na propriedade, assinale a opção correta.","opcoes":["Mediante requisição, pode o Estado obrigar o particular a prestar-lhe um serviço.","A requisição, por constituir procedimento adotado em situação de perigo público iminente, não é indenizável.","A servidão administrativa enseja a perda da propriedade do bem imóvel pelo particular.","Tratando-se de servidão administrativa, a indenização paga ao proprietário deve corresponder ao valor total do bem."],"correta":0,"explicacao":"Gabarito: <strong>Mediante requisição, pode o Estado obrigar o particular a prestar-lhe um serviço.</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4262479,"enunciado":"Acerca da intervenção do Estado na propriedade, assinale a opção correta.","opcoes":["A caducidade da declaração de utilidade pública refere-se à perda da validade dessa declaração pelo decurso de tempo sem que o poder público promova atos concretos destinados a efetivá-la.","Desapropriação é o direito que a administração tem de utilizar propriedade imóvel alheia para possibilitar a execução de obra ou serviço de interesse coletivo.","Os municípios são competentes para legislar sobre desapropriação.","Pode-se desapropriar dinheiro (moeda corrente do país)."],"correta":0,"explicacao":"Gabarito: <strong>A caducidade da declaração de utilidade pública refere-se à perda da validade dessa declaração pelo decurso de tempo sem que o poder público promova atos concretos destinados a efetivá-la.</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4262554,"enunciado":"No que concerne às desapropriações, não se pode afirmar:","opcoes":["a desapropriação ocorrerá por necessidade ou utilidade pública, ou por interesse social, mediante justa e prévia indenização em dinheiro, ressalvados os casos previstos na Constituição.","nos termos da Constituição Federal, depois de adotadas outras medidas, os Municípios e os Estados poderão determinar a desapropriação, com pagamento mediante títulos da dívida pública, caso o proprietário do solo urbano não edificado, subutilizado ou não utilizado, não promova seu adequado aproveitamento.","compete à União desapropriar por interesse social, para fins de reforma agrária, o imóvel rural que não esteja cumprindo sua função social, mediante prévia e justa indenização em títulos da dívida agrária, com cláusula de preservação do valor real, resgatáveis no prazo de até vinte anos, a partir do segundo ano de sua emissão, e cuja utilização será definida em lei.","são insuscetíveis de desapropriação para fins de reforma agrária: a pequena e média propriedade rural, assim definida em lei, desde que seu proprietário não possua outra; e a propriedade produtiva.","as indenizações das desapropriações por interesse social, para fins de reforma agrária, ocorrerão com o pagamento em títulos da dívida agrária; no entanto, as benfeitorias úteis e necessárias serão indenizadas em dinheiro."],"correta":0,"explicacao":"Gabarito: <strong>a desapropriação ocorrerá por necessidade ou utilidade pública, ou por interesse social, mediante justa e prévia indenização em dinheiro, ressalvados os casos previstos na Constituição.</strong>.","banca":"COPEVE-UFAL","ano":2012,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"imunidade reforma agraria","ancora":"imunidade-reforma-agraria"},"B":{"topico":"imunidade reforma agraria","ancora":"imunidade-reforma-agraria"},"C":{"topico":"imunidade reforma agraria","ancora":"imunidade-reforma-agraria"},"D":{"topico":"imunidade reforma agraria","ancora":"imunidade-reforma-agraria"},"E":{"topico":"imunidade reforma agraria","ancora":"imunidade-reforma-agraria"}}},{"id":4262569,"enunciado":"São pressupostos da desapropriação: I. Utilidade Pública. II. Necessidade Pública. III. Interesse social. IV. Retrocessão. Estão corretos os itens","opcoes":["II, III e IV, apenas.","I, II, III e IV.","I, II e IV, apenas.","I, II e III, apenas.","I, III e IV, apenas."],"correta":1,"explicacao":"Gabarito: <strong>I, II, III e IV.</strong>.","banca":"COPEVE-UFAL","ano":2012,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4262591,"enunciado":"Sobre desapropriação, é correto afirmar que o(a)","opcoes":["competência para legislar sobre desapropriação é concorrente.","Município pode, por interesse social, desapropriar imóvel rural para fins de reforma agrária.","Estado de São Paulo não pode desapropriar imóvel, situado em região metropolitana, para fins de política urbana.","competência do Chefe do Poder Executivo, na fase declaratória da desapropriação, não é exclusiva."],"correta":3,"explicacao":"Gabarito: <strong>competência do Chefe do Poder Executivo, na fase declaratória da desapropriação, não é exclusiva.</strong>.","banca":"VUNESP","ano":2012,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"},"B":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"},"C":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"},"D":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"}}},{"id":4262604,"enunciado":"Dadas as assertivas abaixo, assinale a alternativa correta. I. A desqualificação da entidade como organização social pelo Poder Executivo será precedida de processo administrativo, assegurado o direito de ampla defesa, respondendo os seus dirigentes, individual e solidariamente, pelos danos ou prejuízos decorrentes de sua ação ou omissão. II. Às organizações sociais poderão ser destinados recursos orçamentários e bens públicos necessários ao cumprimento do contrato de gestão, dispensada licitação. III. O tombamento de bens públicos realizado pelo órgão federal competente processa-se mediante simples notificação à entidade a quem pertencer ou sob cuja guarda estiver a coisa tombada, produzindo, a partir de então, os respectivos efeitos. IV. A diferença entre limitação administrativa e servidão administrativa é que aquela implica a constituição de direito real de uso e gozo em favor do poder público ou da coletividade, ao passo que esta constitui restrição em proveito de determinado bem afetado a fim de utilidade pública.","opcoes":["Está correta apenas a assertiva IV.","Estão corretas apenas as assertivas I e III.","Estão corretas apenas as assertivas II e IV.","Estão corretas apenas as assertivas I, II e III.","Estão corretas todas as assertivas."],"correta":3,"explicacao":"Gabarito: <strong>Estão corretas apenas as assertivas I, II e III.</strong>.","banca":"TRF - 4ª REGIÃO","ano":2012,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"1":{"topico":"Regime jurídico dos bens públicos","ancora":"regime-bens-publicos"},"2":{"topico":"Regime jurídico dos bens públicos","ancora":"regime-bens-publicos"},"3":{"topico":"Tombamento — conceito e características","ancora":"tombamento-conceito"},"4":{"topico":"Servidão administrativa","ancora":"servidao-administrativa"}}},{"id":4262611,"enunciado":"Sobre intervenção do Estado na propriedade, é correto afirmar:","opcoes":["De acordo com a interpretação literal do Decreto-lei nº 3.365/41, consideram-se hipóteses de necessidade pública, para fins de desapropriação: segurança nacional, defesa do Estado, socorro público em caso de calamidade e salubridade pública;","Na desapropriação por interesse social, para fins de reforma agrária, a indenização prévia e justa, em títulos da dívida agrária, abrange as benfeitorias úteis;","O Distrito Federal pode legislar sobre desapropriação por necessidade pública;","Tombamento e desapropriação, dentre outras, são ferramentas por meio das quais o Poder Público, com a colaboração da comunidade, promoverá e protegerá o patrimônio cultural brasileiro."],"correta":3,"explicacao":"Gabarito: <strong>Tombamento e desapropriação, dentre outras, são ferramentas por meio das quais o Poder Público, com a colaboração da comunidade, promoverá e protegerá o patrimônio cultural brasileiro.</strong>.","banca":"TJ-DFT","ano":2012,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"hipoteses utilidade publica","ancora":"hipoteses-utilidade-publica"},"B":{"topico":"hipoteses utilidade publica","ancora":"hipoteses-utilidade-publica"},"C":{"topico":"hipoteses utilidade publica","ancora":"hipoteses-utilidade-publica"},"D":{"topico":"hipoteses utilidade publica","ancora":"hipoteses-utilidade-publica"}}},{"id":4262617,"enunciado":"Assinale a alternativa que apresenta o instituto com característica de limitação administrativa.","opcoes":["Desapropriação por utilidade pública","Desapropriação por interesse social","Requisição","Ocupação temporária","Área de preservação permanente"],"correta":4,"explicacao":"Gabarito: <strong>Área de preservação permanente</strong>.","banca":"MPE-MT","ano":2012,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"limitacao administrativa","ancora":"limitacao-administrativa"},"B":{"topico":"limitacao administrativa","ancora":"limitacao-administrativa"},"C":{"topico":"limitacao administrativa","ancora":"limitacao-administrativa"},"D":{"topico":"limitacao administrativa","ancora":"limitacao-administrativa"},"E":{"topico":"limitacao administrativa","ancora":"limitacao-administrativa"}}},{"id":4262666,"enunciado":"Assinale a afirmativa INCORRETA:","opcoes":["Na Servidão Administrativa a indenização vincula-se à existência de efetivos prejuízos.","O Tombamento é ato administrativo de intervenção do Estado na propriedade, com o objetivo de preservar o patrimônio histórico, cultural, artístico, científico, paisagístico ou turístico.","A Requisição Administrativa é ato administrativo discricionário quanto ao objeto requisitado, podendo-se afirmar que é vinculado quanto à competência da autoridade requisitante.","A Requisição Administrativa diferencia-se da Servidão Administrativa, apenas porque a primeira incide sobre bens móveis, enquanto a segunda incide sobre bens imóveis."],"correta":3,"explicacao":"Gabarito: <strong>A Requisição Administrativa diferencia-se da Servidão Administrativa, apenas porque a primeira incide sobre bens móveis, enquanto a segunda incide sobre bens imóveis.</strong>.","banca":"IESES","ano":2012,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4262670,"enunciado":"Assinale a alternativa INCORRETA:","opcoes":["A desapropriação desenvolve-se por meio de uma sucessão de atos definidos em lei, que espelham duas fases distintas, a declaratória e a executória, abrangendo, a última, uma etapa administrativa e outra judicial.","A desapropriação é forma derivada de aquisição da propriedade.","A desapropriação indireta é a que se verifica sem o cumprimento das exigências legais, sendo equiparada, de costume, ao esbulho possessório.","A retrocessão é o direito que tem o expropriado de buscar o retorno de seu bem, caso o mesmo não tenha merecido o destino indicado à desapropriação."],"correta":1,"explicacao":"Gabarito: <strong>A desapropriação é forma derivada de aquisição da propriedade.</strong>.","banca":"IESES","ano":2012,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4262699,"enunciado":"A respeito da desapropriação, assinale a opção correta.","opcoes":["A desapropriação indireta consiste no fato administrativo por meio do qual o Estado se apropria de bem particular sem observância dos requisitos legais necessários para a desapropriação.","Mediante a desapropriação, forma de intervenção restritiva do Estado na propriedade privada, o poder público retira algumas das faculdades relativas ao domínio, mas mantém a propriedade em favor do dono.","A natureza jurídica da desapropriação é a de procedimento administrativo, somente.","Na desapropriação, a declaração de utilidade pública do bem particular, realizada pelo poder público, não tem prazo para se efetivar.","Denomina-se direito de extensão a faculdade de o expropriado permanecer na propriedade durante certo período após a conclusão do procedimento de desapropriação."],"correta":0,"explicacao":"Gabarito: <strong>A desapropriação indireta consiste no fato administrativo por meio do qual o Estado se apropria de bem particular sem observância dos requisitos legais necessários para a desapropriação.</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"direito extensao","ancora":"direito-extensao"},"E":{"topico":"direito extensao","ancora":"direito-extensao"}}},{"id":4262757,"enunciado":"No que se refere à intervenção do estado na propriedade, julgue o  item  a seguir.\nRequisição é o direito real público que possibilita ao poder público usar da propriedade imóvel para permitir a execução de obras e serviços de interesse coletivo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"E":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"}}},{"id":4262758,"enunciado":"No que se refere à intervenção do estado na propriedade, julgue o  item  a seguir.\nNa ocupação temporária, a indenização é condicionada à ocorrência de prejuízo ao proprietário.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"ocupacao temporaria","ancora":"ocupacao-temporaria"},"E":{"topico":"ocupacao temporaria","ancora":"ocupacao-temporaria"}}},{"id":4262770,"enunciado":"Assinale a opção correta com relação aos serviços públicos e à desapropriação.","opcoes":["Consideram-se serviços públicos indelegáveis os serviços que o Estado, atendendo a necessidades coletivas, assume como seus e executa diretamente, por seus próprios agentes e órgãos da administração centralizada, vedada a transferência de sua execução a particulares ou mesmo a entidades da administração indireta.","Como forma de impedir o comprometimento da operacionalização e da continuidade da prestação do serviço, as concessionárias estão proibidas, no financiamento de seus contratos, de oferecer em garantia os direitos emergentes da concessão.","A declaração expropriatória, mediante a qual o poder público declara a utilidade pública ou o interesse social do bem de um particular para fins de desapropriação, pode ser feita por decreto do chefe do Poder Executivo e por iniciativa do Poder Legislativo, tanto na esfera da União como na dos estados, do DF, dos municípios e dos territórios.","Em decorrência do princípio da igualdade dos usuários, não se admite, no serviço público, o estabelecimento de tarifas diferenciadas em função de custos específicos provenientes do atendimento a distintos segmentos de usuários.","As concessionárias de serviços públicos são obrigadas a oferecer ao consumidor e ao usuário, dentro do mês de vencimento dos débitos, várias opções de data para o vencimento de seus débitos, devendo as datas indicadas, quer no âmbito de cada estado, quer no do DF, ser as mesmas para os diferentes tipos de serviço público oferecidos."],"correta":2,"explicacao":"Gabarito: <strong>A declaração expropriatória, mediante a qual o poder público declara a utilidade pública ou o interesse social do bem de um particular para fins de desapropriação, pode ser feita por decreto do chefe do Poder Executivo e por iniciativa do Poder Legislativo, tanto na esfera da União como na dos estados, do DF, dos municípios e dos territórios.</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4262797,"enunciado":"Considerando a disciplina que rege a desapropriação, assinale a opção correta.","opcoes":["A União poderá desapropriar bens para atendimento de necessidades coletivas, urgentes e transitórias, decorrentes de situações de perigo iminente, de calamidade pública ou de irrupção de epidemias.","Conforme entendimento sumulado pelo STJ, o prazo prescricional da ação de desapropriação indireta é de cinco anos.","Caso recaia hipoteca sobre o imóvel a ser desapropriado, o poder público ficará impedido de dar início ao processo expropriatório.","O Poder Legislativo pode tomar a iniciativa da desapropriação, cabendo, nesse caso, ao Executivo praticar os atos necessários à sua efetivação.","Um município é competente para, presentes os requisitos legais, desapropriar bens de empresa pública federal."],"correta":3,"explicacao":"Gabarito: <strong>O Poder Legislativo pode tomar a iniciativa da desapropriação, cabendo, nesse caso, ao Executivo praticar os atos necessários à sua efetivação.</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"iniciativa legislativa desapropriacao","ancora":"iniciativa-legislativa-desapropriacao"},"B":{"topico":"iniciativa legislativa desapropriacao","ancora":"iniciativa-legislativa-desapropriacao"},"C":{"topico":"iniciativa legislativa desapropriacao","ancora":"iniciativa-legislativa-desapropriacao"},"D":{"topico":"iniciativa legislativa desapropriacao","ancora":"iniciativa-legislativa-desapropriacao"},"E":{"topico":"iniciativa legislativa desapropriacao","ancora":"iniciativa-legislativa-desapropriacao"}}},{"id":4262801,"enunciado":"Analise as proposições a seguir: I – A lei civil vigente define os bens de uso comum como aqueles destinados a serviço ou estabelecimento da administração, ao passo que sob a égide do código civil de 1916 os mesmos bens eram caracterizados por estarem aplicados a serviço ou estabelecimento. A distinção entre ambos está no fato de que atualmente a afetação deixou de decorrer do fato de o bem estar efetivamente empregado ao uso especial, passando a se relacionar à condição genérica de ter sido o mesmo simplesmente reservado a esse uso. II – Os bens tombados pertencentes à União, Estados ou Municípios são inalienáveis por natureza. Dessa característica decorre a impossibilidade de sua transferência entre os diversos Entes Federados. Se houver interesse de uma Entidade Federada em bem tombado de propriedade de outra, e havendo concordância dessa última, devem os interessados requerer ao órgão competente do Serviço de Patrimônio Histórico e Artístico Nacional autorização específica para o uso do bem, o que será feito sempre de forma precária. III – Há súmula do STJ fixando o prazo prescricional de 20 anos para a propositura de ação de indenização por desapropriação indireta, que tem natureza de ação real. Entretanto, o Decreto-lei nº 3.365/41, que dispõe sobe desapropriação por utilidade pública, foi alterado por Medida Provisória que estabeleceu o prazo máximo de cinco anos para propositura de ação que vise a indenização por apossamento administrativo ou desapropriação indireta, ou por restrições decorrentes de ato do poder público. O STF, no julgamento de ADI, suspendeu cautelarmente a aplicação dessa norma apenas em relação às ações de indenização por apossamento administrativo ou desapropriação indireta, por entender que o mesmo perpetra ofensa à garantia constitucional da justa e prévia indenização. IV – É dever do Poder Público Estadual proteger as manifestações culturais e populares, indígenas e afro-brasileiras e de outros grupos participantes do processo civilizatório. Nesse contexto, a Lei Maior Paraense declarou tombados os sítios dos antigos quilombos paraense, dos sambaquis, das áreas delimitadas pela arquitetura de habitação indígena e áreas inerentes a relevante narrativas de nossa história cultural.","opcoes":["apenas uma proposição está incorreta","apenas duas proposições estão incorretas","apenas três proposições estão incorretas","todas as proposições estão incorretas","todas as proposições estão corretas"],"correta":1,"explicacao":"Gabarito: <strong>apenas duas proposições estão incorretas</strong>.","banca":"UEPA","ano":2012,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"B":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"C":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"D":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"E":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"}}},{"id":4262814,"enunciado":"Julgue os itens seguintes, que versam sobre desapropriação.\n\nO ato de a União desapropriar, mediante prévia e justa indenização, para fins de reforma agrária, imóvel rural que não esteja cumprindo a sua função social configura desapropriação por utilidade pública.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4262820,"enunciado":"Com base nessa situação hipotética e na jurisprudência do STF acerca do tema, julgue os itens que se seguem.\n\nA norma que limitou a quinze o número de andares dos prédios a serem construídos na localidade constitui limitação administrativa que, dotada de caráter geral, se distingue das demais formas de intervenção estatal na propriedade, não caracterizando, via de regra, situação passível de indenização.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"limitacao administrativa","ancora":"limitacao-administrativa"},"E":{"topico":"limitacao administrativa","ancora":"limitacao-administrativa"}}},{"id":4262862,"enunciado":"No que se refere à classificação e às formas de utilização dos bens públicos, ao tombamento e à servidão administrativa, assinale a opção correta.","opcoes":["A servidão administrativa, direito real que autoriza o poder público a usar propriedade alheia para permitir a execução de obras e serviços de interesse público, gera, como regra, a obrigação de indenizar o proprietário.","Uso especial é a forma de utilização de bens públicos por meio da qual o indivíduo se submete à incidência da obrigação de pagar pelo uso, podendo os bens de uso especial estar sujeitos a uso especial remunerado, possibilidade que não se estende aos bens de uso comum, em relação aos quais não se admite nenhuma forma de pagamento.","O fechamento de rua para a realização de festa comunitária caracteriza autorização de uso, ato pelo qual a administração consente, a título precário, que particulares se utilizem de bem público de modo privativo, atendendo primordialmente a seus próprios interesses.","Assim como ocorre na autorização de uso, na permissão de uso, o interesse que predomina é o privado, ainda que haja interesse público como pano de fundo.","O tombamento, forma de intervenção do Estado na propriedade privada, tem por objetivo a proteção do patrimônio histórico e artístico, podendo atingir bens móveis ou imóveis, materiais ou imateriais, mas não bens públicos."],"correta":2,"explicacao":"Gabarito: <strong>O fechamento de rua para a realização de festa comunitária caracteriza autorização de uso, ato pelo qual a administração consente, a título precário, que particulares se utilizem de bem público de modo privativo, atendendo primordialmente a seus próprios interesses.</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"B":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"C":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"D":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"E":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"}}},{"id":4262913,"enunciado":"Acerca do instituto da servidão administrativa, é CORRETO afirmar:","opcoes":["a servidão administrativa impõe ao proprietário do imóvel um gravame de caráter temporário, que é característica típica desse instituto.","a servidão administrativa poderá concretizar-se por acordo entre o Poder Público e o proprietário.","a servidão administrativa opera transferência de posse do bem ao Poder Público.","nas situações em que a servidão administrativa decorre diretamente de lei, não é possível indenização."],"correta":1,"explicacao":"Gabarito: <strong>a servidão administrativa poderá concretizar-se por acordo entre o Poder Público e o proprietário.</strong>.","banca":"UEG","ano":2012,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4263000,"enunciado":"A Administração Pública desapropriou área com vistas à criação de um parque ecológico. No curso da implantação do citado parque, sobreveio necessidade de dispor da área para a criação de um Centro de Pesquisas Ambientais, o que foi levado a termo. Na escritura pública de desapropriação amigável constava cláusula de renúncia ao direito de recompra. O expropriado ajuizou Ação Ordinária de Retrocessão, alegando desvio de finalidade por parte do Ente Público expropriante, objetivando o reconhecimento do seu direito à recompra do bem. Diante dos fatos, analise as proposições abaixo e assinale a alternativa CORRETA: I - Assiste razão ao expropriado, pois a Administração não poderia utilizar o bem para finalidade diversa daquela prevista no decreto de desapropriação, sendo-lhe devido o reconhecimento do direito à retrocessão. II - Houve desvio de finalidade. III - Houve tredestinação lícita, pois o bem foi utilizado no atendimento às necessidades e ao interesse público, o que, segundo entendimento pacificado no âmbito do Superior Tribunal de Justiça, não gera direito à retrocessão. IV - A retrocessão é cabível somente nos casos de tredestinação ilícita. V - A retrocessão, de acordo com a lei civil vigente, limita-se ao direito de preferência conferido ao expropriado, pelo preço atual da coisa.","opcoes":["Apenas as proposições I e II estão incorretas.","Apenas as proposições II e III estão corretas.","Apenas as proposições III e IV estão incorretas.","Apenas as proposições I e II estão corretas.","Apenas as proposições II e V estão incorretas."],"correta":0,"explicacao":"Gabarito: <strong>Apenas as proposições I e II estão incorretas.</strong>.","banca":"PGE-PA","ano":2011,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4263005,"enunciado":"Analise as seguintes afirmativas sobre a servidão administrativa: I. Servidão administrativa é o direito real de gozo, de natureza pública, instituído sobre imóvel de propriedade alheia, com base em lei, por entidade pública ou por seus delegados, em favor de um serviço público ou de um bem afetado a um fim de utilidade pública. II. As servidões administrativas não se extinguem pelo não uso. III. Caberá justa e prévia indenização quando a servidão administrativa decorrer diretamente da lei, impondo-se em relação a toda uma coletividade de imóveis que se encontrem na mesma situação. Quais estão corretas?","opcoes":["Apenas I.","Apenas II.","Apenas I e II.","Apenas I e III.","Apenas II e III."],"correta":2,"explicacao":"Gabarito: <strong>Apenas I e II.</strong>.","banca":"FUNDATEC","ano":2011,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4263012,"enunciado":"Considere as seguintes afirmações a respeito da desapropriação. I. A declaração de utilidade pública para fins de desapropriação, dentre outros efeitos, fixa o estado do bem (sua condições e benfeitorias, por exemplo), confere ao Poder Público o direito de fazer medições e verificações no imóvel, estabelece o início do prazo de caducidade da declaração, e implica desde logo a transferência do bem ao domínio público, pela afetação ocorrida. II. A desapropriação indireta ocorre quando a Administração Pública se apossa de um bem sem a observância dos procedimentos legais; é por isso considerada um esbulho administrativo. Nesse caso, o título que servirá para a incorporação do bem ao patrimônio público, mediante registro no álbum imobiliário, é a sentença proferida na ação movida pelo proprietário do bem para receber a devida indenização. III. No caso de a indenização ser paga, em processo judicial expropriatório que resultou na incorporação do bem à Fazenda Pública, a terceiro que não o verdadeiro dono do bem não garante a este o direito de reivindicá-lo com base na nulidade do processo, resolvendo-se a relação apenas em perdas e danos, como se de expropriação indireta se tratasse. IV. Em ação judicial de desapropriação, a imissão na posse depende da declaração de urgência pelo expropriante alegável a qualquer momento do depósito da quantia fixada segundo critérios legais e de que o requerimento da imissão se dê em 120 dias, a contar da alegação de urgência, podendo esta ser renovada apenas uma vez. Quais estão corretas?","opcoes":["Apenas I, II e IV.","Apenas I e IV.","Apenas II, III e IV.","Apenas I, III e IV.","Apenas II e III."],"correta":4,"explicacao":"Gabarito: <strong>Apenas II e III.</strong>.","banca":"MPE-RS","ano":2011,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"caducidade urgencia 120 dias","ancora":"caducidade-urgencia-120-dias"},"B":{"topico":"caducidade urgencia 120 dias","ancora":"caducidade-urgencia-120-dias"},"C":{"topico":"caducidade urgencia 120 dias","ancora":"caducidade-urgencia-120-dias"},"D":{"topico":"caducidade urgencia 120 dias","ancora":"caducidade-urgencia-120-dias"},"E":{"topico":"caducidade urgencia 120 dias","ancora":"caducidade-urgencia-120-dias"}}},{"id":4263026,"enunciado":"A respeito da intervenção do Estado na propriedade, assinale a alternativa correta.","opcoes":["São modalidades de intervenção do Estado na propriedade privada: desapropriação, tombamento, ocupação temporária e imissão provisória na posse.","São requisitos essenciais de qualquer desapropriação o pagamento prévio de quantia justa e em dinheiro.","As limitações administrativas, em regra, devem ser indenizadas.","A requisição e a ocupação temporária não são indenizáveis, salvo se houver dano ao proprietário.","O tombamento é a única forma de proteção do patrimônio cultural brasileiro prevista pela Constituição Federal de 1988."],"correta":3,"explicacao":"Gabarito: <strong>A requisição e a ocupação temporária não são indenizáveis, salvo se houver dano ao proprietário.</strong>.","banca":"ISAE","ano":2011,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"B":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"C":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"D":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"E":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"}}},{"id":4263041,"enunciado":"O poder público comunicou a Maria que, em atendimento a interesse coletivo, precisaria erguer postes de energia elétrica dentro de sua propriedade privada para levar luz a um vilarejo próximo, instituindo direito real sobre a área atingida. Nessa situação hipotética, incide, sobre o bem de Maria,","opcoes":["concessão de uso.","limitação administrativa.","servidão administrativa.","ocupação temporária.","desapropriação indireta."],"correta":2,"explicacao":"Gabarito: <strong>servidão administrativa.</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4263043,"enunciado":"José é permissionário de uma lanchonete que funciona ao lado da prefeitura e atende aos servidores que ali trabalham. O pequeno estabelecimento, construído dentro do terreno da prefeitura, vem sendo utilizado e conservado por José há mais de vinte anos. O novo prefeito, que pretendia usar o espaço da lanchonete para ampliar o seu gabinete, expediu ato administrativo revogando a permissão de uso do bem público. José procurou a DP para obter orientação jurídica com relação à situação, já que depende da lanchonete para sustentar sua família. Considerando essa situação hipotética, assinale a opção que, em conformidade com o ordenamento jurídico, a doutrina e a jurisprudência, pode subsidiar a orientação jurídica.","opcoes":["Sendo o ato bilateral e estável, deveria a prefeitura ter ajuizado ação de despejo a fim de reaver o imóvel.","É cabível o ajuizamento de medida cautelar de penhora a fim de garantir a indisponibilidade do bem até que a legalidade do ato do prefeito seja aferida.","Caracterizando-se o ato do prefeito como unilateral, discricionário e precário, a única medida possível é verificar a regularidade dos motivos do ato revogador, a fim de aferir possível desvio de finalidade em prejuízo do permissionário.","É cabível o mandado de segurança sob a alegação de que o ato do prefeito consiste, de fato, em desapropriação indireta disfarçada de revogação.","É cabível ação de usucapião em razão do longo tempo de exercício da posse mansa e pacífica do bem."],"correta":2,"explicacao":"Gabarito: <strong>Caracterizando-se o ato do prefeito como unilateral, discricionário e precário, a única medida possível é verificar a regularidade dos motivos do ato revogador, a fim de aferir possível desvio de finalidade em prejuízo do permissionário.</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4263080,"enunciado":"No caso da Administração Pública impor a um imóvel particular limitações que terminem por inviabilizar qualquer aproveitamento da propriedade, estar-se-á diante de hipótese de desapropriação indireta. O instituto afeto à desapropriação direta que se aplica à desapropriação indireta:","opcoes":["a retrocessão.","o direito de extensão.","o desapossamento ficto.","os juros compensatórios.","a avaliação administrativa."],"correta":3,"explicacao":"Gabarito: <strong>os juros compensatórios.</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4263113,"enunciado":"A Administração desapropriou um terreno particular para construção de uma escola, porém, por insuficiência de recursos orçamentários, desistiu da construção. Nessa situação, poderá","opcoes":["dar ao terreno destinação diversa daquela que originou a desapropriação, mediante o instituto da retrocessão.","alienar o terreno a outro particular, independentemente de oferecimento prévio ao expropriado, desde que já tenha pago a integralidade da indenização.","exigir do expropriado a restituição do valor da indenização, mediante a devolução a este do terreno desapropriado, expurgando-se os juros compensatórios.","alienar o terreno por meio de procedimento licitatório, oferecendo-o, previamente, ao expropriado, sob pena de caracterizar tredestinação.","alienar o terreno, exclusivamente ao expropriado, por valor estabelecido em avaliação atualizada."],"correta":1,"explicacao":"Gabarito: <strong>alienar o terreno a outro particular, independentemente de oferecimento prévio ao expropriado, desde que já tenha pago a integralidade da indenização.</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4263288,"enunciado":"As limitações ao Direito de Propriedade, implicam, além de outras hipóteses, afirmar:","opcoes":["Se um bem tombado pertencer ao domínio público, torna-se inalienável para particulares, vedada em qualquer hipótese, a sua transferência de uma entidade pública para outra.","Abrangem as restrições que afetam o caráter absoluto do direito de propriedade como a ocupação temporária, a requisição e a servidão, que atingem o caráter exclusivo, e a desapropriação, incidente sobre o caráter perpétuo.","A servidão administrativa opera a transferência do domínio, da posse e do uso total do bem ao poder público.","Na desapropriação, a “indenização justa” abrange o ressarcimento dos prejuízos financeiros suportados pelo expropriado, exceto honorários de advogado, juros compensatórios e custas processuais.","Retrocessão é o ato declaratório que, nas desapropriações indiretas, transfere ao patrimônio do Poder Público o domínio e a propriedade sobre o bem expropriado."],"correta":0,"explicacao":"Gabarito: <strong>Se um bem tombado pertencer ao domínio público, torna-se inalienável para particulares, vedada em qualquer hipótese, a sua transferência de uma entidade pública para outra.</strong>.","banca":"FCC","ano":2010,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4263335,"enunciado":"Sobre a desapropriação, é correto afirmar:","opcoes":["Para fins de reforma agrária é vedado ao proprietário o direito de extensão, isto é, em nenhuma hipótese pode ele pedir a desapropriação de todo o imóvel quando apenas parte deste foi objeto da ação.","A desapropriação de propriedade rural por interesse social, para fins de reforma agrária, é de competência privativa da União.","Em nenhuma hipótese o espaço aéreo e o subsolo podem ser objeto de desapropriação.","É forma derivada de aquisição da propriedade.","A pequena propriedade rural pode ser objeto de desapropriação para fins de reforma agrária, mesmo que seu proprietário não possua outra."],"correta":2,"explicacao":"Gabarito: <strong>Em nenhuma hipótese o espaço aéreo e o subsolo podem ser objeto de desapropriação.</strong>.","banca":"FCC","ano":2010,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"subsolo espaco aereo","ancora":"subsolo-espaco-aereo"},"B":{"topico":"subsolo espaco aereo","ancora":"subsolo-espaco-aereo"},"C":{"topico":"subsolo espaco aereo","ancora":"subsolo-espaco-aereo"},"D":{"topico":"subsolo espaco aereo","ancora":"subsolo-espaco-aereo"},"E":{"topico":"subsolo espaco aereo","ancora":"subsolo-espaco-aereo"}}},{"id":4263389,"enunciado":"No que se refere à desapropriação, julgue o item seguinte.\n\nCompete aos municípios a desapropriação por descumprimento da função social da propriedade urbana, e aos estados, a desapropriação de imóvel rural, por interesse social, para fins de reforma agrária.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4263402,"enunciado":"No que se refere às restrições estatais sobre a propriedade privada, assinale a opção correta.","opcoes":["É possível que determinado município institua servidão administrativa sobre imóvel pertencente ao estado, desde que a autorização tenha sido concedida por lei municipal.","A instituição de uma servidão administrativa é permanente e não admite extinção.","O tombamento incide somente sobre bens imóveis, dada a sua natureza.","Na desapropriação por utilidade pública, o prazo de caducidade do decreto expropriatório é de cinco anos, contado a partir da data da sua expedição.","Compete à União desapropriar propriedades rurais, por interesse social e para fins de reforma agrária, mediante o pagamento prévio e justo da indenização em dinheiro."],"correta":3,"explicacao":"Gabarito: <strong>Na desapropriação por utilidade pública, o prazo de caducidade do decreto expropriatório é de cinco anos, contado a partir da data da sua expedição.</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"B":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"C":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"D":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"E":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"}}},{"id":4263448,"enunciado":"Analise as seguintes afirmativas e assinale a alternativa CORRETA.","opcoes":["O tombamento é instrumento constitucional mais eficaz para a preservação do patrimônio cultural, protegendo indistintamente bens móveis, imóveis e imateriais.","Apesar de a doutrina divergir sobre a natureza jurídica do bem tombado, a legislação brasileira optou claramente pela intitulada Domínio Eminente do Estado.","O Direito Constitucional brasileiro não contempla a possibilidade da efetivação do denominado Tombamento por Lei.","Quanto aos efeitos, o tombamento ostenta natureza dúplice ou mista, pois, juntamente com efeitos constitutivos, apresenta importante nota declaratória."],"correta":3,"explicacao":"Gabarito: <strong>Quanto aos efeitos, o tombamento ostenta natureza dúplice ou mista, pois, juntamente com efeitos constitutivos, apresenta importante nota declaratória.</strong>.","banca":"MPE-MG","ano":2010,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"B":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"C":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"D":{"topico":"tombamento conceito","ancora":"tombamento-conceito"}}},{"id":4263505,"enunciado":"Assinale a alternativa correta: I. É possível, antes de uma ação desapropriatória, o Poder Público e o proprietário acordarem sobre o preço do bem imóvel. II. Tendo a alienação do bem se consumado por meio de negócio jurídico bilateral e amigável, este acordo suprirá, in specie, o caráter de coercitividade de que se reveste a desapropriação, prevalecendo a natureza jurídica negocial e a teoria da autonomia da vontade. III. As desapropriações podem recair sobre bens móveis e imóveis tanto da pessoa física como jurídica, pública ou privada. IV. O procedimento da desapropriação possui somente a fase declaratória. V. Havendo muita pressa na desapropriação, alegada pela Administração Pública, o juiz pode negar a imissão provisória na posse, mesmo quando já depositada a quantia arbitrada.","opcoes":["Somente as proposições I e III estão incorretas.","Somente as proposições II e V estão incorretas.","Somente as proposições I e IV estão incorretas.","Somente as proposições IV e V estão incorretas.","Todas as proposições estão incorretas."],"correta":3,"explicacao":"Gabarito: <strong>Somente as proposições IV e V estão incorretas.</strong>.","banca":"TJ-SC","ano":2010,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"},"B":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"},"C":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"},"D":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"},"E":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"}}},{"id":4263519,"enunciado":"O poder público pode intervir na propriedade do particular por atos que visem satisfazer as exigências coletivas e reprimir a conduta antissocial do particular. Essa intervenção do Estado, consagrada na Constituição Federal, é regulada por leis federais que disciplinam as medidas interventivas e estabelecem o modo e a forma de sua execução, condicionando o atendimento do interesse público ao respeito às garantias individuais previstas na Constituição. Acerca da intervenção do Estado na propriedade particular, julgue os itens subsequentes.\n\nAs indenizações referentes a processo de desapropriação sempre devem ser pagas em moeda corrente ao expropriado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4263547,"enunciado":"Respeitados os requisitos e trâmites legais, é possível ao Estado-membro desapropriar,","opcoes":["mediante prévia e justa indenização em dinheiro, imóvel não utilizado pertencente a sociedade de economia mista federal exploradora de atividade econômica em sentido estrito.","mediante pagamento em títulos da dívida pública, área urbana não edificada, subutilizada ou não utilizada, cujo proprietário tenha sido regularmente notificado para promover o adequado aproveitamento.","após prévia autorização legislativa, emitida pelo Congresso Nacional, imóvel da União que seja utilizado para defesa das fronteiras nacionais.","para fins de reforma agrária e mediante pagamentos em títulos, imóvel rural que não esteja cumprindo sua função social.","mediante prévia e justa indenização em dinheiro, pessoa jurídica que tenha sido constituída por particulares."],"correta":0,"explicacao":"Gabarito: <strong>mediante prévia e justa indenização em dinheiro, imóvel não utilizado pertencente a sociedade de economia mista federal exploradora de atividade econômica em sentido estrito.</strong>.","banca":"FCC","ano":2010,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"distincao instrumentos intervencao","ancora":"distincao-instrumentos-intervencao"},"B":{"topico":"distincao instrumentos intervencao","ancora":"distincao-instrumentos-intervencao"},"C":{"topico":"distincao instrumentos intervencao","ancora":"distincao-instrumentos-intervencao"},"D":{"topico":"distincao instrumentos intervencao","ancora":"distincao-instrumentos-intervencao"},"E":{"topico":"distincao instrumentos intervencao","ancora":"distincao-instrumentos-intervencao"}}},{"id":4263572,"enunciado":"A desapropriação, modo involuntário de perda da propriedade imóvel, pode ocorrer em caso de necessidade pública, sendo obrigatória a prévia e justa indenização ao proprietário do imóvel desapropriado.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4263603,"enunciado":"Assinale a opção correta a respeito da intervenção do Estado na propriedade privada e do instituto da desapropriação.","opcoes":["O tombamento implica limitação precária e temporária ao direito de propriedade em benefício do interesse coletivo e incide apenas sobre bens imóveis.","A servidão administrativa, que impõe ao proprietário a obrigação de suportar ônus parcial sobre o imóvel de sua propriedade, é direito real instituído tanto em favor do Estado quanto de particulares.","Requisição é a modalidade de intervenção estatal por meio da qual o Estado utiliza bens móveis, imóveis e serviços particulares em situação de perigo público iminente, tanto para fins militares quanto civis.","A ocupação temporária é direito de caráter real que tem natureza de permanência e exige situação de perigo público iminente, tanto quanto a requisição.","Quaisquer entes federativos podem desapropriar bens públicos uns dos outros, desde que devidamente autorizados pelo Poder Legislativo de seu âmbito."],"correta":2,"explicacao":"Gabarito: <strong>Requisição é a modalidade de intervenção estatal por meio da qual o Estado utiliza bens móveis, imóveis e serviços particulares em situação de perigo público iminente, tanto para fins militares quanto civis.</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"B":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"C":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"D":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"E":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"}}},{"id":4263609,"enunciado":"Quanto às restrições do Estado sobre a propriedade privada, segundo o direito pátrio, é CORRETO afirmar que","opcoes":["a requisição administrativa pode incidir sobre bens móveis e imóveis e ainda sobre serviços particulares, sendo procedimento unilateral, autoexecutório e oneroso, demandando prévia indenização.","a Constituição Federal de 1988 conferiu à União, Estados e Municípios a competência concorrente para legislar sobre proteção ao patrimônio histórico, cultural, artístico, turístico e paisagístico.","o Estado-membro não pode atribuir, por lei, poder expropriatório a entidade de sua administração indireta.","a ação popular e a ação civil pública são instrumentos aptos à proteção de bens de valor histórico e artístico, desde que assim considerados através da inscrição no competente Livro de Tombo.","a desapropriação por interesse social surgiu no direito brasileiro em 1964 com a finalidade específica de possibilitar a chamada reforma agrária, permitindo, desde então, a indenização em títulos da dívida pública."],"correta":2,"explicacao":"Gabarito: <strong>o Estado-membro não pode atribuir, por lei, poder expropriatório a entidade de sua administração indireta.</strong>.","banca":"MPE-MG","ano":2010,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"B":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"C":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"D":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"E":{"topico":"tombamento conceito","ancora":"tombamento-conceito"}}},{"id":4263800,"enunciado":"Em relação à intervenção do Estado na propriedade privada, assinale a opção correta.","opcoes":["Quanto à forma de constituição da servidão, consideram-se genéricas as servidões que atingem bens indeterminados e específicas as que atingem bens determinados.","As servidões administrativas são sempre indenizáveis, ainda que não causem qualquer dano ou não impeçam o uso normal da propriedade pelo particular.","A base de cálculo dos honorários advocatícios em desapropriação é o valor da oferta realizada pelo poder público e não o da indenização efetivamente paga.","Segundo entendimento do STJ, no procedimento de desapropriação de imóvel pelo poder público, são inacumuláveis juros compensatórios e moratórios.","Na desapropriação direta, os juros compensatórios são devidos desde a antecipada imissão na posse e, na desapropriação indireta, a partir da efetiva ocupação do imóvel."],"correta":4,"explicacao":"Gabarito: <strong>Na desapropriação direta, os juros compensatórios são devidos desde a antecipada imissão na posse e, na desapropriação indireta, a partir da efetiva ocupação do imóvel.</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"B":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"C":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"D":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"E":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"}}},{"id":4263868,"enunciado":"Acerca da desapropriação por utilidade pública, assinale a opção correta.","opcoes":["Podem executar a desapropriação as concessionárias e permissionárias de serviços públicos, assim como autarquias, fundações instituídas e mantidas pelo poder público, empresas públicas e sociedades de economia mista, mediante autorização expressa, constante de lei ou contrato.","O termo inicial para o prazo de caducidade da declaração emitida pelo poder público é de dois anos, contados da data de expedição do respectivo decreto.","Segundo o STF, a imissão provisória na posse dos bens, mesmo que precedido do depósito do valor correspondente ao valor cadastral do imóvel e independentemente da citação do réu, contraria o princípio da justa e prévia indenização em dinheiro estipulado na CF.","Segundo o STF, a base de cálculo dos honorários advocatícios na desapropriação é o valor da condenação.","O Poder Judiciário poderá decidir, no processo de desapropriação, se ocorrem ou não os casos de utilidade pública."],"correta":0,"explicacao":"Gabarito: <strong>Podem executar a desapropriação as concessionárias e permissionárias de serviços públicos, assim como autarquias, fundações instituídas e mantidas pelo poder público, empresas públicas e sociedades de economia mista, mediante autorização expressa, constante de lei ou contrato.</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"B":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"C":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"D":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"E":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"}}},{"id":4263869,"enunciado":"No que concerne às formas de intervenção do Estado na propriedade, assinale a opção correta.","opcoes":["Ocupação temporária é a modalidade de intervenção estatal na propriedade particular fundada na urgência, que incide sobre bens móveis, imóveis e até mesmo serviços prestados por particulares.","Quanto à eficácia, o tombamento dos bens poderá ser provisório ou definitivo, mas nem sempre poderá gerar direito a indenização.","A requisição administrativa destina-se ao uso da propriedade do particular, ocorre sempre em caso de urgência - mediante autorização judicial - e não enseja qualquer indenização ao particular.","Segundo jurisprudência reiterada do STF, a limitação administrativa non aedificandi imposta aos terrenos marginais nas estradas de rodagem da zona rural afeta o domínio do particular e obriga a administração a promover a indenização devida.","O tombamento somente poderá incidir sobre bens particulares, não havendo previsão legal para incidir sobre bens públicos."],"correta":1,"explicacao":"Gabarito: <strong>Quanto à eficácia, o tombamento dos bens poderá ser provisório ou definitivo, mas nem sempre poderá gerar direito a indenização.</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"B":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"C":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"D":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"E":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"}}},{"id":4263900,"enunciado":"O seguinte dispositivo do Decreto-Lei nº 3.365/41 teve sua constitucionalidade questionada perante o Supremo Tribunal Federal: \"Art. 15-A. No caso de imissão prévia na posse, na desapropriação por necessidade ou utilidade pública e interesse social, inclusive para fins de reforma agrária, havendo divergência entre o preço ofertado em juízo e o valor do bem, fixado na sentença, expressos em termos reais, incidirão juros compensatórios de até seis por cento ao ano sobre o valor da diferença eventualmente apurada, a contar da imissão na posse, vedado o cálculo de juros compostos\". Por decisão em medida cautelar em ação direta de inconstitucionalidade, entre outros aspectos, o Supremo Tribunal Federal entendeu que","opcoes":["o termo inicial da incidência dos juros compensatórios é o trânsito em julgado da sentença.","a diferença sobre a qual deva incidir os juros compensatórios se dá entre 80% do preço ofertado em juízo e o valor do bem fixado na sentença.","não incidem juros compensatórios em desapropriação por interesse social.","não é mais compatível com a Constituição Federal vigente a imissão prévia na posse.","é necessário o cálculo de juros compostos em se tratando da incidência de juros compensatórios."],"correta":1,"explicacao":"Gabarito: <strong>a diferença sobre a qual deva incidir os juros compensatórios se dá entre 80% do preço ofertado em juízo e o valor do bem fixado na sentença.</strong>.","banca":"FCC","ano":2009,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"B":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"C":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"D":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"E":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"}}},{"id":4263982,"enunciado":"Considere as seguintes afirmações, relativas ao processo de desapropriação: I. no curso do processo, é vedado ao particular discutir o mérito da declaração de utilidade pública. II. é permitida a imissão provisória na posse, independentemente de depósito por parte do Poder Público. III. é permitida a fixação da indenização por acordo entre o Poder Público e o proprietário. Está correto o que se afirma em","opcoes":["II e III, apenas.","I, II e III.","I, apenas.","I e II, apenas.","I e III, apenas."],"correta":4,"explicacao":"Gabarito: <strong>I e III, apenas.</strong>.","banca":"FCC","ano":2009,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"B":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"C":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"D":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"E":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"}}},{"id":4263993,"enunciado":"Quanto ao direito de propriedade e à desapropriação, assinale a opção correta.","opcoes":["A CF contempla hipótese de desapropriação de imóvel urbano não edificado mediante pagamento em títulos da dívida pública municipal.","De acordo com a jurisprudência do STF, a justa indenização na desapropriação de imóvel urbano deve ser observada no momento da imissão provisória na posse e não quando ocorre a transferência do domínio.","Segundo o STF, o decreto que declara um imóvel de utilidade pública para fins de desapropriação é ato normativo, que pode ser objeto de ADI.","Considerando a competência da União para desapropriar por interesse social, para fins de reforma agrária, o imóvel rural que não esteja cumprindo sua função social, as operações de transferência desse bem são isentas exclusivamente de impostos federais.","É facultado ao poder público municipal, mediante lei específica para área incluída no plano diretor, exigir, nos termos de lei estadual, que o proprietário do solo urbano não edificado, subutilizado ou não utilizado promova seu adequado aproveitamento."],"correta":0,"explicacao":"Gabarito: <strong>A CF contempla hipótese de desapropriação de imóvel urbano não edificado mediante pagamento em títulos da dívida pública municipal.</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"competencia desapropriar","ancora":"competencia-desapropriar"},"B":{"topico":"competencia desapropriar","ancora":"competencia-desapropriar"},"C":{"topico":"competencia desapropriar","ancora":"competencia-desapropriar"},"D":{"topico":"competencia desapropriar","ancora":"competencia-desapropriar"},"E":{"topico":"competencia desapropriar","ancora":"competencia-desapropriar"}}},{"id":4264141,"enunciado":"Pela retrocessão, a lei permite que a parte despojada do seu direito de propriedade possa reivindicá-lo, se o imóvel não tiver sido utilizado para o fim declarado na desapropriação. Ante a impossibilidade de fazê-lo (ad impossibilia nemo tenetur), subjaz-lhe a ação de perdas e danos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4264169,"enunciado":"Constitui entendimento sumulado dos Tribunais Superiores, EXCETO:","opcoes":["É cabível execução por título extrajudicial contra a Fazenda Pública.","No tribunal de contas estadual, composto por sete conselheiros, quatro devem ser escolhidos pela assembléia legislativa e três pelo chefe do poder executivo estadual, sendo que, destes, uma escolha é discricionária e as outras duas são vinculadas.","Os créditos de natureza alimentícia não dispensam a expedição de precatório, apenas são isentos da observância da ordem cronológica dos precatórios decorrentes de condenações de outra natureza.","É inconstitucional a imissão provisória independentemente de citação do réu em ação de desapropriação."],"correta":3,"explicacao":"Gabarito: <strong>É inconstitucional a imissão provisória independentemente de citação do réu em ação de desapropriação.</strong>.","banca":"EJEF","ano":2009,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"B":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"C":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"D":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"}}},{"id":4264181,"enunciado":"O ato pelo qual a Administração dá ao bem expropriado destinação de interesse público diversa daquela inicialmente prevista denomina-se","opcoes":["retrocessão.","desapropriação.","reversão.","desvio de finalidade.","tredestinação."],"correta":4,"explicacao":"Gabarito: <strong>tredestinação.</strong>.","banca":"FCC","ano":2009,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4264293,"enunciado":"Em matéria de intervenção do Estado na propriedade, analise: I. Utilização transitória, remunerada ou gratuita, de bens particulares pelo Poder Público, para a execução de obras, serviços ou atividades públicas ou de interesse público, como modalidade de intervenção do Estado na propriedade. II. Toda imposição geral, gratuita, unilateral e de ordem pública condicionada ao exercício de direitos ou de atividades particulares às exigências do bem- estar social. Tais situações dizem respeito, respectivamente, a","opcoes":["desapropriação e requisição.","ocupação temporária e limitação administrativa.","servidão administrativa e tombamento.","requisição e ocupação temporária.","limitação administrativa e tombamento."],"correta":1,"explicacao":"Gabarito: <strong>ocupação temporária e limitação administrativa.</strong>.","banca":"FCC","ano":2008,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4264313,"enunciado":"Determinado órgão da administração pública estadual licitou, contratou e executou a construção de uma unidade prisional em um terreno situado no interior do Estado. Após o início das atividades, descobriu-se que o domínio terreno pertencia a um particular, ao qual caberá exigir","opcoes":["a demolição da construção e a reintegração na posse.","indenização, alegando ter havido desapropriação indireta.","indenização, requerendo a desapropriação direta do bem.","a indenização pelo valor do terreno e a demolição da construção.","a imediata interrupção das atividades desempenhadas no local até a indenização pelo valor do terreno."],"correta":1,"explicacao":"Gabarito: <strong>indenização, alegando ter havido desapropriação indireta.</strong>.","banca":"FCC","ano":2008,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4264344,"enunciado":"Considere as seguintes assertivas: I. No caso de iminente perigo público, a autoridade competente poderá usar de propriedade particular, assegurada ao proprietário indenização ulterior, se houver dano. II. São isentas de impostos federais, estaduais e municipais as operações de transferência de imóveis desapropriados para fins de reforma agrária. III. Compete a União, aos Estados e ao Distrito Federal legislar concorrentemente sobre a desapropriação. Com fundamento na Constituição da República, estão corretas:","opcoes":["Todas as assertivas.","Apenas a assertiva I.","As assertivas I e III.","As assertivas I e II."],"correta":3,"explicacao":"Gabarito: <strong>As assertivas I e II.</strong>.","banca":"IESES","ano":2008,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"B":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"C":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"D":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"}}},{"id":4264350,"enunciado":"O Poder Público lançou mão, urgente e transitoriamente, de um prédio de três andares, pertencente a João Silva, empresário do ramo de equipamentos de incêndio, para atender demanda de perigo iminente. Nesse caso, ele o fez, corretamente, por meio de","opcoes":["limitação administrativa.","ocupação temporária.","desapropriação indireta.","servidão administrativa.","requisição."],"correta":4,"explicacao":"Gabarito: <strong>requisição.</strong>.","banca":"FCC","ano":2008,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4264355,"enunciado":"Assinale a opção correta a respeito da desapropriação.","opcoes":["Apenas a União pode desapropriar imóvel rural.","Bens públicos não podem ser desapropriados.","O registro da desapropriação independe da verificação de que o imóvel pertence à pessoa que figure no processo expropriatório como proprietário.","Na sua feição indireta, aceita no ordenamento jurídico brasileiro, o Estado é livre de indenizar o particular.","A desapropriação deve ser precedida de indenização em dinheiro, à exceção da destinada à reforma agrária."],"correta":2,"explicacao":"Gabarito: <strong>O registro da desapropriação independe da verificação de que o imóvel pertence à pessoa que figure no processo expropriatório como proprietário.</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"B":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"C":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"D":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"E":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"}}},{"id":4264357,"enunciado":"Assinale a opção correta com referência à desapropriação.","opcoes":["A desapropriação, por interesse social, de imóvel rural que não cumpra sua função social importa prévia e justa indenização da área e das benfeitorias úteis com títulos da dívida agrária.","Os valores de custas e emolumentos devem ser pagos pelo expropriante porque a imunidade tributária somente alcança os impostos.","A pequena propriedade rural não pode ser objeto de desapropriação para fim de reforma agrária.","A valorização extraordinária de terras pela conclusão de obra pública, no caso em que não sejam ditas áreas socialmente aproveitadas, caracteriza interesse social para decretação de desapropriação.","Os bens desapropriados por interesse social passam a integrar o patrimônio do expropriante, que não poderá aliená-lo no prazo de 10 anos, mas poderá alugá-lo por até 1%, por mês, do valor pago na indenização."],"correta":3,"explicacao":"Gabarito: <strong>A valorização extraordinária de terras pela conclusão de obra pública, no caso em que não sejam ditas áreas socialmente aproveitadas, caracteriza interesse social para decretação de desapropriação.</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4264367,"enunciado":"Acerca da desapropriação, assinale a opção correta.","opcoes":["A desapropriação de um bem destina-se, em todos os casos, a retirá-lo da esfera particular e incluí-lo no patrimônio do Estado.","O Estado pode desapropriar as zonas que se valorizem extraordinariamente em conseqüência de obra ou serviço público feitos na área.","O procedimento da desapropriação envolve duas fases: a executória, realizada pelo Poder Executivo, e a judicial, realizada pelo Poder Judiciário.","Tresdestinação é a obrigação que tem o expropriante de oferecer ao expropriado o bem, sempre que a este for dada destinação diversa da indicada no ato expropriatório.","A desapropriação para fins de reforma agrária deve ser feita mediante pagamento de indenização justa, prévia e em dinheiro."],"correta":1,"explicacao":"Gabarito: <strong>O Estado pode desapropriar as zonas que se valorizem extraordinariamente em conseqüência de obra ou serviço público feitos na área.</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4264399,"enunciado":"O governador do estado de Rondônia, em atendimento a um pleito de organizações da sociedade civil, que atuam na defesa do meio ambiente, criou uma reserva florestal no estado. Pedro, que possui uma fazenda no local, na qual se desenvolve atividade pecuária e de ecoturismo, entendendo que houve prejuízo econômico em decorrência desse ato, ingressou com ação na justiça. Com base nessa situação hipotética, assinale a opção correta a respeito da intervenção do estado na propriedade.","opcoes":["O governador do estado de Rondônia não tem competência para declarar uma área como de interesse social para criar uma reserva florestal, já que essa matéria é de competência da União.","A natureza jurídica dessa espécie de intervenção do estado na propriedade é de desapropriação indireta.","Pedro fará jus a indenização somente se houver comprometimento na exploração econômica de sua propriedade com a criação da reserva florestal.","Os juros compensatórios, se devidos, têm de ser calculados na taxa de 12% ao ano, a contar do trânsito em julgado da sentença condenatória.","Os juros moratórios, na espécie, se devidos, têm de ser fixados em 1% ao mês, a contar da data do trânsito em julgado da respectiva sentença."],"correta":2,"explicacao":"Gabarito: <strong>Pedro fará jus a indenização somente se houver comprometimento na exploração econômica de sua propriedade com a criação da reserva florestal.</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"B":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"C":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"D":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"E":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"}}},{"id":4264475,"enunciado":"O tombamento voluntário de bem pertencente a pessoa física impede a alienação da coisa tombada.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"tombamento alienacao","ancora":"tombamento-alienacao"},"E":{"topico":"tombamento alienacao","ancora":"tombamento-alienacao"}}},{"id":4264485,"enunciado":"Assinale a alternativa correta.","opcoes":["Segundo jurisprudência dos Tribunais Superiores, a imissão provisória do Poder Público no bem, em procedimento expropriatório, na desapropriação por utilidade pública, é inconstitucional à luz da Constituição Federal de 1988.","As desapropriações de imóveis urbanos serão feitas com prévia e justa indenização. No entanto, caso o imóvel não esteja cumprindo sua função social, poderá o Poder Público Municipal, após a aplicação de outras medidas previstas na Constituição Federal, desapropriar o imóvel com pagamento mediante títulos da dívida pública de emissão prévia, aprovada pelo Senado Federal, com prazo de resgate de até 10 anos, em parcelas anuais, iguais e sucessivas, assegurados o valor real da indenização e os juros legais.","O decreto que declarar o imóvel como de interesse social, para os fins de reforma agrária, autoriza desde já ao Município propor a ação de desapropriação.","Segundo comando constitucional, nos casos de \"desapropriação confisco\", as terras desapropriadas devem integrar, de forma permanente, o patrimônio do ente federativo expropriante, que deverá utilizá-las para o cultivo de produtos alimentícios e medicamentosos.","A declaração expropriatória, nas desapropriações por utilidade pública, é o marco para a indenização das benfeitorias necessárias. Essas serão indenizadas se realizadas até a data da publicação da declaração."],"correta":1,"explicacao":"Gabarito: <strong>As desapropriações de imóveis urbanos serão feitas com prévia e justa indenização. No entanto, caso o imóvel não esteja cumprindo sua função social, poderá o Poder Público Municipal, após a aplicação de outras medidas previstas na Constituição Federal, desapropriar o imóvel com pagamento mediante títulos da dívida pública de emissão prévia, aprovada pelo Senado Federal, com prazo de resgate de até 10 anos, em parcelas anuais, iguais e sucessivas, assegurados o valor real da indenização e os juros legais.</strong>.","banca":"FGV","ano":2008,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"B":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"C":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"D":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"E":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"}}},{"id":4264618,"enunciado":"No que diz respeito à desapropriação, é INCORRETO afirmar que","opcoes":["a indenização justa é a que cobre não só o valor real e atual dos bens expropriados, à data do pagamento, como, também, os danos emergentes e os lucros cessantes do proprietário, decorrentes do despojamento do seu patrimônio.","todos os bens e direitos patrimoniais prestam-se à desapropriação, inclusive o espaço aéreo e o subsolo.","a desapropriação da propriedade é a regra, mas a posse legítima ou de boa-fé também é expropriável, por ter valor econômico para o possuidor, principalmente quando se trata de imóvel utilizado ou cultivado pelo posseiro.","a declaração expropriatória pode ser feita por lei ou decreto em que se identifique o bem, se indique seu destino e se aponte o dispositivo legal que a autorize.","a retrocessão é possível até a incorporação do bem ao patrimônio do expropriante, ou seja, até o trânsito em julgado da sentença ou o registro do título resultante do acordo."],"correta":2,"explicacao":"Gabarito: <strong>a desapropriação da propriedade é a regra, mas a posse legítima ou de boa-fé também é expropriável, por ter valor econômico para o possuidor, principalmente quando se trata de imóvel utilizado ou cultivado pelo posseiro.</strong>.","banca":"FCC","ano":2007,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4264619,"enunciado":"É certo que a servidão administrativa é","opcoes":["ônus real de uso imposto especificamente pelo Poder Público sobre a propriedade particular, com finalidade de serventia pública - publicae utilitatis.","direito real de um prédio particular sobre o outro, com finalidade de serventia privada- uti singuli.","restrição pessoal, geral e gratuita, imposta genericamente pelo Poder Público ao exercício de direitos individuais, em benefício da coletividade.-","instituto que despoja o proprietário do domínio sobre o imóvel público ou particular, com a conseqüente e imprescindível indenização.","a limitação administrativa que impõe uma obrigação de não fazer, incidente sobre o proprietário e não sobre imóvel particular, somente se perfazendo mediante prévia e justa indenização."],"correta":1,"explicacao":"Gabarito: <strong>direito real de um prédio particular sobre o outro, com finalidade de serventia privada- uti singuli.</strong>.","banca":"FCC","ano":2007,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4264670,"enunciado":"No que tange à intervenção do Estado na propriedade, assinale a opção correta.","opcoes":["Conforme entendimento do STJ, a imissão provisória na posse não representa a transferência de domínio. Dessa forma, o IPTU continua a ser devido pelo proprietário.","O decreto de desapropriação por interesse social caduca no prazo de 5 anos.","O tombamento não incide sobre bens móveis.","A concessão de uso para fins de moradia, que decorre do poder discricionário da Administração Pública, tem natureza jurídica de contrato administrativo.","O direito de preempção municipal tem natureza jurídica de limitação administrativa."],"correta":4,"explicacao":"Gabarito: <strong>O direito de preempção municipal tem natureza jurídica de limitação administrativa.</strong>.","banca":"CESPE / CEBRASPE","ano":2007,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"B":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"C":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"D":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"E":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"}}},{"id":4264701,"enunciado":"Em tema de desapropriação, é correto afirmar:","opcoes":["Na desapropriação para instituir servidão administrativa são devidos juros compensatórios pela limitação de uso da propriedade;","A desapropriação poderá abranger a área contígua necessária ao desenvolvimento da obra a que se destina, e as zonas que se valorizarem extraordinariamente, em conseqüência da realização do serviço, independentemente de a declaração de utilidade pública compreendê-las e da discriminação entre as indispensáveis à continuação da obra e as que se destinam à revenda;","As glebas de qualquer região do País onde forem localizadas culturas ilegais de plantas psicotrópicas serão imediatamente expropriadas, sem qualquer indenização ao proprietário, e reverterão em benefício de instituições e pessoal especializados no tratamento e recuperação de viciados e no aparelhamento e custeio de atividades de fiscalização, controle, prevenção e repressão do crime de tráfico de drogas;","Na desapropriação por interesse social, o expropriante tem o prazo de 5 (cinco) anos, a partir da decretação da desapropriação, para iniciar as providências de aproveitamento do bem expropriado."],"correta":0,"explicacao":"Gabarito: <strong>Na desapropriação para instituir servidão administrativa são devidos juros compensatórios pela limitação de uso da propriedade;</strong>.","banca":"TJ-DFT","ano":2007,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"B":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"C":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"D":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"}}},{"id":4264813,"enunciado":"Sobre a intervenção do Estado na propriedade, sob a modalidade de desapropriação, marque a opção FALSA.","opcoes":["Um Estado-membro pode promover a desapropriação de imóvel rural por interesse social.","A competência para declarar a utilidade pública ou o interesse social é concorrente da União, dos Estados, do Distrito Federal e dos Municípios.","Desapropriação é o procedimento de direito público pelo qual o Poder Público transfere para si a propriedade de terceiro, exigindo-se, sempre, o prévio pagamento de indenização.","A Lei poderá atribuir competência declaratória (declaração de utilidade pública) a uma autarquia."],"correta":2,"explicacao":"Gabarito: <strong>Desapropriação é o procedimento de direito público pelo qual o Poder Público transfere para si a propriedade de terceiro, exigindo-se, sempre, o prévio pagamento de indenização.</strong>.","banca":"UECE-CEV","ano":2006,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4264814,"enunciado":"Sobre a intervenção do Estado na propriedade, sob a modalidade de servidão administrativa, podemos afirmar, corretamente, que","opcoes":["a servidão administrativa tem natureza jurídica de direito pessoal.","a servidão administrativa tem como característica a auto-executoriedade.","a servidão administrativa não possui o caráter de definitividade.","a indenização, apesar de condicionada ao prejuízo, deve ser prévia."],"correta":3,"explicacao":"Gabarito: <strong>a indenização, apesar de condicionada ao prejuízo, deve ser prévia.</strong>.","banca":"UECE-CEV","ano":2006,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4264871,"enunciado":"Acerca do instituto da desapropriação, julgue os itens que se seguem.\n\nA imissão provisória na posse do imóvel não pode, em nenhuma hipótese, ocorrer antes da citação do expropriado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2006,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"E":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"}}},{"id":4264873,"enunciado":"Acerca do instituto da desapropriação, julgue os itens que se seguem.\n\nEm caso de se dar destinação não prevista inicialmente no decreto expropriatório ao bem expropriado,deve-se reconhecer a retrocessão,ainda que outra finalidade reconhecidamente pública tenha sido dada ao imóvel.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2006,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4265020,"enunciado":"Ao direito que tem o proprietário de exigir que na desapropriação se inclua a parte restante dos bens que se tornou inútil ou de difícil utilização por decorrência da expropriação, chama-se:","opcoes":["Direito de requisição.","Direito de extensão.","Direito de tredestinação.","Direito de retrocessão."],"correta":1,"explicacao":"Gabarito: <strong>Direito de extensão.</strong>.","banca":"MPM","ano":2005,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4265028,"enunciado":"Ao direito que tem o expropriado de reaver os bens não utilizados no interesse, necessidade ou utilidade públicos por que foram desapropriados, denomina-se:","opcoes":["Retrocessão.","Destinação imprópria.","Retrovenda.","Extensão."],"correta":0,"explicacao":"Gabarito: <strong>Retrocessão.</strong>.","banca":"MPM","ano":2005,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4316951,"enunciado":"O Instituto do Patrimônio Histórico e Artístico Nacional (IPHAN) instaurou processo de tombamento de determinado imóvel urbano de valor histórico. Após a notificação do proprietário, mas antes da inscrição definitiva no Livro do Tombo, o proprietário iniciou obra de demolição parcial do bem, alegando que o tombamento ainda não estava concluído. À luz do Decreto-Lei nº 25/1937, é correto afirmar que:","opcoes":["o proprietário pode realizar obras enquanto não houver decisão final;","as restrições só produzem efeitos após a inscrição definitiva no Livro do Tombo;","a demolição depende apenas de comunicação prévia ao órgão competente;","o bem, desde a notificação, fica sujeito provisoriamente às restrições do tombamento;","o tombamento provisório, existente após a notificação, tem duração máxima de 90 dias."],"correta":3,"explicacao":"Gabarito: <strong>o bem, desde a notificação, fica sujeito provisoriamente às restrições do tombamento;</strong>.","banca":"FGV","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"B":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"C":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"D":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"E":{"topico":"tombamento conceito","ancora":"tombamento-conceito"}}},{"id":4317072,"enunciado":"O Estado Alfa fez editar um decreto que declarou de utilidade pública, para fins de desapropriação, o imóvel de propriedade de Eufrásio, com vistas a construir um hospital público. Diante disso, Eufrásio está com fundadas dúvidas em relação à possibilidade de a desapropriação ser realizada por acordo, motivo pelo qual consultou assessoria jurídica em relação ao tema. Acerca da distinção entre desapropriação por acordo e desapropriação judicial, é correto afirmar que:","opcoes":["o acordo formalizado em âmbito administrativo com relação à desapropriação por utilidade pública depende da homologação judicial para que possa surtir seus regulares efeitos;","a utilização de meios alternativos de solução de controvérsias, tais como mediação e arbitragem, é vedada no âmbito da desapropriação por utilidade pública;","a quantia indenizatória na desapropriação por utilidade pública realizada por acordo deverá necessariamente abarcar os juros compensatórios, que compõem a justa e prévia indenização em dinheiro;","o adimplemento do montante que exceder eventual depósito prévio na ação judicial de desapropriação por utilidade pública, determinado na sentença, deverá ser realizado por meio de precatório, se o poder público estiver em dia com o seu pagamento;","a rejeição da oferta realizada administrativamente impõe que o poder público promova a desapropriação judicial, o que deve ser realizado no prazo máximo de dois anos, a contar da publicação do decreto que declarou a utilidade pública."],"correta":3,"explicacao":"Gabarito: <strong>o adimplemento do montante que exceder eventual depósito prévio na ação judicial de desapropriação por utilidade pública, determinado na sentença, deverá ser realizado por meio de precatório, se o poder público estiver em dia com o seu pagamento;</strong>.","banca":"FGV","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"B":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"C":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"D":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"E":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"}}},{"id":4317075,"enunciado":"As modalidades de desapropriação sancionatórias ou punitivas são compreendidas como aquelas em que o sacrifício da propriedade decorre do descumprimento de sua função social, o que, à luz das disposições constitucionais, surte efeitos na indenização. Acerca do tema, é correto afirmar que:","opcoes":["nenhuma das modalidades de desapropriação sancionatória pode ensejar o sacrifício do direito de propriedade sem o pagamento de indenização ao proprietário, em razão do princípio constitucional de vedação ao confisco;","os efeitos sobre a indenização, na hipótese de desapropriação sancionatória, são condizentes com a forma de pagamento, sendo certo que o montante a ser fixado, em qualquer caso, deve ser justo e incluir juros compensatórios;","a desapropriação por zona é considerada modalidade de desapropriação sancionatória, de modo que, em tal caso, a indenização não deve ser prévia e justa em dinheiro, pois o pagamento deverá ser efetuado por precatório;","o valor real da indenização no caso de desapropriação urbanística sancionatória deve ser em títulos da dívida pública aprovados pelo Senado Federal e deverá computar expectativas de ganhos e lucros cessantes relacionados ao imóvel;","a indenização no caso de desapropriação para fins de reforma agrária será mediante prévia e justa indenização em títulos da dívida agrária, com cláusula de preservação do valor real, resgatáveis no prazo de até vinte anos, a partir do segundo ano de sua emissão."],"correta":3,"explicacao":"Gabarito: <strong>o valor real da indenização no caso de desapropriação urbanística sancionatória deve ser em títulos da dívida pública aprovados pelo Senado Federal e deverá computar expectativas de ganhos e lucros cessantes relacionados ao imóvel;</strong>.","banca":"FGV","ano":2026,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"desapropriacao por zona","ancora":"desapropriacao-por-zona"},"E":{"topico":"desapropriacao por zona","ancora":"desapropriacao-por-zona"}}},{"id":4317123,"enunciado":"Sobre o Tombamento, é correto afirmar:","opcoes":["O processo de tombamento de bem pertencente a pessoa natural ou a pessoa jurídica de direito privado ou de direito público se fará a pedido do proprietário apenas.","O pedido de tombamento será dirigido ao presidente do Conselho Municipal do Patrimônio Cultural.","Caso decida pelo tombamento, o Conselho Municipal do Patrimônio Cultural dará publicidade ao Edital de Tombamento Definitivo e notificará o proprietário.","No caso de impugnação, o Conselho Municipal do Patrimônio Cultural terá o prazo de trinta dias contados do seu recebimento para apreciação e parecer, do qual não caberá recurso."],"correta":0,"explicacao":"Gabarito: <strong>O processo de tombamento de bem pertencente a pessoa natural ou a pessoa jurídica de direito privado ou de direito público se fará a pedido do proprietário apenas.</strong>.","banca":"Prefeitura de Bom Despacho - MG","ano":2025,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"B":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"C":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"D":{"topico":"tombamento conceito","ancora":"tombamento-conceito"}}},{"id":4317154,"enunciado":"O Estado Delta tombou, por meio de decreto, o prédio do teatro onde ocorreu a apresentação da primeira ópera no Brasil. Maria, proprietária do imóvel, pretendia vendê-lo para custear um tratamento de saúde. Diante do tombamento realizado, Maria continuou com a gestão do espaço cultural utilizado para importantes espetáculos. No entanto, Maria está suportando despesas excessivas, em razão de exigências do estado, para reparação e preservação do imóvel. Em relação ao referido caso, é correto afirmar que:","opcoes":["como se trata de uma espécie de limitação administrativa, que apenas restringe o uso do bem, não há indenização pela limitação imposta;","uma vez que Maria pretendia vender o imóvel, houve desapropriação indireta e a proprietária faz jus a indenização correspondente ao valor de mercado do bem tombado;","o tombamento é ato administrativo bilateral e deveria ter havido concordância expressa do proprietário para produzir efeitos, sob pena de violação à liberdade de propriedade, não cabendo a intervenção mediante decreto;","eventual indenização a Maria, decorrente de obras de reparação custosas exigidas pelo estado, não deve ocorrer, uma vez que a proprietária é remunerada anualmente pelo valor da outorga;","é imprescindível a anuência da Assembleia Legislativa do Estado Delta, e o ato expropriatório de intervenção em propriedade privada deve ser editado, mediante lei, em prol da livre inciativa."],"correta":0,"explicacao":"Gabarito: <strong>como se trata de uma espécie de limitação administrativa, que apenas restringe o uso do bem, não há indenização pela limitação imposta;</strong>.","banca":"FGV","ano":2025,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4317430,"enunciado":"O chefe do Poder Executivo de determinado ente federativo editou decreto promovendo a declaração de utilidade pública de certo imóvel urbano, objetivando a construção de uma escola. Frustradas as tentativas de desapropriação consensual, foi ajuizada a ação judicial de desapropriação em 1998. Ato contínuo, foi deferida a imissão provisória da posse após a realização do depósito prévio. Ao fim do processo expropriatório, que ocorreu no presente exercício, foi constatada divergência entre o valor inicialmente indicado pelo ente federativo e o valor real do imóvel expropriado. O expropriante, que possui uma elevada dívida pública e está em atraso com os seus precatórios, foi condenado a complementar o valor da indenização. Na situação descrita, o complemento da indenização:","opcoes":["deve ser realizado pelo regime geral de precatórios;","deve ser realizado via depósito judicial direto, a exemplo do que foi feito em relação ao depósito prévio;","deve seguir a regra geral que determina a sua realização em dinheiro, em razão da exigência de que a indenização seja prévia e justa;","deve ser realizado pelo regime especial de precatórios introduzido pela Emenda Constitucional nº 30/2000, sendo cabível o sequestro na hipótese de atraso no pagamento;","deve ser realizado pelo regime especial de precatórios introduzido pela Emenda Constitucional nº 62/2009, não sendo cabível o sequestro na hipótese de atraso no pagamento."],"correta":1,"explicacao":"Gabarito: <strong>deve ser realizado via depósito judicial direto, a exemplo do que foi feito em relação ao depósito prévio;</strong>.","banca":"FGV","ano":2025,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"E":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"}}},{"id":4317485,"enunciado":"A pessoa jurídica Sergipana Indústria e Comércio Ltda., usando de recursos financeiros próprios, adquiriu um terreno na cidade de Aracaju. Este mesmo foi invadido por um grupo de invasores profissionais, que posteriormente repartiram a área entre um grande número de pessoas carentes, que nele rapidamente fixaram residência. O estado de Sergipe, atento ao apelo político da situação, disponibilizou serviços públicos no local, como água, luz, asfalto, esgoto, postos de saúde e escola, obras estas realizadas em terreno de propriedade privada. O governador do estado decretou a desapropriação do imóvel por interesse social. Considerando essa situação hipotética, é correto afirmar que:","opcoes":["a existência de liminar impedindo a prática de atos tendentes a efetivar a desapropriação, inclusive a propositura da correspondente ação, não obsta o curso do prazo para a decadência do decreto expropriatório;","o expropriante tem o prazo de dois anos, a partir da decretação da desapropriação por interesse social, para efetivar a aludida desapropriação, independentemente da adoção de providências de aproveitamento do bem expropriado;","não enseja indenização a desapropriação direta não implementada em razão da caducidade do decreto expropriatório quando o ente expropriante não houver ultimado ato que implique a perda do domínio do bem pelo particular;","há responsabilidade do Estado quando este realizar serviços públicos de infraestrutura em gleba cuja invasão por terceiros apresenta situação consolidada e irreversível, ainda que não tenha concorrido para o desapossamento ocasionado exclusivamente por particulares;","ocorre desapossamento por parte do ente público ao realizar obras de infraestrutura em imóvel cuja invasão já se consolidara, pois a simples invasão de propriedade urbana por terceiros, mesmo sem ser repelida pelo poder público, constitui desapropriação indireta."],"correta":2,"explicacao":"Gabarito: <strong>não enseja indenização a desapropriação direta não implementada em razão da caducidade do decreto expropriatório quando o ente expropriante não houver ultimado ato que implique a perda do domínio do bem pelo particular;</strong>.","banca":"FGV","ano":2025,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"B":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"C":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"D":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"E":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"}}},{"id":4317582,"enunciado":"A Administração Pública direta e indireta de qualquer dos Poderes da União, dos estados, do Distrito Federal e dos municípios obedecerá aos princípios explícitos e implícitos da CF/88 e às demais normas infraconstitucionais. Em relação a esses princípios, assinale a alternativa que contém o princípio que permite ao Estado desapropriar bem particular por necessidade ou utilidade pública, ou por interesse social, mediante justa e prévia indenização em dinheiro.","opcoes":["Da segurança jurídica.","Da supremacia do interesse público sobre o particular.","Da irretroatividade.","Da impessoalidade.","Da publicidade."],"correta":1,"explicacao":"Gabarito: <strong>Da supremacia do interesse público sobre o particular.</strong>.","banca":"Instituto Avalia","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"distincao instrumentos intervencao","ancora":"distincao-instrumentos-intervencao"},"B":{"topico":"distincao instrumentos intervencao","ancora":"distincao-instrumentos-intervencao"},"C":{"topico":"distincao instrumentos intervencao","ancora":"distincao-instrumentos-intervencao"},"D":{"topico":"distincao instrumentos intervencao","ancora":"distincao-instrumentos-intervencao"},"E":{"topico":"distincao instrumentos intervencao","ancora":"distincao-instrumentos-intervencao"}}},{"id":4317658,"enunciado":"O prefeito do Município de Megalópolis questionou a respectiva assessoria jurídica acerca da existência de modalidades de intervenção do Estado na propriedade que não podem ser levadas a efeito por tal ente federativo no âmbito de seu território. Nesse contexto, a assessoria jurídica informou corretamente que é vedado aos Municípios","opcoes":["realizar a desapropriação por interesse social de propriedade privada situada na zona rural.","determinar o tombamento de bens públicos pertencentes outros entes federativos.","efetuar a ocupação temporária de terreno privado não edificado, vizinho à certa obra e necessário à sua realização;","instituir servidão administrativa sobre propriedade privada, para viabilizar a prestação de um serviço público de sua competência.","promover a requisição administrativa de bens públicos estaduais, ainda que caraterizada situação de iminente perigo público."],"correta":4,"explicacao":"Gabarito: <strong>promover a requisição administrativa de bens públicos estaduais, ainda que caraterizada situação de iminente perigo público.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao por zona","ancora":"desapropriacao-por-zona"},"B":{"topico":"desapropriacao por zona","ancora":"desapropriacao-por-zona"},"C":{"topico":"desapropriacao por zona","ancora":"desapropriacao-por-zona"},"D":{"topico":"desapropriacao por zona","ancora":"desapropriacao-por-zona"},"E":{"topico":"desapropriacao por zona","ancora":"desapropriacao-por-zona"}}},{"id":4317665,"enunciado":"Sobre a indenização e os consectários legais da desapropriação, é correto afirmar que:","opcoes":["os juros compensatórios são devidos nas ações de indenização por desapropriação indireta, abrangendo o período anterior à aquisição da propriedade ou da posse titulada pelo autor da ação;","os juros compensatórios incidem nas indenizações relativas às desapropriações que tiverem como pressuposto o descumprimento da função social da propriedade;","os juros compensatórios são devidos mesmo que a propriedade se mostre impassível de qualquer espécie de exploração econômica atual ou futura, em decorrência de limitações legais ou fáticas;","os honorários advocatícios sucumbenciais em desapropriação devem ser fixados por equidade quando a aplicação dos percentuais legais sobre a indenização tornar a verba excessiva;","a base de cálculo dos juros compensatórios em desapropriações corresponde à diferença entre 80% do preço ofertado pelo ente público e o valor fixado na sentença."],"correta":4,"explicacao":"Gabarito: <strong>a base de cálculo dos juros compensatórios em desapropriações corresponde à diferença entre 80% do preço ofertado pelo ente público e o valor fixado na sentença.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"B":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"C":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"D":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"},"E":{"topico":"juros compensatorios moratorios","ancora":"juros-compensatorios-moratorios"}}},{"id":4317722,"enunciado":"Imagine que um incêndio tenha atingido um dos prédios do Tribunal de Justiça, comprometendo as suas instalações, e o trabalho de funcionários e jurisdicionados, em razão do que se revela necessário o uso de uma propriedade privada para resguardar o acervo e promover o funcionamento das respectivas atividades, ainda que precariamente, em caráter temporário, tão-somente para debelar a situação de iminente perigo, diante do objetivo de retorno ao antigo edifício após as obras pertinentes. Considerando as modalidades de intervenção do Estado na propriedade é correto afirmar que tal situação deveria ensejar uma","opcoes":["servidão administrativa.","requisição administrativa.","limitação administrativa.","desapropriação confisco.","desapropriação por necessidade pública."],"correta":1,"explicacao":"Gabarito: <strong>requisição administrativa.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4317759,"enunciado":"O Instituto do Patrimônio Histórico e Artístico Nacional (IPHAN) notificou a sociedade empresária Alfa, estrangeira, que importou determinado bem para adornar um dos seus estabelecimentos, localizado no Município de Macaé, afirmando que a referida coisa preenche os requisitos necessários para ser parte integrante do patrimônio histórico e artístico nacional. Na mesma data, o IPHAN notificou o Município de Macaé, informando-o de que, por ordem do Diretor da referida autarquia federal, proceder-se-á ao tombamento de determinado bem pertencente à municipalidade. Nesse cenário, considerando o Decreto-Lei nº 25/1937, assinale a afirmativa correta.","opcoes":["Não é juridicamente cabível o tombamento do bem pertencente à sociedade empresária Alfa, por não integrar o patrimônio histórico e artístico nacional. Embora não se admita o tombamento compulsório do bem de propriedade do Município de Macaé, por ostentar natureza pública, nada impede que a medida se dê de forma voluntária, com a concordância da municipalidade.","É juridicamente cabível o tombamento compulsório do bem pertencente à sociedade empresária Alfa. Embora não se admita o tombamento compulsório do bem de propriedade do Município de Macaé, por ostentar natureza pública, nada impede que a medida se dê de forma voluntária, com a concordância da municipalidade.","É juridicamente cabível o tombamento compulsório do bem pertencente à sociedade empresária Alfa. Não se admite o tombamento, compulsório ou voluntário, do bem de propriedade do Município de Macaé, por ostentar natureza pública.","Não é juridicamente cabível o tombamento do bem pertencente à sociedade empresária Alfa, por não integrar o patrimônio histórico e artístico nacional. Admite-se o tombamento do bem de propriedade do Município de Macaé.","Não é juridicamente cabível tanto o tombamento do bem pertencente à sociedade empresária Alfa quanto o do Município de Macaé."],"correta":3,"explicacao":"Gabarito: <strong>Não é juridicamente cabível o tombamento do bem pertencente à sociedade empresária Alfa, por não integrar o patrimônio histórico e artístico nacional. Admite-se o tombamento do bem de propriedade do Município de Macaé.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"B":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"C":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"D":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"E":{"topico":"tombamento conceito","ancora":"tombamento-conceito"}}},{"id":4317765,"enunciado":"Para fins de desapropriação, o Município Y declarou de utilidade pública o terreno de José, tendo avaliado o imóvel em R$ 500.000,00. José não concordou com o valor da avaliação e, diante da impossibilidade de acordo, o Município Y propôs ação de desapropriação por utilidade pública contra José e obteve, liminarmente, a imissão provisória na posse, tendo efetuado o depósito de R$ 500.000,00. O pedido foi julgado procedente, tendo a indenização, devida pelo Município Y a José pela perda da propriedade, sido fixada em R$ 800.000,00, após a elaboração de laudo pericial e produção de outras provas. A sentença transitou em julgado. À luz da jurisprudência do STF, o pagamento da diferença entre o valor inicial e o valor final devido a José pelo Município Y deve ser efetuado por meio de:","opcoes":["precatório, se José não for vulnerável ou hipossuficiente;","depósito judicial direto, desde que as finanças do Município Y suportem a despesa;","precatório, independentemente da situação financeira do Município Y;","depósito judicial direto, se José for vulnerável ou hipossuficiente;","depósito judicial direto, se o Município Y não estiver pagando em dia seus precatórios."],"correta":4,"explicacao":"Gabarito: <strong>depósito judicial direto, se o Município Y não estiver pagando em dia seus precatórios.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"stf tema 831 precatorios","ancora":"stf-tema-831-precatorios"},"B":{"topico":"stf tema 831 precatorios","ancora":"stf-tema-831-precatorios"},"C":{"topico":"stf tema 831 precatorios","ancora":"stf-tema-831-precatorios"},"D":{"topico":"stf tema 831 precatorios","ancora":"stf-tema-831-precatorios"},"E":{"topico":"stf tema 831 precatorios","ancora":"stf-tema-831-precatorios"}}},{"id":4317767,"enunciado":"João, proprietário de uma casa situada no centro do Município Alfa, que se encontrava desocupada, foi informado de que esse imóvel foi objeto de declaração de desapropriação por motivo de utilidade pública, de modo que fosse ali construída uma escola pública, visando a atender alunos da educação fundamental. Também tomou conhecimento de que a avaliação realizada se encontrava muito aquém dos padrões que, a seu ver, eram praticados pelo mercado. Preocupado com a forma como seria indenizado, João consultou a legislação de regência, tendo concluído, corretamente, que a Administração Pública deve:","opcoes":["realizar o depósito em títulos da dívida pública, tanto para a imissão provisória na posse quanto após a definição do valor definitivo do imóvel;","realizar o depósito em dinheiro, considerando a avaliação judicial, tanto para a imissão provisória na posse quanto para a transmissão definitiva da propriedade;","realizar o depósito em dinheiro, tanto para fins de imissão provisória na posse, com base na avaliação que realizou, quanto após a definição do valor definitivo do imóvel em decisão judicial;","promover a expedição de precatório, tanto para fins de imissão provisória na posse, com base na avaliação que realizou, quanto após a definição do valor definitivo do imóvel em decisão judicial;","realizar o depósito em dinheiro, para fins de imissão provisória na posse, com base na avaliação que realizou, sendo expedido precatório em relação ao complemento, após a definição do valor definitivo do imóvel em decisão judicial."],"correta":4,"explicacao":"Gabarito: <strong>realizar o depósito em dinheiro, para fins de imissão provisória na posse, com base na avaliação que realizou, sendo expedido precatório em relação ao complemento, após a definição do valor definitivo do imóvel em decisão judicial.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"B":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"C":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"D":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"E":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"}}},{"id":4317769,"enunciado":"Ao estudar direito administrativo para concurso público, Elizabeth verificou que a doutrina administrativista distingue o ato administrativo do fato administrativo, de modo que concluiu, corretamente, que é exemplo desse último","opcoes":["a sanção de demissão.","a multa administrativa.","a licença profissional.","o Decreto editado para a fiel execução da lei.","a desapropriação indireta."],"correta":4,"explicacao":"Gabarito: <strong>a desapropriação indireta.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4317787,"enunciado":"Dentre as modalidades de intervenção do Estado na propriedade, existe aquela que, em princípio, é restritiva, mas que pode se tornar supressiva, quando ocorre o perecimento do bem que dela tenha sido objeto, a ser indenizado, portanto posteriormente. É correto afirmar que tal modalidade de intervenção, que tem lugar nas situações que envolvem iminente perigo público, corresponde à","opcoes":["limitação administrativa.","ocupação provisória.","requisição administrativa.","servidão administrativa.","desapropriação."],"correta":2,"explicacao":"Gabarito: <strong>requisição administrativa.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4317822,"enunciado":"No território do município Alfa, os órgãos competentes do Poder Executivo adotaram diversas medidas para minimizar os efeitos de uma tempestade que ocorrerá nos próximos dias, com risco iminente de causar uma enchente, conforme fora detectado pelos órgãos técnicos competentes. Entre as medidas adotadas, está a ocupação temporária de um dos imóveis de Maria, sem a sua autorização prévia, para ali estruturar uma base de operações. Irresignada com o teor dessa medida, Maria consulta um especialista em relação à sua conformidade constitucional, sendo-lhe corretamente esclarecido que:","opcoes":["a situação configura uma desapropriação indireta, de modo que Maria deve postular judicialmente a respectiva indenização;","a ausência de prévia autorização judicial, de modo a imitir o município Alfa na posse do imóvel de Maria, evidencia a ilicitude da ocupação;","a ocupação, independente de justa e prévia indenização em dinheiro, foi lícita, mas deve ser assegurada a Maria a indenização posterior, caso haja dano;","a ocupação somente seria lícita se tivesse sido antecedida de depósito administrativo, para fins de garantia de possíveis danos que venham a ser causados ao imóvel;","a ocupação é legítima, não havendo que se falar em indenização por eventuais danos em razão da preeminência do interesse público sobre o particular, ao que se soma o dever de solidariedade social."],"correta":2,"explicacao":"Gabarito: <strong>a ocupação, independente de justa e prévia indenização em dinheiro, foi lícita, mas deve ser assegurada a Maria a indenização posterior, caso haja dano;</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4318159,"enunciado":"Ao estudar as modalidades de intervenção do Estado na propriedade à luz da jurisprudência do Supremo Tribunal Federal, Juliano verificou que a Corte Superior tem o entendimento de que NÃO pode recair sobre bens públicos:","opcoes":["tombamento;","desapropriação;","ocupação temporária;","limitação administrativa;","requisição administrativa."],"correta":4,"explicacao":"Gabarito: <strong>requisição administrativa.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"B":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"C":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"D":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"E":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"}}},{"id":4318165,"enunciado":"Em decorrência de suas peculiaridades, algumas modalidades de intervenção do Estado na propriedade são dotadas de autoexecutoriedade, em especial aquela em que a premência na adoção de determinada conduta é imposta por perigo iminente, em razão do que eventual indenização será ulterior, se houver dano, hipótese em que, inclusive, poderá ocorrer a supressão da propriedade, no caso de perecimento do bem. Nesse contexto, assinale a opção que indica a modalidade de intervenção do Estado na propriedade que apresenta tais características.","opcoes":["A desapropriação por necessidade pública.","A requisição administrativa.","O tombamento.","A limitação administrativa.","A servidão administrativa."],"correta":1,"explicacao":"Gabarito: <strong>A requisição administrativa.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4318179,"enunciado":"Imagine que determinado Município, após o devido processo legal, promoveu a desapropriação de certo imóvel para a construção de um hospital, mas, em lugar disso, utilizou-se do bem para finalidade que viola o interesse público, de modo a restar caracterizada uma tredestinação ilícita. Tal situação hipotética daria ensejo ao que costuma ser designado de:","opcoes":["retrocessão;","direito de extensão;","cláusula de retomada;","desapropriação indireta;","manutenção do status quo."],"correta":0,"explicacao":"Gabarito: <strong>retrocessão;</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4318279,"enunciado":"Há cerca de sete anos, determinado Estado da Federação fez editar uma lei que, após os devidos trâmites, regularmente criou uma unidade de conservação ambiental, de uso sustentável, que pode ser instituída sobre bens privados. Tal norma atingiu diversos imóveis situados na área delimitada, entre os quais o de Rosana, que acredita que deve ser indenizada em decorrência de tal conduta do ente federativo, diante do esvaziamento do conteúdo econômico de sua propriedade, mas ainda não ajuizou a demanda pertinente. Diante dessa situação hipotética, considerando a jurisprudência do Superior Tribunal de Justiça, é correto afirmar que a modalidade de intervenção do Estado na propriedade que deve respaldar a pretensão de Rosana é a","opcoes":["desapropriação indireta, cujo prazo prescricional é de vinte anos.","limitação administrativa, cujo prazo prescricional é de dez anos.","desapropriação por interesse social, cujo prazo prescricional é de dois anos.","limitação administrativa, cujo prazo prescricional é de cinco anos.","desapropriação indireta, cujo prazo prescricional, em regra, é de quinze anos."],"correta":3,"explicacao":"Gabarito: <strong>limitação administrativa, cujo prazo prescricional é de cinco anos.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4318313,"enunciado":"O Município Alfa almeja desapropriar por utilidade pública, para fins de construir um hospital, o bem de propriedade da sociedade empresária Delta, no qual ela desenvolve a sua atividade empresarial. Acerca dessa situação hipotética, à luz do disposto na legislação de regência e da jurisprudência dos Tribunais Superiores, é correto afirmar que","opcoes":["o procedimento da desapropriação não pode se exaurir na esfera administrativa, ainda que haja acordo entre as partes.","a justa indenização não pode envolver o fundo de comércio da sociedade empresária Delta, na medida em que deve abarcar apenas as construções existentes na localidade.","caso o Município Alfa construa uma escola no bem desapropriado, restará caracterizada a tredestinação ilícita, que dá ensejo à retrocessão.","o Município Alfa não precisa realizar depósito prévio para fins de obter a liminar na imissão provisória da posse, no curso da respectiva ação de desapropriação.","se for necessária a complementação da indenização ao final do processo de desapropriação, deverá o pagamento ser feito mediante depósito judicial direto se o Município Alfa não estiver em dia com os precatórios."],"correta":4,"explicacao":"Gabarito: <strong>se for necessária a complementação da indenização ao final do processo de desapropriação, deverá o pagamento ser feito mediante depósito judicial direto se o Município Alfa não estiver em dia com os precatórios.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"stf tema 831 precatorios","ancora":"stf-tema-831-precatorios"},"B":{"topico":"stf tema 831 precatorios","ancora":"stf-tema-831-precatorios"},"C":{"topico":"stf tema 831 precatorios","ancora":"stf-tema-831-precatorios"},"D":{"topico":"stf tema 831 precatorios","ancora":"stf-tema-831-precatorios"},"E":{"topico":"stf tema 831 precatorios","ancora":"stf-tema-831-precatorios"}}},{"id":4318319,"enunciado":"Após os devidos trâmites administrativos, o Município Alfa ajuizou ação de desapropriação por utilidade pública para fins de construir uma ponte, que tem por objeto o imóvel de Matilde. Houve a regular imissão provisória na posse e o ente federativo demoliu a casa em que ela morava, construída no mencionado terreno, para a realização da obra. Posteriormente, verificou-se a existência de um erro no respectivo projeto, de modo que o imóvel em questão, na realidade, não é necessário para o fim almejado, razão pela qual o ente federativo pretende desistir da desapropriação Considerando que Matilde promoveu o levantamento dos valores previamente depositados em Juízo para a imissão provisória na posse e que ainda não há sentença nos respectivos autos, à luz da jurisprudência do Superior Tribunal de Justiça, é correto afirmar que o Município","opcoes":["não poderá desistir da desapropriação, diante do ajuizamento da respectiva demanda.","poderá desistir da desapropriação em questão, na medida em que ainda não ocorreu o trânsito em julgado.","não poderá desistir da desapropriação, em decorrência da alteração substancial do bem de Matilde, que compromete a sua utilização como antes do processo desapropriatório.","poderá desistir da desapropriação a qualquer tempo, mesmo após o pagamento integral do preço, diante do interesse público subjacente.","não poderá desistir da desapropriação, considerando que Matilde promoveu o levantamento do depósito prévio."],"correta":2,"explicacao":"Gabarito: <strong>não poderá desistir da desapropriação, em decorrência da alteração substancial do bem de Matilde, que compromete a sua utilização como antes do processo desapropriatório.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desistencia desapropriacao","ancora":"desistencia-desapropriacao"},"B":{"topico":"desistencia desapropriacao","ancora":"desistencia-desapropriacao"},"C":{"topico":"desistencia desapropriacao","ancora":"desistencia-desapropriacao"},"D":{"topico":"desistencia desapropriacao","ancora":"desistencia-desapropriacao"},"E":{"topico":"desistencia desapropriacao","ancora":"desistencia-desapropriacao"}}},{"id":4318467,"enunciado":"O Estado Alfa ajuizou ação de desapropriação em face de Regina, casada sob o regime de comunhão parcial de bens com João, fundado em decreto que declarou porção do terreno de propriedade desta como de utilidade pública para fins de desapropriação. Outrossim, o ente federativo requereu a imissão prévia na posse do imóvel, sustentando ter urgência em iniciar obras para a construção de rodovia na região, a qual cruzaria parcela significativa da propriedade. Porém, passados mais de 120 (cento e vinte) dias da alegação de urgência, o Estado não efetuou o depósito do preço oferecido. Regularmente citada, Regina, em defesa, sustentou que o valor da avaliação do imóvel, a qual instruiu a petição inicial e fora realizado na fase administrativa da desapropriação, é significativamente inferior ao valor real da propriedade. Pugnou, ainda, pela extensão da desapropriação para todo o terreno, eis que a parcela não englobada pelo decreto expropriatório teria sua utilidade econômica esvaziada. Finda a fase instrutória, o juiz julgou parcialmente procedente o pedido, fixando o valor da indenização devida a Regina em R$ 2.000.000,00 (dois milhões de reais), o qual equivale ao dobro do valor da avaliação realizada pelo Poder Executivo e que instruiu a petição inicial. Inconformado, o Estado interpôs recurso de apelação em face da sentença, o qual está pendente de julgamento, pugnando pela redução do valor da indenização para o montante de R$ 1.000.000,00 (um milhão de reais). Tomando o caso acima como premissa, assinale a afirmativa correta.","opcoes":["O Estado poderá desistir da ação de desapropriação no atual momento processual, sendo ônus de Regina provar a existência de fato impeditivo do direito de desistência.","O direito de extensão alegado por Regina em defesa não é cabível em sede de ação de desapropriação, o qual deve ser exercido por meio de ação própria.","Em razão do regime de bens de Regina, sua citação não dispensaria a de cônjuge João, havendo, assim, litisconsórcio passivo necessário, o qual não foi respeitado.","O Estado poderá renovar a alegação de urgência para fins de pedido de imissão provisória na posse, desde que comprove a insuficiência de recursos para promover o depósito do valor da indenização.","Os honorários advocatícios deverão ser fixados entre 10% a 20% do valor total da indenização devida à Regina, não podendo exceder R$ 151.000,00 (cento e cinquenta e um mil reais)."],"correta":2,"explicacao":"Gabarito: <strong>Em razão do regime de bens de Regina, sua citação não dispensaria a de cônjuge João, havendo, assim, litisconsórcio passivo necessário, o qual não foi respeitado.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"direito extensao","ancora":"direito-extensao"},"B":{"topico":"direito extensao","ancora":"direito-extensao"},"C":{"topico":"direito extensao","ancora":"direito-extensao"},"D":{"topico":"direito extensao","ancora":"direito-extensao"},"E":{"topico":"direito extensao","ancora":"direito-extensao"}}},{"id":4318486,"enunciado":"O Palácio da Liberdade, o Museu Escola Alfredo Andersen e o Palacete do Batel são exemplos de bens tombados situados na Cidade de Curitiba. Sobre o tombamento, é correto afirmar que:","opcoes":["em face da alienação onerosa de bens tombados, pertencentes a pessoas naturais ou a pessoas jurídicas de direito privado, a União, os Estados, o Distrito Federal e os Municípios terão, nesta ordem, o direito de preferência;","nenhuma venda judicial se poderá realizar sem que, previamente, os titulares do direito de preferência sejam disso notificados judicialmente, não podendo os editais de praça ser expedidos, sob pena de nulidade, antes de feita a notificação;","patrimônio histórico e artístico nacional é o conjunto dos bens móveis e imóveis existentes no país e cuja conservação seja de interesse público, por sua vinculação a fatos memoráveis da história do Brasil ou por seu excepcional valor arqueológico ou etnográfico, bibliográfico ou artístico;","não estão sujeitos a tombamento os monumentos naturais, bem como os sítios e paisagens que tenham sido alterados pela natureza ou agenciados pela indústria humana, assim como os bens públicos dominiais, especiais ou de uso comum;","negociantes de antiguidades, de obras de arte de qualquer natureza, de manuscritos e livros antigos ou raros são obrigados a um registro especial no Serviço do Patrimônio Histórico e Artístico Nacional, devendo apresentar relatório anual de suas atividades."],"correta":4,"explicacao":"Gabarito: <strong>negociantes de antiguidades, de obras de arte de qualquer natureza, de manuscritos e livros antigos ou raros são obrigados a um registro especial no Serviço do Patrimônio Histórico e Artístico Nacional, devendo apresentar relatório anual de suas atividades.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"B":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"C":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"D":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"},"E":{"topico":"regime bens publicos","ancora":"regime-bens-publicos"}}},{"id":4318620,"enunciado":"A União, por meio do Departamento Nacional de Infraestrutura de Transportes (DNIT), na busca da ampliação da malha viária, para promover o desenvolvimento social e econômico e a melhor integração entre duas regiões do país, pretende desapropriar propriedade particular. Sobre os procedimentos a serem adotados pela autarquia, é correto afirmar que:","opcoes":["a segunda fase do procedimento de desapropriação (fase executória) é sempre judicial pela necessidade de controle do valor da indenização que deve ser prévia, justa e em dinheiro;","é cabível a imissão provisória na posse, caso requerida em até 120 dias da alegação de urgência e mediante o depósito da quantia fixada segundo o critério previsto em lei;","tem-se na hipótese uma desapropriação por necessidade pública, com a final transferência do bem de propriedade do particular para o poder público;","não incidem honorários advocatícios de sucumbência na ação de desapropriação dada a natureza dessa demanda judicial;","proposta a ação de desapropriação, é cabível a imissão provisória na posse pelo DNIT, após a avaliação judicial do imóvel a ser expropriado."],"correta":0,"explicacao":"Gabarito: <strong>a segunda fase do procedimento de desapropriação (fase executória) é sempre judicial pela necessidade de controle do valor da indenização que deve ser prévia, justa e em dinheiro;</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"},"B":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"},"C":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"},"D":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"},"E":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"}}},{"id":4318623,"enunciado":"A União se apropriou do imóvel de Humberto no ano de 2012, sem observar as formalidades previstas em lel para a desapropriação, e nele imediatamente construiu um prédio que até hoje é sede de diversos órgãos públicos federais. Como já era aposentado e costumava viajar constantemente para o exterior, Humberto decidiu ajuizar ação indenizatória por desapropriação indireta somente agora no ano de 2023. O Juízo Federal, observando a atual jurisprudência do Superior Tribunal de Justiça em tema de recurso repetitivo, decidiu que:","opcoes":["já ocorreu a prescrição da pretensão de Humberto, pois se aplica o prazo de dez anos da usucapião extraordinária do Código Civil;","não ocorreu a prescrição da pretensão de Humberto, pois se aplica o prazo de quinze anos da usucapião ordinária do Código Civil;","não ocorreu a prescrição da pretensão de Humberto, pois se aplica o prazo de vinte anos da usucapião extraordinária do Código Civil;","já ocorreu a prescrição da pretensão de Humberto, pois se aplica o prazo quinquenal de dívidas passivas de entes públicos previsto no Decreto nº 20.910/1932;","não ocorreu a prescrição da pretensão de Humberto, pois é imprescritível o ressarcimento ao particular de atos dolosos do poder público, sob pena de locupletamento ilícito da União."],"correta":2,"explicacao":"Gabarito: <strong>não ocorreu a prescrição da pretensão de Humberto, pois se aplica o prazo de vinte anos da usucapião extraordinária do Código Civil;</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4318643,"enunciado":"João, policial militar, ao observar a fuga de dois assaltantes que acabaram de roubar um comércio local, parou o veículo de Maria, aposentada, determinando que ela se retirasse do veículo para que ele pudesse perseguir os ladrões. Nesse caso, considerando o tema da intervenção do Estado na propriedade, é correto afirmar que o agente público fez uso do instituto","opcoes":["da requisição administrativa.","da desapropriação indireta.","da limitação administrativa.","da ocupação temporária.","do empréstimo compulsório."],"correta":0,"explicacao":"Gabarito: <strong>da requisição administrativa.</strong>.","banca":"INSTITUTO AOCP","ano":2023,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4318791,"enunciado":"Para atender um clamor da população, com vistas a proteger o patrimônio histórico e artístico local, o Município Utopia fez publicar uma lei que determinou o tombamento de alguns prédios considerados marcos de um renomado de arquiteto nascido na localidade, devidamente especificados na norma. Dentre os aludidos bens, existe um que é de propriedade do Estado Utopia. Diante dessa situação hipotética, à luz da jurisprudência do Supremo Tribunal Federal, é correto afirmar que o aludido tombamento:","opcoes":["não pode ser realizado por lei, pois exige a ampla defesa e o contraditório para a sua perfectibilização;","não poderia abarcar bem do Estado Utopia, na medida em que os entes menores não podem tombar bens de entes maiores;","não pode ser realizado pelo Município Utopia, pois a competência para determinar tal modalidade de intervenção do Estado na propriedade é exclusiva da União;","está perfectibilizado pela determinação do Poder Legislativo no sentido de realizar tal modalidade de intervenção do Estado na propriedade;","poderia ter seu procedimento iniciado pela mencionada lei, que será considerada de efeitos concretos para fins de dar prosseguimento à ampla defesa e ao contraditório necessários para a perfectibilização de tal intervenção do Estado na propriedade."],"correta":2,"explicacao":"Gabarito: <strong>não pode ser realizado pelo Município Utopia, pois a competência para determinar tal modalidade de intervenção do Estado na propriedade é exclusiva da União;</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"B":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"C":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"D":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"E":{"topico":"tombamento conceito","ancora":"tombamento-conceito"}}},{"id":4318837,"enunciado":"O Estado Beta, em caso de comprovado iminente perigo público, consistente em alagamento decorrente de fortes e extraordinárias chuvas, por meio de sua autoridade competente, pretende fazer uso da requisição administrativa de bem imóvel da União, assegurando-lhe indenização ulterior, se houver dano. Com base no texto constitucional e na jurisprudência do Supremo Tribunal Federal, a pretensão do Estado Beta é","opcoes":["viável, diante da narrada situação de emergência pública, mas a indenização deve ser prévia, mediante acordo com a União ou depósito judicial.","viável, diante da narrada situação de emergência pública, desde que haja prévia decisão judicial e depósito em juízo do valor inicialmente estimado para indenização, diante da determinação constitucional de reserva de jurisdição.","inviável, pois ofende o princípio federativo a requisição de bens de um ente federativo por outro, o que somente se admitiria à União, de forma excepcional, durante a vigência das medidas excepcionais de estado de defesa e estado de sítio","viável, diante da narrada situação de emergência pública, mas a indenização ulterior deve ocorrer independentemente de haver dano ao imóvel e deve ser calculada com base no tempo de utilização do bem da União.","inviável, pois, no tocante aos entes federativos, suas relações se caracterizam pela cooperação e pela horizontalidade, não se admitindo a ente federativo requisitar bem pertencente a outro, sob pena de ferimento da autonomia desse ente e, consequentemente, ofensa ao pacto federativo, mas é possível no caso a requisição administração de serviço público, desde que demonstrada situação de perigo público iminente."],"correta":2,"explicacao":"Gabarito: <strong>inviável, pois ofende o princípio federativo a requisição de bens de um ente federativo por outro, o que somente se admitiria à União, de forma excepcional, durante a vigência das medidas excepcionais de estado de defesa e estado de sítio</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"B":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"C":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"D":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"E":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"}}},{"id":4318863,"enunciado":"Com relação à desapropriação, assinale a alternativa correta.","opcoes":["A desapropriação indireta decorre de ato lícito da Administração, que impõe limitações sobre determinado bem e impede que o proprietário exerça poderes inerentes ao domínio.","O pagamento de indenização na desapropriação por necessidade pública pode ser feito em títulos da dívida pública.","A chamada desapropriação indireta decorre de ato ilícito indenizável praticado pela Administração Pública contra o proprietário ou possuidor.","O texto constitucional prevê a expropriação de glebas que contenham cultura ilegal de plantas psicotrópicas, hipótese em que o pagamento da indenização é feito em títulos da dívida pública.","Segundo doutrina majoritária, a desapropriação por utilidade pública é forma derivada de aquisição da propriedade."],"correta":4,"explicacao":"Gabarito: <strong>Segundo doutrina majoritária, a desapropriação por utilidade pública é forma derivada de aquisição da propriedade.</strong>.","banca":"Quadrix","ano":2023,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4319037,"enunciado":"Com objetivo de executar políticas públicas de preservação do meio ambiente, em especial na área de saneamento básico, o Estado Alfa promoveu a desapropriação do imóvel de João, com finalidade específica de construir no local uma estação de tratamento de esgoto. Ocorre que, após a execução do ato expropriatório, para atender ao interesse coletivo devidamente justificado, o Estado Alfa construiu no local um aterro sanitário municipal para destinação final de resíduos sólidos, alterando a destinação do bem. No caso em tela, de acordo com a doutrina de Direito Administrativo, ocorreu a chamada","opcoes":["adestinação.","tredestinação lícita.","retrocessão por desvio de finalidade ilícito.","tredestinação ilícita.","retrocessão por motivação lícita."],"correta":1,"explicacao":"Gabarito: <strong>tredestinação lícita.</strong>.","banca":"FGV","ano":2022,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4319105,"enunciado":"O Município Alfa, para fins de instalação de poste para viabilizar o serviço de iluminação pública, utilizou, com base no poder de polícia, uma parcela do terreno privado de propriedade de Marcelo. No caso em tela, o poder público municipal fez uso da intervenção do Estado na propriedade denominada","opcoes":["requisição administrativa.","servidão administrativa.","limitação administrativa.","desapropriação indireta.","tombamento."],"correta":1,"explicacao":"Gabarito: <strong>servidão administrativa.</strong>.","banca":"FGV","ano":2022,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4319129,"enunciado":"Ademar é proprietário de um imóvel na cidade de Palmas/TO situado em área abrangida por projeto de construção de uma rodovia estadual. O referido imóvel, então, foi declarado de utilidade pública por decreto do governador do Estado. Nessa situação, pretendendo o poder público desapropriar o imóvel, é correto afirmar que:","opcoes":["Ademar e o Estado poderão submeter a controvérsia à mediação, desde que eleita uma câmara de mediação criada pelo poder público, sendo vedada a arbitragem;","Ademar e o Estado poderão submeter a controvérsia à mediação ou à via arbitral, devendo Ademar indicar um dos órgãos ou instituições especializados em mediação ou arbitragem previamente cadastrados pelo órgão responsável pela desapropriação;","antes de ajuizar a ação de desapropriação, o Estado tem o dever de notificar Ademar e apresentar-lhe oferta de indenização, depositando desde logo em seu favor o valor da oferta;","Ademar e o Estado poderão submeter a controvérsia à mediação, devendo Ademar indicar um dos órgãos ou instituições especializados em mediação previamente cadastrados pelo órgão responsável pela desapropriação, sendo vedada a arbitragem;","é obrigatório o ajuizamento da ação de desapropriação, sendo vedada a utilização dos meios alternativos de resolução de controvérsias em vista da indisponibilidade do interesse público."],"correta":1,"explicacao":"Gabarito: <strong>Ademar e o Estado poderão submeter a controvérsia à mediação ou à via arbitral, devendo Ademar indicar um dos órgãos ou instituições especializados em mediação ou arbitragem previamente cadastrados pelo órgão responsável pela desapropriação;</strong>.","banca":"FGV","ano":2022,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"notificacao oferta indenizacao","ancora":"notificacao-oferta-indenizacao"},"B":{"topico":"notificacao oferta indenizacao","ancora":"notificacao-oferta-indenizacao"},"C":{"topico":"notificacao oferta indenizacao","ancora":"notificacao-oferta-indenizacao"},"D":{"topico":"notificacao oferta indenizacao","ancora":"notificacao-oferta-indenizacao"},"E":{"topico":"notificacao oferta indenizacao","ancora":"notificacao-oferta-indenizacao"}}},{"id":4319217,"enunciado":"O Município Beta, pretendendo construir uma escola no imóvel de Maria, editou decreto que declarou o imóvel como de utilidade pública. Em seguida, o Município ajuizou ação de desapropriação, sem requerer a imissão provisória na posse do imóvel. No curso do processo judicial, o Município decidiu construir a escola em outro imóvel que já era de sua propriedade, de maneira que revogou o decreto de utilidade pública e requereu a extinção do processo de desapropriação, pela desistência. No caso em tela, adotando a jurisprudência atual do Superior Tribunal de Justiça, o magistrado deve extinguir o feito, homologando a desistência:","opcoes":["sem condenação do Município Beta em honorários advocatícios sucumbenciais, diante da ausência de prejuízo a Maria, uma vez que não houve imissão na posse;","sem condenação do Município Beta em honorários advocatícios sucumbenciais, diante da ausência de má-fé e do atendimento ao interesse público na extinção do processo;","com condenação do Município Beta em honorários advocatícios sucumbenciais, com valor calculado com base nos parâmetros do Código de Processo Civil entre o mínimo de 10% e o máximo de 20% sobre o valor atualizado da causa;","com condenação do Município Beta em honorários advocatícios sucumbenciais, com valor calculado levando em consideração os limites da Lei das Desapropriações entre 0,5% e 5% incidentes sobre o valor atualizado da causa;","com condenação do Município Beta em honorários advocatícios sucumbenciais, com valor calculado com base no princípio da proporcionalidade e observado o limite máximo de vinte salários mínimos, para evitar o enriquecimento ilícito de Maria."],"correta":3,"explicacao":"Gabarito: <strong>com condenação do Município Beta em honorários advocatícios sucumbenciais, com valor calculado levando em consideração os limites da Lei das Desapropriações entre 0,5% e 5% incidentes sobre o valor atualizado da causa;</strong>.","banca":"FGV","ano":2022,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"B":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"C":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"D":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"E":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"}}},{"id":4319593,"enunciado":"João foi notificado pelo Poder Executivo do Município Alfa, tomando conhecimento de que, após um amplo processo de seleção, o seu imóvel fora escolhido para sediar uma escola pública. Nesse caso, para que a decisão do Poder Executivo possa se tornar efetiva, é necessário que João, observados os balizamentos legais","opcoes":["receba justa e prévia indenização em dinheiro.","celebre contrato de compra e venda com o Município.","receba justa indenização ao fim do processo de desapropriação.","indique o preço do imóvel, de modo que possa ser indenizado pelo Município Alfa.","defina o valor do imóvel juntamente com o Município, valendo-se de mecanismos de solução não contenciosa."],"correta":0,"explicacao":"Gabarito: <strong>receba justa e prévia indenização em dinheiro.</strong>.","banca":"FGV","ano":2022,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4319640,"enunciado":"Com relação à requisição administrativa de leitos, medicamentos e insumos, feita pelo Poder Público, em razão de pandemia por COVID-19, assinale a afirmativa correta.","opcoes":["Constitui limitação constitucional à propriedade privada, através de ato de império do Poder Público, bastando a demonstração da necessidade e do perigo público iminente.","Na requisição administrativa será garantida a indenização prévia do dano ao particular.","Além do aspecto legal, o Poder Judiciário pode acrescentar outras medidas políticas que entende cabíveis, a serem adotadas na requisição, além daquelas estabelecidas pelo Executivo.","Não cabe ao Poder Judiciário a fixação do valor da indenização, que deve ser estabelecida posteriormente ao ato de intervenção na propriedade privada."],"correta":0,"explicacao":"Gabarito: <strong>Constitui limitação constitucional à propriedade privada, através de ato de império do Poder Público, bastando a demonstração da necessidade e do perigo público iminente.</strong>.","banca":"FGV","ano":2022,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"B":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"C":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"D":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"}}},{"id":4319641,"enunciado":"O poder público necessitando, com urgência, construir um anel viário ingressou em imóvel alheio vazio e passou a praticar a terraplanagem do terreno. Assinale a opção que indica a ação adequada que o proprietário do imóvel pode mover em face do poder público.","opcoes":["Ação de reintegração de posse, pois o esbulho equivale à própria perda da posse sobre o bem.","Ação de manutenção de posse, porque a turbação por atos da administração pública equivale à perda total da posse.","Ação de desapropriação indireta, pois o poder público já ingressou no imóvel e pratica atos de dono da área.","Ação de desapropriação, porque o proprietário, no futuro, poderá perder o título de propriedade do imóvel, sem indenização."],"correta":2,"explicacao":"Gabarito: <strong>Ação de desapropriação indireta, pois o poder público já ingressou no imóvel e pratica atos de dono da área.</strong>.","banca":"FGV","ano":2022,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4319658,"enunciado":"O Município Alfa invadiu o imóvel de propriedade de José, de forma irregular e ilícita, sem respeitar os procedimentos administrativos e judiciais inerentes à desapropriação, e iniciou a construção de uma escola municipal. José estava internado por longo período em tratamento de doença grave e, ao retornar para seu imóvel, verificou que a escola já tinha iniciado suas atividades. Ao buscar assistência jurídica na Defensoria Pública, José foi informado de que, de acordo com a jurisprudência do Superior Tribunal de Justiça, é cabível o ajuizamento de ação de:","opcoes":["reintegração de posse, cujo prazo prescricional é de cinco anos;","reintegração de posse, cujo prazo prescricional é de quinze anos;","indenização por desapropriação indireta, cujo prazo prescricional é de dez anos;","indenização por desapropriação indireta, cujo prazo prescricional é de vinte anos."],"correta":2,"explicacao":"Gabarito: <strong>indenização por desapropriação indireta, cujo prazo prescricional é de dez anos;</strong>.","banca":"FGV","ano":2022,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4319708,"enunciado":"No Município Gama ocorreu grave enchente que fez com que muitas famílias ficassem desabrigadas. O Prefeito municipal, diante do iminente perigo público, determinou a imediata utilização de um galpão abandonado, de propriedade de João, para assentar as famílias atingidas, até a solução definitiva. No caso narrado, ocorreu a intervenção do Estado na propriedade chamada","opcoes":["servidão administrativa, assegurada a João prévia e justa indenização;","ocupação temporária, assegurada a João prévia e justa indenização;","limitação administrativa, assegurada a João indenização ulterior, se houver dano;","requisição administrativa, assegurada a João indenização ulterior, se houver dano;","desapropriação temporária, assegurada a João indenização ulterior."],"correta":3,"explicacao":"Gabarito: <strong>requisição administrativa, assegurada a João indenização ulterior, se houver dano;</strong>.","banca":"FGV","ano":2021,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4319841,"enunciado":"No caso de iminente perigo público, o Estado poderá desapropriar imóvel privado, desde que pague justa e prévia indenização em dinheiro.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"C":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"},"E":{"topico":"requisicao administrativa","ancora":"requisicao-administrativa"}}},{"id":4319847,"enunciado":"Em razão das fortes chuvas do último mês de junho, determinada região do Município Alfa ficou totalmente alagada e muitas famílias ficaram desabrigadas. Diante do iminente perigo público, o prefeito municipal usou a propriedade privada de João, consistente em um amplo galpão que estava inutilizado, para assentar as famílias atingidas por uma semana até a solução definitiva dada ao caso. Na hipótese narrada, o prefeito se valeu da intervenção do Estado na propriedade chamada:","opcoes":["ocupação temporária, mediante prévia e justa indenização a João;","requisição administrativa, assegurada a João indenização ulterior, se houver dano;","desapropriação temporária, mediante imediata e justa indenização a João;","limitação administrativa, assegurada a João indenização ulterior, se houver dano;","servidão administrativa, assegurada a João indenização justa e posterior."],"correta":1,"explicacao":"Gabarito: <strong>requisição administrativa, assegurada a João indenização ulterior, se houver dano;</strong>.","banca":"FGV","ano":2021,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4319958,"enunciado":"Em matéria de intervenção do Estado na propriedade, a chamada desapropriação especial urbana se dá por interesse social para a política urbana. A desapropriação especial urbana é de competência:","opcoes":["concorrente dos estados, municípios e Distrito Federal, tem função sancionatória, uma vez que recai sobre imóveis urbanos que desatendam a sua função social, e há necessidade de pagamento de prévia e justa indenização;","concorrente da União, estados, municípios e Distrito Federal, tem função pedagógica, uma vez que recai sobre imóveis urbanos subutilizados, e há necessidade de pagamento de ulterior e justa indenização;","concorrente dos estados, municípios e Distrito Federal, tem função pedagógica, uma vez que recai sobre imóveis urbanos subutilizados, e há necessidade de pagamento de ulterior e justa indenização;","exclusiva dos municípios, tem função sancionatória, uma vez que recai sobre imóveis urbanos que desatendam a sua função social, e há necessidade de pagamento de prévia e justa indenização;","exclusiva dos municípios que possuem plano diretor, tem função sancionatória, uma vez que recai sobre imóveis urbanos que desatendam a sua função social, e a indenização será feita com pagamento em títulos da dívida pública de emissão previamente aprovada pelo Senado Federal."],"correta":4,"explicacao":"Gabarito: <strong>exclusiva dos municípios que possuem plano diretor, tem função sancionatória, uma vez que recai sobre imóveis urbanos que desatendam a sua função social, e a indenização será feita com pagamento em títulos da dívida pública de emissão previamente aprovada pelo Senado Federal.</strong>.","banca":"FGV","ano":2021,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}},{"id":4320126,"enunciado":"O Prefeito do Município Alfa editou decreto no qual informava que o Poder Público utilizaria, por seis meses, os serviços e as instalações do único hospital privado da região. A decisão decorreu do fato de o nosocômio ter informado que cessaria o atendimento dos pacientes do Sistema Único de Saúde, o que comprometeria o serviço de saúde no Município. À luz da sistemática legal, a situação narrada caracteriza:","opcoes":["requisição administrativa, que não exige autorização do Poder Judiciário e acarreta o dever de indenização posterior;","ocupação temporária, que exige prévia autorização do Poder Judiciário e não demanda indenização;","desapropriação, devendo ser antecedida de prévia e justa indenização;","servidão administrativa ao direito de propriedade, que exige autorização do Poder Judiciário e reembolso dos gastos;","ilegalidade, pois é típica situação de intervenção no domínio econômico, caracterizando desapropriação indireta."],"correta":0,"explicacao":"Gabarito: <strong>requisição administrativa, que não exige autorização do Poder Judiciário e acarreta o dever de indenização posterior;</strong>.","banca":"FGV","ano":2019,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4320215,"enunciado":"No caso de desapropriação por necessidade pública, é correto afirmar que","opcoes":["se dá mediante justa e prévia indenização em dinheiro, ressalvados os casos previstos na Constituição.","se dá mediante justa e prévia indenização em precatórios, ressalvados os casos previstos na Constituição.","se dá sem a necessidade de justa e prévia indenização no caso de iminente perigo ou interesse público.","é competência do Município legislar sobre desapropriações em seu território, eis que trata-se de interesse local.","poderá se dar pelo Poder Público municipal, mediante lei específica imóvel subutilizado ou não utilizado."],"correta":0,"explicacao":"Gabarito: <strong>se dá mediante justa e prévia indenização em dinheiro, ressalvados os casos previstos na Constituição.</strong>.","banca":"INDEPAC","ano":2018,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"competencia desapropriar","ancora":"competencia-desapropriar"},"B":{"topico":"competencia desapropriar","ancora":"competencia-desapropriar"},"C":{"topico":"competencia desapropriar","ancora":"competencia-desapropriar"},"D":{"topico":"competencia desapropriar","ancora":"competencia-desapropriar"},"E":{"topico":"competencia desapropriar","ancora":"competencia-desapropriar"}}},{"id":4320365,"enunciado":"Suponha que, no ano de 2005, o Estado do Rio Grande do Sul, por necessidade pública, interviu na propriedade particular desapropriando-a. O bem, incorporado ao patrimônio estatal, não foi utilizado pelo poder público até o ano de 2017. Em razão do tempo decorrido, o antigo proprietário do imóvel desapropriado solicitou o desfazimento do ato administrativo, promovendo o depósito do valor recebido a título de indenização. Nesse caso, é possível afirmar que se está diante do instituto da:","opcoes":["Expropriação.","Retrocessão.","Tredestinação lícita.","Tredestinação ilícita.","Repristinação."],"correta":1,"explicacao":"Gabarito: <strong>Retrocessão.</strong>.","banca":"FUNDATEC","ano":2018,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4320531,"enunciado":"Com objetivo de desenvolver e expandir o fornecimento de energia elétrica em determinado município, a Administração Pública verifica ser necessária a passagem de fios de eletricidade por determinada propriedade privada, impondo ao particular o dever de suportar a conduta de instalação e utilização de parte de seu bem imóvel. Sobre a hipótese, assinale a opção que indica a modalidade correta de intervenção do Estado na propriedade privada.","opcoes":["Desapropriação","Tombamento","Limitação administrativa","Ocupação temporária","Servidão administrativa"],"correta":4,"explicacao":"Gabarito: <strong>Servidão administrativa</strong>.","banca":"FGV","ano":2016,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4320615,"enunciado":"Intervenção do Estado na propriedade é toda e qualquer atividade estatal que, amparada em lei, tenha por fim ajustá-la aos inúmeros fatores exigidos pela função social a que está condicionada. De acordo com o texto constitucional, a modalidade de intervenção restritiva conhecida como requisição administrativa é o direito:","opcoes":["real público que autoriza o Poder Público a usar a propriedade imóvel para permitir a execução de obras e serviços de interesse coletivo, como o caso de instalação de redes elétricas e a implantação de gasodutos e oleodutos em áreas privadas para a execução de serviços públicos, mediante prévia e justa indenização;","pessoal da Administração Pública de, no caso de iminente perigo público, usar da propriedade particular (bens móveis, imóveis e serviços particulares) assegurada ao proprietário indenização ulterior, se houver dano, como a hipótese do uso do imóvel, dos equipamentos e dos serviços médicos de determinado hospital privado em situação de alagamento de toda a cidade em estado de calamidade pública reconhecido oficialmente, por decreto do Executivo;","real da Administração Pública de usar transitoriamente imóveis privados, como meio de apoio à execução de obras e serviços públicos ordinários, como a hipótese de utilização de terrenos particulares contíguos a estradas (em construção ou em reforma), para a alocação transitória de máquinas de asfalto, equipamentos de serviços e pequenas barracas de operários, mediante prévia e justa indenização;","pessoal da Administração Pública de expedir determinações de caráter geral, através das quais o Poder Público impõe a proprietários indeterminados obrigações positivas, negativas ou permissivas, para o fim de condicionar as propriedades ao atendimento da função social, como o caso de permissão de vistorias em elevadores de edifícios e ingresso de agentes para fins de vigilância sanitária, não havendo prévia indenização;","real da Administração Pública de expedir requisições para proteção do patrimônio cultural brasileiro, com vistas à preservação da memória nacional, da identidade social e de aspectos históricos de bens de interesse coletivo, por meio de inventários, registros, vigilância, tombamento e de outras formas de acautelamento e preservação, como a hipótese de tombamento de igreja centenária ou de ruínas com relevante interesse arqueológico."],"correta":2,"explicacao":"Gabarito: <strong>real da Administração Pública de usar transitoriamente imóveis privados, como meio de apoio à execução de obras e serviços públicos ordinários, como a hipótese de utilização de terrenos particulares contíguos a estradas (em construção ou em reforma), para a alocação transitória de máquinas de asfalto, equipamentos de serviços e pequenas barracas de operários, mediante prévia e justa indenização;</strong>.","banca":"FGV","ano":2015,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"B":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"C":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"D":{"topico":"tombamento conceito","ancora":"tombamento-conceito"},"E":{"topico":"tombamento conceito","ancora":"tombamento-conceito"}}},{"id":4320638,"enunciado":"Sobre desapropriação, assinale a afirmativa correta.","opcoes":["A tredestinação vem a ser a desapropriação parcial do bem.","O direito de penetração confunde-se com a imissão provisória na posse.","A desapropriação é a forma de aquisição derivada da propriedade, segundo a doutrina majoritária.","A declaração de urgência e o depósito prévio do valor são pressupostos que permitem ao expropriante a imissão provisória na posse.","A desapropriação indireta resulta de ato considerado lícito da Administração, quando os dois requisitos constitucionais essenciais – a declaração e a justa indenização – foram observados."],"correta":3,"explicacao":"Gabarito: <strong>A declaração de urgência e o depósito prévio do valor são pressupostos que permitem ao expropriante a imissão provisória na posse.</strong>.","banca":"FGV","ano":2015,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"B":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"C":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"D":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"},"E":{"topico":"tredestinacao retrocessao","ancora":"tredestinacao-retrocessao"}}},{"id":4320696,"enunciado":"A Constituição da República estabelece no Art. , XX , que “no caso de iminente perigo público, a autoridade competente poderá usar de propriedade particular, assegurada ao proprietário indenização ulterior, se houver dano”. Com base em tal norma, diante de uma situação de iminente calamidade pública em cidade do interior do Estado, o Poder Público municipal usou do imóvel, dos equipamentos e dos serviços médicos de determinado hospital privado. Trata-se da modalidade de intervenção do Estado na propriedade da:","opcoes":["servidão administrativa;","requisição administrativa;","ocupação temporária;","limitação administrativa;","desapropriação intermediária."],"correta":1,"explicacao":"Gabarito: <strong>requisição administrativa;</strong>.","banca":"FGV","ano":2015,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4320710,"enunciado":"Quanto ao instituto da desapropriação, assinale a afirmativa correta.","opcoes":["O direito de extensão apenas é possível na desapropriação por interesse social.","A desapropriação indireta se dá quando há apossamento indevido e temporário de bem particular pelo Poder Público.","Na ação de desapropriação para efeitos de reforma agrária não pode haver condenação em honorários advocatícios.","O Poder Público possui o direito de desistir da desapropriação, mesmo que tenha dado causa à total inviabilidade econômica do bem, desde que o faça antes trânsito em julgado da sentença.","O Direito de Penetração é reconhecido na desapropriação e pode gerar o dever de indenização pelo Poder Público expropriante, caso tenha se feito abusivamente."],"correta":1,"explicacao":"Gabarito: <strong>A desapropriação indireta se dá quando há apossamento indevido e temporário de bem particular pelo Poder Público.</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"direito extensao","ancora":"direito-extensao"},"B":{"topico":"direito extensao","ancora":"direito-extensao"},"C":{"topico":"direito extensao","ancora":"direito-extensao"},"D":{"topico":"direito extensao","ancora":"direito-extensao"},"E":{"topico":"direito extensao","ancora":"direito-extensao"}}},{"id":4320717,"enunciado":"Sobre a intervenção do Estado na propriedade, assinale a afirmativa correta.","opcoes":["O tombamento importa em limitação temporária ao direito de propriedade em prol do interesse coletivo, afetando o caráter absoluto desse direito.","A servidão administrativa importa na instituição de um direito pessoal, fazendo com que o proprietário suporte um ônus ilimitado sobre o imóvel de sua propriedade, em prol de um serviço público. Afeta a exclusividade do direito de propriedade","As limitações administrativas importam em obrigações de caráter geral a proprietários indeterminados, em prol do interesse geral, e afeta o caráter absoluto do direito de propriedade","A desapropriação atinge apenas a faculdade de disposição que o proprietário tem sobre a coisa e importa em transferência compulsória da propriedade para satisfazer a interesse público, mediante o pagamento de uma indenização.","A requisição de imóveis impõe ao proprietário a obrigação de suportar a utilização perpétua de imóvel pelo poder público, diante da utilização inadequada dada pelo proprietário à sua propriedade."],"correta":2,"explicacao":"Gabarito: <strong>As limitações administrativas importam em obrigações de caráter geral a proprietários indeterminados, em prol do interesse geral, e afeta o caráter absoluto do direito de propriedade</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4320791,"enunciado":"Um Município foi atingido por extraordinárias e fortes chuvas no mês de janeiro de 2014, que deixaram centenas de desabrigados. Em razão do iminente perigo público, inclusive diante da necessidade de remoção de diversas famílias que moravam em área de risco, a administração pública municipal, após a lotação dos prédios públicos disponíveis, viu-se obrigada a utilizar o prédio de uma escola particular. Por não concordar com a medida, João, o proprietário da escola particular, buscou orientação jurídica, sendo informado de que se tratava de estado de calamidade pública, reconhecido por decreto municipal, que autorizava a intervenção do Estado na propriedade particular, com vistas à satisfação do interesse público. O instituto em tela se chama .","opcoes":["servidão administrativa, tendo o particular direito à posterior indenização, se houver dano.","requisição, tendo o particular direito à indenização ulterior, se houver dano.","ocupação temporária, tendo o particular direito à posterior indenização, se houver dano.","ocupação temporária, tendo o particular direito à prévia indenização, independentemente da comprovação do dano.","limitação administrativa, tendo o particular direito à indenização ulterior, independentemente da comprovação do dano."],"correta":1,"explicacao":"Gabarito: <strong>requisição, tendo o particular direito à indenização ulterior, se houver dano.</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"B":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"C":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"D":{"topico":"servidao administrativa","ancora":"servidao-administrativa"},"E":{"topico":"servidao administrativa","ancora":"servidao-administrativa"}}},{"id":4320797,"enunciado":"Proprietário de um imóvel urbano não edificado, situado no centro de uma cidade no Estado do Rio de Janeiro, João foi informado por vizinhos de que o poder público municipal poderia adotar várias medidas legais em razão da não edificação do solo urbano. Argumentando que a Constituição da República protege seu direito fundamental à propriedade, João buscou assistência jurídica, e lhe foi esclarecido que a Constituição prevê que o Município, mediante lei específica para a área em questão, incluída no plano diretor, pode exigir, nos termos da lei federal, que o particular promova o adequado aproveitamento do solo urbano. Permanecendo sua omissão, João está sujeito à pena, sucessivamente, de (I) parcelamento ou edificação compulsórios; (II) imposto sobre a propriedade predial e territorial urbana progressivo no tempo; e (III) desapropriação, que ocorre","opcoes":["mediante justa e prévia indenização em dinheiro, observado o procedimento legal que possui duas fases: a declaratória e a executória.","sem qualquer indenização, na modalidade urbanística sancionatória, desde que o imóvel passe a ser destinado a atender ao interesse público, na forma da lei.","com indenização apenas pelas benfeitorias, desde que haja necessidade ou utilidade pública, ou interesse social, observado o procedimento legal que possui duas fases: a declaratória e a executória.","com pagamento mediante títulos da dívida pública de emissão previamente aprovada pelo Senado Federal, com prazo de resgate de até dez anos, em parcelas anuais, iguais e sucessivas, assegurados o valor real da indenização e os juros legais.","mediante pagamento posterior, com títulos da dívida pública municipal com prazo de resgate de até cinco anos, em parcelas anuais, iguais e sucessivas, assegurados o valor real da indenização e os juros legais."],"correta":3,"explicacao":"Gabarito: <strong>com pagamento mediante títulos da dívida pública de emissão previamente aprovada pelo Senado Federal, com prazo de resgate de até dez anos, em parcelas anuais, iguais e sucessivas, assegurados o valor real da indenização e os juros legais.</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"},"B":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"},"C":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"},"D":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"},"E":{"topico":"fases desapropriacao","ancora":"fases-desapropriacao"}}},{"id":4320800,"enunciado":"Após publicação do Decreto estadual n. 1234, que declarou de utilidade pública o imóvel empregado por Fulano de Tal como restaurante, o Estado X iniciou as tratativas para desapropriação administrativa do imóvel. Não foi possível, entretanto, o acordo, uma vez que o proprietário, tendo contraído diversas dívidas, não aceitou o valor ofertado pelo Estado. Por essa razão, foi ajuizada ação de desapropriação em face de Fulano de Tal, com pedido de imissão provisória na posse. Diante do exposto, assinale a afirmativa correta.","opcoes":["Em se tratando de imóvel urbano não residencial, utilizado para fins comerciais, não se admite a imissão provisória na posse.","A desapropriação deve ser precedida da declaração de utilidade pública, a ser feita por lei, e não por decreto.","Somente a União está autorizada a promover desapropriação por utilidade pública, razão pela qual é inválido o decreto estadual.","Ficam subrogados no preço quaisquer ônus ou direitos que recaiam sobre o bem expropriado.","A ação deve ser proposta em face do proprietário do imóvel e de todos os seus credores, uma vez que terão seu crédito atingido por eventual sentença de procedência."],"correta":3,"explicacao":"Gabarito: <strong>Ficam subrogados no preço quaisquer ônus ou direitos que recaiam sobre o bem expropriado.</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"B":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"C":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"D":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"},"E":{"topico":"imissao provisoria posse","ancora":"imissao-provisoria-posse"}}},{"id":4320896,"enunciado":"A imposição de limitação de construir acima de determinado número de andares, para garantir a visibilidade de bem tombado, é denominada","opcoes":["limitação administrativa.","desapropriação indireta.","servidão administrativa.","requisição administrativa.","tombamento indireto."],"correta":0,"explicacao":"Gabarito: <strong>limitação administrativa.</strong>.","banca":"FGV","ano":2013,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4320935,"enunciado":"No que tange à intervenção do Estado na propriedade privada, a mais drástica dessas medidas é a desapropriação. Com relação a essa modalidade de intervenção é correto afirmar que:","opcoes":["os bens gravados com inalienabilidade não poderão ser desapropriados.","a desapropriação do imóvel urbano por descumprimento de sua função social será indenizada previamente e em dinheiro.","a desapropriação do imóvel rural por descumprimento de sua função social será indenizada previamente e em dinheiro.","uma vez consolidada a desapropriação indireta, o proprietário não poderá reaver o imóvel restando-lhe apenas buscar sua indenização.","somente a administração direta poderá mover a ação de desapropriação."],"correta":3,"explicacao":"Gabarito: <strong>uma vez consolidada a desapropriação indireta, o proprietário não poderá reaver o imóvel restando-lhe apenas buscar sua indenização.</strong>.","banca":"FGV","ano":2013,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"B":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"C":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"D":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"},"E":{"topico":"desapropriacao indireta","ancora":"desapropriacao-indireta"}}},{"id":4320963,"enunciado":"A respeito das modalidades de intervenção do Estado na propriedade, analise as afirmativas a seguir: I. O prazo de caducidade do decreto expropriatório nas desapropriações por utilidade pública é de cinco anos, contados da data de sua expedição. II. A ocupação temporária de terrenos vizinhos não edificados, vizinhos às obras públicas e necessários à sua realização, depende de decreto de declaração de necessidade e prévia indenização. III. A desapropriação de bens pela União Federal efetiva-se após processo administrativo, sempre mediante justa indenização em títulos da dívida pública de emissão previamente aprovada pelo Senado Federal. Assinale","opcoes":["se apenas a afirmativa I estiver correta.","se apenas a afirmativa II estiver correta.","se apenas a afirmativa III estiver correta.","se apenas as afirmativas I e II estiverem corretas.","se apenas as afirmativas I e III estiverem corretas."],"correta":0,"explicacao":"Gabarito: <strong>se apenas a afirmativa I estiver correta.</strong>.","banca":"FGV","ano":2011,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"B":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"C":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"D":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"},"E":{"topico":"caducidade decreto desapropriacao","ancora":"caducidade-decreto-desapropriacao"}}},{"id":4320976,"enunciado":"A Constituição Federal garante o direito de propriedade, mas exige que a mesma atenda à sua função social. Sob esses pressupostos, assinale a alternativa que não corresponde ao regime constitucional da propriedade e da desapropriação.","opcoes":["A desapropriação por necessidade ou utilidade pública, ou por interesse social, depende de prévia e justa indenização em dinheiro.","As glebas onde forem localizadas culturas ilegais de plantas psicotrópicas podem ser expropriadas com pagamento indenizatório a ser efetivado por títulos da dívida agrária resgatáveis em até 30 anos.","A propriedade urbana não edificada, subutilizada ou não utilizada pode vir a ser submetida à desapropriação com pagamento indenizatório a ser efetivado por títulos da dívida pública resgatáveis em até 10 anos.","O imóvel rural que não esteja cumprindo sua função social pode ser submetido à desapropriação por interesse social, para fins de reforma agrária, com pagamento indenizatório a ser efetivado por títulos da dívida agrária resgatáveis em até 20 anos.","Os imóveis públicos não podem ser adquiridos por usucapião."],"correta":4,"explicacao":"Gabarito: <strong>Os imóveis públicos não podem ser adquiridos por usucapião.</strong>.","banca":"IADES","ano":2011,"temas_relacionados":["intervencao_estado_propriedade"],"indicadores_teoria":{"A":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"B":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"C":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"D":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"},"E":{"topico":"conceito desapropriacao","ancora":"conceito-desapropriacao"}}}];
